// Consent_Choice on the device (Req 17.1-17.8). Stored in `sf.consent` as
// { id, purposes: { analytics, marketing_tags }, version, at, synced }; the inline head script reads `purposes.analytics`.
// Until a choice for the current privacy notice version exists, every purpose is refused.
import { declineLook, type ControlLook } from './honesty';
import { deleteTagCookies } from './marketing';
import { getJson, removeItem, setAnalyticsConsent, setJson } from './storage';

export interface Purposes {
  analytics: boolean;
  marketing_tags: boolean;
}

export interface StoredConsent {
  id: string;
  purposes: Purposes;
  version: string;
  at: number;
  /** False until `api.store_record_consent` accepted the choice; it is retried on the next page. */
  synced: boolean;
}

/** Version of the privacy notice; a different stored version means the shopper is asked again (Req 17.7). */
export const NOTICE_VERSION: string =
  ((import.meta as unknown as { env?: Record<string, string | undefined> }).env?.PUBLIC_PRIVACY_NOTICE_VERSION ?? '').trim() || 'v1';

export const REFUSED: Purposes = { analytics: false, marketing_tags: false };

/** The three banner buttons share one look (Req 17.2, 11.23). */
export const BUTTON_LOOK: ControlLook = { className: 'pm-button pm-button--secondary pm-consent__button', minSize: 44, color: 'var(--pm-brand)', background: 'var(--pm-bg)' };
export const buttonLooks = (): { accept: ControlLook; necessary: ControlLook; choose: ControlLook } => ({
  accept: BUTTON_LOOK,
  necessary: declineLook(BUTTON_LOOK),
  choose: declineLook(BUTTON_LOOK),
});

const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;

/** The stored choice, or null when none was recorded or it is for another notice version. */
export function readConsent(version = NOTICE_VERSION): StoredConsent | null {
  const c = getJson<Partial<StoredConsent>>('sf.consent');
  if (!c || typeof c !== 'object') return null;
  const p = c.purposes;
  if (typeof c.id !== 'string' || !UUID.test(c.id) || !p || typeof p.analytics !== 'boolean' || typeof p.marketing_tags !== 'boolean') return null;
  if (c.version !== version) return null;
  return { id: c.id, purposes: { analytics: p.analytics, marketing_tags: p.marketing_tags }, version: c.version, at: Number(c.at) || 0, synced: c.synced === true };
}

/** Purposes in force: refused until a current choice exists. */
export const currentPurposes = (version = NOTICE_VERSION): Purposes => readConsent(version)?.purposes ?? { ...REFUSED };

function consentId(): string {
  const old = getJson<{ id?: unknown }>('sf.consent');
  return typeof old?.id === 'string' && UUID.test(old.id) ? old.id : globalThis.crypto.randomUUID();
}

/** Removes the identifiers of purposes that are off and tells the page (Req 17.8). */
export function applyPurposes(p: Purposes): void {
  setAnalyticsConsent(p.analytics); // removes sf.sid, sf.exp and sf.events when off
  if (!p.analytics && typeof document !== 'undefined') document.documentElement.removeAttribute('data-pm-exp');
  if (!p.marketing_tags && typeof document !== 'undefined') deleteTagCookies(); // Marketing_Tag identifiers go with the consent (Req 17.7)
  if (typeof document !== 'undefined') document.dispatchEvent(new CustomEvent('pm:consent', { detail: { ...p } }));
}

export type RecordFn = (args: { p_consent_id: string; p_analytics: boolean; p_marketing_tags: boolean; p_notice_version: string }) => Promise<unknown>;

/** Saves the choice on the device, applies it, then records it through `api.store_record_consent`. */
export async function saveConsent(purposes: Purposes, record: RecordFn, now = Date.now(), version = NOTICE_VERSION): Promise<StoredConsent> {
  const c: StoredConsent = { id: consentId(), purposes: { ...purposes }, version, at: now, synced: false };
  setJson('sf.consent', c);
  applyPurposes(c.purposes);
  return syncConsent(c, record);
}

/** Sends a choice not yet recorded; failure leaves it for the next page. */
export async function syncConsent(c: StoredConsent, record: RecordFn): Promise<StoredConsent> {
  if (c.synced) return c;
  try {
    await record({ p_consent_id: c.id, p_analytics: c.purposes.analytics, p_marketing_tags: c.purposes.marketing_tags, p_notice_version: c.version });
  } catch {
    return c;
  }
  const done = { ...c, synced: true };
  // Keep a newer choice if the shopper changed it while the request was in flight.
  const now = getJson<StoredConsent>('sf.consent');
  if (now && now.id === c.id && now.at === c.at) setJson('sf.consent', done);
  return done;
}

/** Applies the stored choice at page load; returns whether the banner is due. */
export function initConsent(version = NOTICE_VERSION): { due: boolean; consent: StoredConsent | null } {
  const consent = readConsent(version);
  applyPurposes(consent?.purposes ?? REFUSED);
  return { due: consent === null, consent };
}

/** Test and recovery helper: forgets the choice on this device. */
export const clearConsent = (): void => removeItem('sf.consent');
