// Build-time helper: collects the social proof and trust text from the dictionaries (keys `social.*`).
import { t, type Locale } from '../lib/i18n';

const KEYS = [
  'rating', 'ratingCount', 'highlightsTitle', 'highlightPositive', 'highlightCritical', 'highlightBy', 'popularity', 'lowStock',
  'trustLabel', 'securePayment', 'cod', 'returns', 'gstInvoice', 'origin',
] as const;

export type SocialLabels = Record<(typeof KEYS)[number], string>;

export const socialLabels = (locale: Locale): SocialLabels =>
  Object.fromEntries(KEYS.map((k) => [k, t(locale, `social.${k}`)])) as SocialLabels;
