// Build-time: the PLP's interface text from the dictionaries (keys under `plp.*`), passed to the island as JSON.
import { t, type Locale } from './i18n';
import { isBadgeKey } from './badges';
import type { CardLabels } from './plp-card';

const BADGES = ['sale', 'new', 'best_seller', 'low_stock', 'free_delivery', 'made_in_india'] as const;

export function cardLabels(locale: Locale): CardLabels {
  return {
    from: t(locale, 'plp.from'),
    priceOnRequest: t(locale, 'plp.priceOnRequest'),
    save: t(locale, 'plp.save'),
    moreColours: t(locale, 'plp.moreColours'),
    chooseOptions: t(locale, 'plp.chooseOptions'),
    unavailable: t(locale, 'plp.unavailable'),
    addToCart: t(locale, 'plp.addToCart'),
    quickView: t(locale, 'plp.quickView'),
    quickViewFor: t(locale, 'plp.quickViewFor'),
    viewFull: t(locale, 'plp.viewFull'),
    srCurrent: t(locale, 'plp.srCurrent'),
    srPrior: t(locale, 'plp.srPrior'),
    badges: Object.fromEntries(BADGES.filter(isBadgeKey).map((b) => [b, t(locale, `plp.badge.${b}`)])),
  };
}

const UI_KEYS = [
  'showResultsNone', 'applyLoading', 'removeFilter', 'showing', 'loading', 'loaded', 'empty', 'emptyHint', 'error', 'retry',
  'categories', 'collections', 'tags', 'types', 'priceMin', 'priceMax', 'filtersApplied', 'filters', 'loadMore',
] as const;

/** Text the island needs; plural forms are resolved in the browser from `one` and `other`. */
export function plpUiLabels(locale: Locale) {
  const base = Object.fromEntries(UI_KEYS.map((k) => [k, t(locale, `plp.${k}`)])) as Record<(typeof UI_KEYS)[number], string>;
  return {
    ...base,
    showResultsOne: t(locale, 'plp.showResults.one'),
    showResultsOther: t(locale, 'plp.showResults.other'),
    productCountOne: t(locale, 'plp.productCount.one'),
    productCountOther: t(locale, 'plp.productCount.other'),
  };
}
export type PlpUiLabels = ReturnType<typeof plpUiLabels>;
