// Shared Live_Data reader for the delivery and countdown islands: fetches, keeps a server-time clock, and refetches on demand.
import { useCallback, useEffect, useRef, useState } from 'preact/hooks';
import { createServerClock, pickLiveDelivery, type LiveDelivery, type ServerClock } from '../lib/delivery';
import { LIVE_TIMEOUT_MS, pageLiveClient } from '../lib/live-client';

export { LIVE_TIMEOUT_MS };
const DEFAULT_MAX_AGE_S = 60;

export interface LiveState {
  /** loading: nothing yet; ready: current evidence; stale: no response in 8 seconds or older than the maximum age. */
  status: 'loading' | 'ready' | 'stale';
  data: LiveDelivery | null;
  clock: ServerClock | null;
  /** Refetches Live_Data now. */
  refetch: () => void;
}

/** `initialBody` is a pre-supplied Live_Data response (a fixture or a server render); `liveUrl` null reads nothing. */
export function useLiveDelivery(
  liveUrl: string | null,
  productId: string,
  variantId: string,
  initialBody: unknown = null,
): LiveState {
  const [state, setState] = useState<Omit<LiveState, 'refetch'>>(() => {
    const delivery = initialBody ? pickLiveDelivery(initialBody, productId, variantId) : null;
    const clock = delivery?.serverTime ? createServerClock(delivery.serverTime) : null;
    return delivery && clock
      ? { status: 'ready', data: delivery, clock }
      : { status: liveUrl ? 'loading' : 'stale', data: null, clock: null };
  });
  const [tick, setTick] = useState(0);
  const loadedAt = useRef<number | null>(state.status === 'ready' ? performance.now() : null);
  const maxAgeMs = useRef(DEFAULT_MAX_AGE_S * 1000);

  const refetch = useCallback(() => setTick((n) => n + 1), []);

  useEffect(() => {
    if (!liveUrl) return;
    let cancelled = false;
    // The page's shared Live_Island client sends one request per page, with the Supabase fallback (Req 1.12).
    const load = () => {
      void pageLiveClient()
        .load(liveUrl)
        .then((res) => {
          if (cancelled) return;
          const body = res.status === 'ready' ? res.body : null;
          const delivery = body ? pickLiveDelivery(body, productId, variantId) : null;
          const clock = delivery?.serverTime ? createServerClock(delivery.serverTime) : null;
          if (!delivery || !clock) return markStale();
          maxAgeMs.current = res.maxAgeMs;
          loadedAt.current = performance.now();
          setState({ status: 'ready', data: delivery, clock });
        })
        .catch(() => !cancelled && markStale());
    };
    // A failed refresh only hides the evidence once the last good response is older than the maximum age.
    const markStale = () =>
      setState((cur) =>
        loadedAt.current !== null && performance.now() - loadedAt.current <= maxAgeMs.current
          ? cur
          : { status: 'stale', data: null, clock: null },
      );
    load();
    // Keep the evidence current while the page stays open.
    const every = setInterval(() => document.visibilityState === 'visible' && load(), maxAgeMs.current);
    return () => {
      cancelled = true;
      clearInterval(every);
    };
  }, [liveUrl, productId, variantId, tick]);

  return { ...state, refetch };
}

/** True while the element is on screen and the tab is visible; the clock ticks only then. */
export function useVisible(ref: { current: Element | null }): boolean {
  const [inView, setInView] = useState(true);
  const [tabVisible, setTabVisible] = useState(() => typeof document === 'undefined' || document.visibilityState === 'visible');
  useEffect(() => {
    const onVis = () => setTabVisible(document.visibilityState === 'visible');
    document.addEventListener('visibilitychange', onVis);
    let io: IntersectionObserver | null = null;
    if (ref.current && 'IntersectionObserver' in window) {
      io = new IntersectionObserver((entries) => setInView(entries.some((e) => e.isIntersecting)));
      io.observe(ref.current);
    }
    return () => {
      document.removeEventListener('visibilitychange', onVis);
      io?.disconnect();
    };
  }, [ref]);
  return inView && tabVisible;
}

export function usePrefersReducedMotion(): boolean {
  const [reduced, setReduced] = useState(() => typeof matchMedia === 'function' && matchMedia('(prefers-reduced-motion: reduce)').matches);
  useEffect(() => {
    if (typeof matchMedia !== 'function') return;
    const mq = matchMedia('(prefers-reduced-motion: reduce)');
    const on = () => setReduced(mq.matches);
    mq.addEventListener('change', on);
    return () => mq.removeEventListener('change', on);
  }, []);
  return reduced;
}
