import en from '../i18n/en.json';
import hi from '../i18n/hi.json';

export type Locale = 'en' | 'hi';
export const LOCALES: readonly Locale[] = ['en', 'hi'];
export const DEFAULT_LOCALE: Locale = 'en';
const dictionaries: Record<Locale, unknown> = { en, hi };

const RTL_LOCALES: Locale[] = []; // en and hi are both left-to-right

export function dir(locale: Locale): 'ltr' | 'rtl' {
  return RTL_LOCALES.includes(locale) ? 'rtl' : 'ltr';
}

type Flatten<T, P extends string = ''> = {
  [K in keyof T & string]: T[K] extends string ? `${P}${K}` : Flatten<T[K], `${P}${K}.`>;
}[keyof T & string];

/** Every dotted key of en.json, including plural forms such as `cart.items.other`. */
export type MessageKey = Flatten<typeof en>;
/** Keys that have plural forms: `cart.items` for `cart.items.one` and `cart.items.other`. */
export type PluralKey = MessageKey extends infer K ? (K extends `${infer P}.other` ? P : never) : never;
/** Typed keys with autocomplete; any other string is still accepted and falls back to itself. */
export type KeyInput = MessageKey | (string & {});

export type Params = Record<string, string | number>;
export type PluralCategory = 'zero' | 'one' | 'two' | 'few' | 'many' | 'other';

const INTL_LOCALE: Record<Locale, string> = { en: 'en-IN', hi: 'hi-IN' };

/** Type guard for the two Storefront_Languages. */
export function isLocale(value: unknown): value is Locale {
  return value === 'en' || value === 'hi';
}

function lookup(d: unknown, key: string): unknown {
  let cur: unknown = d;
  for (const part of key.split('.')) {
    if (cur && typeof cur === 'object' && Object.prototype.hasOwnProperty.call(cur, part)) {
      cur = (cur as Record<string, unknown>)[part];
    } else return undefined;
  }
  return cur;
}

const lookupString = (d: unknown, key: string): string | undefined => {
  const v = lookup(d, key);
  return typeof v === 'string' ? v : undefined;
};

/** Replaces `{name}` placeholders; a placeholder with no value stays as written. */
export function interpolate(template: string, params?: Params): string {
  if (!params) return template;
  return template.replace(/\{(\w+)\}/g, (m, name: string) =>
    Object.prototype.hasOwnProperty.call(params, name) ? String(params[name]) : m,
  );
}

/**
 * Interface text from the dictionary. Fallback: the locale's text, then English, then the key.
 * `{name}` placeholders are filled from `params`.
 */
export function t(locale: Locale, key: KeyInput, params?: Params): string {
  const text = lookupString(dictionaries[locale], key) ?? lookupString(dictionaries.en, key) ?? key;
  return interpolate(text, params);
}

/**
 * Plural category of `count` in the locale (CLDR): English has `one` for 1 only;
 * Hindi has `one` for 0 and 1 (and for fractions below 2).
 */
export function pluralCategory(locale: Locale, count: number): PluralCategory {
  return new Intl.PluralRules(INTL_LOCALE[locale]).select(count) as PluralCategory;
}

/**
 * Plural text: `key` names an object with the category forms (`one`, `other`, ...).
 * Fallback per form: the locale's category, the locale's `other`, English's category, English's `other`, the key.
 * `{count}` is always available to the template.
 */
export function tn(locale: Locale, key: PluralKey | (string & {}), count: number, params?: Params): string {
  const cat = pluralCategory(locale, count);
  const enCat = pluralCategory('en', count);
  const text =
    lookupString(dictionaries[locale], `${key}.${cat}`) ??
    lookupString(dictionaries[locale], `${key}.other`) ??
    lookupString(dictionaries.en, `${key}.${locale === 'en' ? cat : enCat}`) ??
    lookupString(dictionaries.en, `${key}.other`) ??
    key;
  return interpolate(text, { count, ...params });
}

const DEVANAGARI = /[\u0900-\u097F]/;

/** Whether text contains Devanagari characters. */
export function hasDevanagari(text: string): boolean {
  return DEVANAGARI.test(text);
}

/** Language to mark store content with (`lang` attribute): `hi` for Devanagari text and `en` otherwise (Req 5.6). */
export function contentLang(text: string): Locale {
  return hasDevanagari(text) ? 'hi' : 'en';
}
