// Goes_Well_With on the PDP (Req 9.1, 11.13): each paired product has its own add control. A product with one variant goes
// straight to the Cart; one with several opens its page so the shopper chooses.
import { useState } from 'preact/hooks';
import { GoesWellWith } from './BasketJourney';
import type { JourneyLabels } from './journey-labels';
import type { FormatLocale } from '../lib/format';
import type { JourneyProduct } from '../lib/basket-journey';

export interface PdpGoesWellProps {
  locale: FormatLocale;
  labels: JourneyLabels;
  currency: string;
  self: string;
  paired: (JourneyProduct & { variantId: string | null })[];
  switchOn?: boolean;
  errorText: string;
}

export default function PdpGoesWell({ locale, labels, currency, self, paired, switchOn = true, errorText }: PdpGoesWellProps) {
  const [error, setError] = useState('');
  const onAdd = async (id: string) => {
    const p = paired.find((x) => x.id === id);
    if (!p) return;
    if (!p.variantId) {
      if (p.url) location.assign(p.url);
      return;
    }
    setError('');
    try {
      const cart = await import('../lib/cart/store');
      if (!(await cart.addItem(p.id, p.variantId, 1))) setError(errorText);
    } catch {
      setError(errorText);
    }
  };
  return (
    <div>
      <GoesWellWith locale={locale} labels={labels} currency={currency} self={self} paired={paired} onAdd={(id) => void onAdd(id)} switchOn={switchOn} />
      <p class="pm-error" role="alert" hidden={!error}>{error}</p>
    </div>
  );
}
