// Navigation and search helpers (Req 7.2, 7.4, 7.7). Pure, so they run at build time and in the browser.
import type { CategoryRow } from './pdp';
import { categoryPath } from './pdp';

export const SUGGEST_MIN_CHARS = 2;
export const SUGGEST_DELAY_MS = 250;
export const SUGGEST_PRODUCTS = 6;
export const SUGGEST_CATEGORIES = 4;
export const RECENT_SEARCHES = 5;
const MAX_QUERY = 100;

/** The text a search uses: trimmed, whitespace collapsed, and cut to 100 characters. */
export const cleanQuery = (q: string): string => q.replace(/\s+/g, ' ').trim().slice(0, MAX_QUERY);

/** True once the query is long enough to ask for suggestions. */
export const canSuggest = (q: string): boolean => [...cleanQuery(q)].length >= SUGGEST_MIN_CHARS;

export interface Segment { text: string; match: boolean }

/** Splits `text` into parts, marking the parts that match a word of the query (case-insensitive). */
export function highlight(text: string, query: string): Segment[] {
  const words = [...new Set(cleanQuery(query).toLowerCase().split(' ').filter(Boolean))].sort((a, b) => b.length - a.length);
  if (!text) return [];
  if (!words.length) return [{ text, match: false }];
  const lower = text.toLowerCase();
  // toLowerCase can change the length of a few characters; then marking by index would be wrong, so show the text plain.
  if (lower.length !== text.length) return [{ text, match: false }];
  const marked = new Array<boolean>(text.length).fill(false);
  for (const w of words) {
    for (let at = lower.indexOf(w); at !== -1; at = lower.indexOf(w, at + w.length)) marked.fill(true, at, at + w.length);
  }
  const out: Segment[] = [];
  for (let i = 0; i < text.length; i++) {
    const last = out[out.length - 1];
    if (last && last.match === marked[i]) last.text += text[i];
    else out.push({ text: text[i], match: marked[i] });
  }
  return out;
}

const escapeHtml = (s: string): string =>
  s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');

/** HTML of `text` with the matched parts in `<mark>`; every part is escaped. */
export const highlightHtml = (text: string, query: string): string =>
  highlight(text, query).map((s) => (s.match ? `<mark>${escapeHtml(s.text)}</mark>` : escapeHtml(s.text))).join('');

export interface MenuCategory { id: string; name: string; path: string; children: { id: string; name: string; path: string }[] }

/** Top-level categories in the store's order, each with its subcategories (Req 7.2). */
export function menuTree(rows: readonly CategoryRow[]): MenuCategory[] {
  const item = (r: CategoryRow) => ({ id: r.id, name: r.name || r.handle, path: categoryPath(rows, r.id) });
  return rows.filter((r) => !r.parent).map((r) => ({ ...item(r), children: rows.filter((c) => c.parent === r.id).map(item) }));
}

export interface SuggestCategory { name: string; path: string }

/** Up to 4 categories whose name contains every word of the query. */
export function matchCategories(rows: readonly CategoryRow[], query: string, max = SUGGEST_CATEGORIES): SuggestCategory[] {
  const words = cleanQuery(query).toLowerCase().split(' ').filter(Boolean);
  if (!words.length) return [];
  return rows
    .filter((r) => words.every((w) => (r.name || '').toLowerCase().includes(w)))
    .slice(0, max)
    .map((r) => ({ name: r.name || r.handle, path: categoryPath(rows, r.id) }));
}

/** The stored list of searches, cleaned: strings only, no repeats, at most 5. */
export function parseSearches(raw: unknown): string[] {
  if (!Array.isArray(raw)) return [];
  const seen = new Set<string>();
  const out: string[] = [];
  for (const x of raw) {
    if (typeof x !== 'string') continue;
    const q = cleanQuery(x);
    if (!q || seen.has(q.toLowerCase())) continue;
    seen.add(q.toLowerCase());
    out.push(q);
    if (out.length === RECENT_SEARCHES) break;
  }
  return out;
}

/** Puts a search at the front of the list, without repeats, keeping the last 5. */
export function addSearch(list: readonly string[], query: string): string[] {
  const q = cleanQuery(query);
  if (!q) return parseSearches([...list]);
  return parseSearches([q, ...list]);
}
