// Build-time helpers: collect the delivery and countdown interface text from the dictionaries (keys `delivery.*`, `countdown.*`).
import { t, type Locale } from '../lib/i18n';

const COUNTDOWN_KEYS = ['saleEndsIn', 'saleThen', 'saleEndsAt', 'saleEnded', 'srSale', 'dispatchWithin', 'srDispatch'] as const;
const DELIVERY_KEYS = [
  'pinLabel', 'pinHint', 'check', 'checking', 'change', 'forPin', 'between', 'workingDays', 'workingDaysOne', 'notServiceable',
  'noEstimate', 'codYes', 'codNo', 'error', 'pinInvalid', 'unknownCountry',
] as const;

export type CountdownLabels = Record<(typeof COUNTDOWN_KEYS)[number], string>;
export type DeliveryLabels = Record<(typeof DELIVERY_KEYS)[number], string>;

export const countdownLabels = (locale: Locale): CountdownLabels =>
  Object.fromEntries(COUNTDOWN_KEYS.map((k) => [k, t(locale, `countdown.${k}`)])) as CountdownLabels;

export const deliveryLabels = (locale: Locale): DeliveryLabels =>
  Object.fromEntries(DELIVERY_KEYS.map((k) => [k, t(locale, `delivery.${k}`)])) as DeliveryLabels;

/** Fills `{name}` placeholders. */
export const fill = (s: string, p: Record<string, string>): string => s.replace(/\{(\w+)\}/g, (m, k: string) => p[k] ?? m);
