// Review_Summary, Review_Highlights, Popularity_Notice, Low_Stock_Notice and Trust_Strip (Req 11.2-11.5, 11.12, 11.21, 2.4).
// Each renders only from complete current evidence and nothing otherwise. The two live notices hide under the stale
// rule (no answer in 8 seconds or older than the Live_Data_Max_Age). Their text comes from the evidence, never a literal.
import { useEffect, useState } from 'preact/hooks';
import { formatCount, formatNumber, type FormatLocale } from '../lib/format';
import { pageLiveClient } from '../lib/live-client';
import {
  formatRating, parseReviewSummary, parseReviews, pickHighlights, pickLiveSocial, trustItems,
  type LiveVariantEvidence, type ReviewEvidence, type TrustEvidence,
} from '../lib/social-proof';
import { fill } from './delivery-labels';
import type { SocialLabels } from './social-labels';

interface Common { locale: FormatLocale; labels: SocialLabels; switchOn?: boolean }

/** Review_Summary: the average to 1 decimal and the number of published reviews, for at least 1 review. */
export function ReviewSummary({ locale, labels, evidence, switchOn = true }: Common & { evidence: unknown }) {
  const s = switchOn ? parseReviewSummary(evidence) : null;
  if (!s) return null;
  return (
    <p class="pm-review-summary">
      <span aria-hidden="true">★</span>{' '}
      <span>{fill(labels.rating, { average: formatRating(s.average) })}</span>{' '}
      <span>{fill(labels.ratingCount, { count: formatCount(s.count, locale) })}</span>
    </p>
  );
}

function Highlight({ r, kind, labels }: { r: ReviewEvidence; kind: 'positive' | 'critical'; labels: SocialLabels }) {
  return (
    <figure class="pm-review-highlight" data-kind={kind}>
      <figcaption>
        {kind === 'positive' ? labels.highlightPositive : labels.highlightCritical} · {fill(labels.rating, { average: formatRating(r.rating) })}
      </figcaption>
      {r.title && <p><strong>{r.title}</strong></p>}
      <blockquote>{r.body}</blockquote>
      {r.author && <p>{fill(labels.highlightBy, { name: r.author })}</p>}
    </figure>
  );
}

/** Review_Highlights: the newest 4-5 star and the newest 1-3 star review of 100+ characters, only when both exist. */
export function ReviewHighlights({ labels, evidence, switchOn = true }: Omit<Common, 'locale'> & { evidence: unknown }) {
  const h = switchOn ? pickHighlights(parseReviews(evidence)) : null;
  if (!h) return null;
  return (
    <section class="pm-review-highlights" aria-label={labels.highlightsTitle}>
      <h2>{labels.highlightsTitle}</h2>
      <Highlight r={h.positive} kind="positive" labels={labels} />
      <Highlight r={h.critical} kind="critical" labels={labels} />
    </section>
  );
}

type LiveState = { status: 'loading' | 'stale' } | { status: 'ready'; evidence: LiveVariantEvidence };

/** Reads the product's Live_Data through the page's shared client; stale hides the notices (Req 2.4). */
function useLiveSocial(liveUrl: string | null, productId: string, variantId: string, initialBody: unknown): LiveState {
  const initial = (): LiveState => {
    const e = initialBody ? pickLiveSocial(initialBody, productId, variantId) : null;
    return e ? { status: 'ready', evidence: e } : { status: liveUrl ? 'loading' : 'stale' };
  };
  const [state, setState] = useState<LiveState>(initial);
  useEffect(() => {
    if (!liveUrl) return;
    let cancelled = false;
    const client = pageLiveClient();
    const load = () =>
      void client.load(liveUrl).then((res) => {
        if (cancelled) return;
        const e = res.status === 'ready' ? pickLiveSocial(res.body, productId, variantId) : null;
        setState(e ? { status: 'ready', evidence: e } : { status: 'stale' });
      }, () => !cancelled && setState({ status: 'stale' }));
    load();
    const every = setInterval(() => document.visibilityState === 'visible' && load(), 60_000);
    return () => {
      cancelled = true;
      clearInterval(every);
    };
  }, [liveUrl, productId, variantId]);
  return state;
}

interface LiveProps extends Common { liveUrl?: string | null; productId: string; variantId: string; initialBody?: unknown }

/** Popularity_Notice: "<band>+ bought in the last 7 days" for a band of 5 or more. */
export function PopularityNotice({ locale, labels, liveUrl = null, productId, variantId, initialBody = null, switchOn = true }: LiveProps) {
  const live = useLiveSocial(switchOn ? liveUrl : null, productId, variantId, switchOn ? initialBody : null);
  if (!switchOn || live.status !== 'ready' || live.evidence.popularityBand === null) return null;
  return <p class="pm-popularity">{fill(labels.popularity, { band: formatNumber(live.evidence.popularityBand, locale) })}</p>;
}

/** Low_Stock_Notice: the exact Sellable_Quantity while above 0, within the threshold and without backorders. */
export function LowStockNotice({ locale, labels, liveUrl = null, productId, variantId, initialBody = null, switchOn = true }: LiveProps) {
  const live = useLiveSocial(switchOn ? liveUrl : null, productId, variantId, switchOn ? initialBody : null);
  if (!switchOn || live.status !== 'ready' || live.evidence.quantity === null) return null;
  return <p class="pm-low-stock" role="status">{fill(labels.lowStock, { count: formatNumber(live.evidence.quantity, locale) })}</p>;
}

/** Trust_Strip: only the statements that the evidence confirms. */
export function TrustStrip({ locale, labels, evidence, switchOn = true }: Common & { evidence: TrustEvidence | null }) {
  const items = switchOn ? trustItems(evidence) : [];
  if (!items.length) return null;
  return (
    <ul class="pm-trust-strip" aria-label={labels.trustLabel}>
      {items.map((i) => (
        <li key={i.key}>{fill(labels[i.key], { value: i.key === 'returns' && i.value ? formatNumber(Number(i.value), locale) : (i.value ?? '') })}</li>
      ))}
    </ul>
  );
}
