// Component_Switch rule (Req 11.25): a Persuasion_Component shows while its switch is on, or while a running
// Experiment on it assigns the session to the treatment. Switches come from the build data (`componentSwitches`).
import rationale from './rationale.json';

export type Switches = Readonly<Record<string, boolean>>;

/** Reads the assignments of `data-pm-exp` ("id=t id2=c") into the ids assigned to the treatment. */
export function treatmentIds(attr: string | null | undefined): Set<string> {
  const out = new Set<string>();
  for (const part of (attr ?? '').split(/\s+/)) {
    const [id, v] = part.split('=');
    if (id && v === 't') out.add(id);
  }
  return out;
}

/** Reads `data-pm-xt` (the components whose running Experiment assigns the treatment) into a set of component keys. */
export function treatmentComponents(attr: string | null | undefined): Set<string> {
  return new Set((attr ?? '').split(/\s+/).filter(Boolean));
}

/** Components whose pages wrap them in an ExperimentSlot. An Experiment on another component changes nothing yet. */
export const SLOTTED_KEYS: readonly string[] = [
  'review_summary', 'trust_strip', 'review_highlights', 'goes_well_with', 'popularity_notice', 'price_block', 'sale_countdown',
  'low_stock_notice', 'dispatch_countdown', 'delivery_promise', 'free_delivery_progress',
];

export interface ExperimentOn { component?: string }

/**
 * Build-time slots. A component with a running Experiment is rendered in the state its switch does NOT have, and the page
 * shows it to one variant only: `treatment` when its switch is off (the treatment turns it on), `control` when its switch
 * is on (the treatment turns it off). CSS (`experiments.css`) does the choice from `data-pm-xt` before the first paint.
 * Returns the switches to render with and the show-to variant of each tested component.
 */
export function experimentSlots(switches: Switches, running: readonly ExperimentOn[]): { render: Record<string, boolean>; showTo: Record<string, 'treatment' | 'control'> } {
  const render: Record<string, boolean> = { ...switches };
  const showTo: Record<string, 'treatment' | 'control'> = {};
  for (const e of running) {
    const key = e.component;
    if (!key || !SLOTTED_KEYS.includes(key) || key in showTo) continue;
    const isOn = switches[key] !== false;
    render[key] = true;
    showTo[key] = isOn ? 'control' : 'treatment';
  }
  return { render, showTo };
}

/** CSS that shows a tested component to its variant only. Every key is listed because a selector cannot name an attribute value of another element. */
export function experimentCss(keys: readonly string[]): string {
  return keys
    .map((k) => `html:not([data-pm-xt~="${k}"]) [data-pm-component="${k}"][data-pm-show="treatment"],\nhtml[data-pm-xt~="${k}"] [data-pm-component="${k}"][data-pm-show="control"]{display:none}`)
    .join('\n');
}

/** Whether a component shows: its switch is not off, or an Experiment on it assigns the treatment. */
export function componentShown(switches: Switches, key: string, experimentOn: ReadonlySet<string> = new Set()): boolean {
  return switches[key] !== false || experimentOn.has(key);
}

export interface Rationale {
  principle: string;
  evidence: string;
  shownOnlyWhen: string;
  expectedEffect: string;
  darkPatternGuard: string;
}

/** The Component_Rationale of a component in a language, or null for an unknown component. */
export function rationaleOf(key: string, lang: 'en' | 'hi'): Rationale | null {
  const entry = (rationale as Record<string, { en: Rationale; hi: Rationale }>)[key];
  return entry ? entry[lang] : null;
}

export const COMPONENT_KEYS: readonly string[] = Object.keys(rationale);
