// Language paths (design "Languages"): `/<path>` is English and `/hi/<path>` is Hindi. Pure; used by the build,
// the Worker and islands. Only site-relative paths are mapped; other hrefs come back unchanged.
import type { Locale } from './i18n';

export const HI_PREFIX = '/hi';
export const HREFLANG: Record<Locale, string> = { en: 'en-IN', hi: 'hi-IN' };

const isSitePath = (href: string): boolean => href.startsWith('/') && !href.startsWith('//');

/** Splits `/path?query#hash` into its path and the rest (query and hash, kept as written). */
function splitSuffix(href: string): { path: string; suffix: string } {
  const i = href.search(/[?#]/);
  return i < 0 ? { path: href, suffix: '' } : { path: href.slice(0, i), suffix: href.slice(i) };
}

/** Language of a path and the path without the `/hi` prefix. `/hindi` is not Hindi. */
export function splitLocale(pathname: string): { locale: Locale; path: string } {
  if (pathname === HI_PREFIX || pathname === `${HI_PREFIX}/`) return { locale: 'hi', path: '/' };
  if (pathname.startsWith(`${HI_PREFIX}/`)) return { locale: 'hi', path: pathname.slice(HI_PREFIX.length) };
  return { locale: 'en', path: pathname || '/' };
}

/** Language of a path. */
export const localeOfPath = (pathname: string): Locale => splitLocale(pathname).locale;

/** Localized href of any site route, keeping the query string and hash: `/shop?sort=new` -> `/hi/shop?sort=new`. */
export function localizedHref(href: string, locale: Locale): string {
  if (!isSitePath(href)) return href;
  const { path, suffix } = splitSuffix(href);
  const base = splitLocale(path).path;
  if (locale === 'en') return `${base}${suffix}`;
  return `${base === '/' ? HI_PREFIX : HI_PREFIX + base}${suffix}`;
}

/** The same page in the other language, keeping the query string and hash (Req 5.3). */
export function alternatePath(href: string): string {
  if (!isSitePath(href)) return href;
  const { path } = splitSuffix(href);
  return localizedHref(href, localeOfPath(path) === 'en' ? 'hi' : 'en');
}

export interface AlternateLink {
  hreflang: string;
  href: string;
}

/** Site origin without a trailing slash, or '' for relative links. */
const origin = (site?: string | URL): string => (site ? String(site).replace(/\/+$/, '') : '');

/** Path without query or hash, never ending in a slash (except the root). */
function cleanPath(pathname: string): string {
  const { path } = splitSuffix(pathname);
  return path.length > 1 ? path.replace(/\/+$/, '') || '/' : path || '/';
}

/** Canonical URL of a page: its own language version, with no query string. */
export function canonicalUrl(pathname: string, site?: string | URL): string {
  const p = cleanPath(pathname);
  return `${origin(site)}${p}` || '/';
}

/** `hreflang` alternates for a page: `en-IN`, `hi-IN` and `x-default` (English) (Req 5.2). */
export function alternateLinks(pathname: string, site?: string | URL): AlternateLink[] {
  const { path } = splitLocale(cleanPath(pathname));
  const o = origin(site);
  const en = `${o}${path}`;
  const hi = `${o}${localizedHref(path, 'hi')}`;
  return [
    { hreflang: HREFLANG.en, href: en },
    { hreflang: HREFLANG.hi, href: hi },
    { hreflang: 'x-default', href: en },
  ];
}
