/**
 * Delivery dates and countdowns (Req 9.10, 11.6-11.9; design "Countdowns" honesty rules). Pure and clock-injected.
 * Every time comes from the server clock of the latest Live_Data response, never the device clock.
 * Dates are calendar days ("YYYY-MM-DD") in the store timezone; instants are epoch milliseconds.
 */
import { DEFAULT_TIMEZONE, formatDateRange, formatNumber, type FormatLocale } from './format';

export interface DispatchSettings {
  timezone: string;
  /** "HH:MM" in the store timezone, or null when no cutoff is set. */
  cutoff: string | null;
  /** ISO weekday numbers, 1 = Monday to 7 = Sunday. */
  workingDays: number[];
  /** "YYYY-MM-DD" non-working dates. */
  holidays: string[];
}

const YMD = /^(\d{4})-(\d{2})-(\d{2})$/;
const CUTOFF = /^([01]\d|2[0-3]):([0-5]\d)$/;
const DAY_MS = 86_400_000;
/** The longest search for the next working day; settings with no working day in this span give no estimate. */
const MAX_SEARCH_DAYS = 400;

/** Reads the `dispatch` object of a Live_Data response; null when it is missing or unusable. */
export function parseDispatchSettings(raw: unknown): DispatchSettings | null {
  if (!raw || typeof raw !== 'object') return null;
  const o = raw as Record<string, unknown>;
  const timezone = typeof o.timezone === 'string' && o.timezone ? o.timezone : DEFAULT_TIMEZONE;
  try {
    new Intl.DateTimeFormat('en', { timeZone: timezone });
  } catch {
    return null;
  }
  const days = Array.isArray(o.working_days) ? o.working_days.filter((d): d is number => Number.isInteger(d) && d >= 1 && d <= 7) : [1, 2, 3, 4, 5, 6];
  const holidays = Array.isArray(o.holidays) ? o.holidays.filter((h): h is string => typeof h === 'string' && YMD.test(h)) : [];
  const cutoff = typeof o.dispatch_cutoff === 'string' && CUTOFF.test(o.dispatch_cutoff) ? o.dispatch_cutoff : null;
  return { timezone, cutoff, workingDays: days, holidays };
}

export interface ZonedParts {
  ymd: string;
  /** ISO weekday, 1 = Monday to 7 = Sunday. */
  weekday: number;
  /** Seconds since local midnight. */
  secondOfDay: number;
}

const fmtCache = new Map<string, Intl.DateTimeFormat>();

/** The calendar day, weekday and time of day of an instant in a timezone. */
export function zonedParts(ms: number, timeZone: string): ZonedParts {
  let f = fmtCache.get(timeZone);
  if (!f) {
    f = new Intl.DateTimeFormat('en-GB', {
      timeZone, hourCycle: 'h23', year: 'numeric', month: '2-digit', day: '2-digit',
      hour: '2-digit', minute: '2-digit', second: '2-digit',
    });
    fmtCache.set(timeZone, f);
  }
  const p: Record<string, string> = {};
  for (const part of f.formatToParts(new Date(ms))) p[part.type] = part.value;
  const ymd = `${p.year}-${p.month}-${p.day}`;
  return { ymd, weekday: isoWeekday(ymd), secondOfDay: Number(p.hour) * 3600 + Number(p.minute) * 60 + Number(p.second) };
}

const ymdToUtcMs = (ymd: string): number => {
  const m = YMD.exec(ymd);
  return m ? Date.UTC(Number(m[1]), Number(m[2]) - 1, Number(m[3])) : NaN;
};

/** Monday = 1 to Sunday = 7. */
export function isoWeekday(ymd: string): number {
  const d = new Date(ymdToUtcMs(ymd)).getUTCDay();
  return d === 0 ? 7 : d;
}

export function addDays(ymd: string, n: number): string {
  return new Date(ymdToUtcMs(ymd) + n * DAY_MS).toISOString().slice(0, 10);
}

export function isWorkingDay(ymd: string, s: DispatchSettings): boolean {
  return s.workingDays.includes(isoWeekday(ymd)) && !s.holidays.includes(ymd);
}

/** The first working day on or after `ymd`; null when none exists within the search span. */
export function nextWorkingDay(ymd: string, s: DispatchSettings): string | null {
  for (let i = 0; i < MAX_SEARCH_DAYS; i++) {
    const d = addDays(ymd, i);
    if (isWorkingDay(d, s)) return d;
  }
  return null;
}

const cutoffSecond = (cutoff: string): number => {
  const m = CUTOFF.exec(cutoff)!;
  return Number(m[1]) * 3600 + Number(m[2]) * 60;
};

/**
 * The day an Order placed now is dispatched: today while today is a working day and the Dispatch_Cutoff
 * has not passed (or none is set), otherwise the next working day.
 */
export function dispatchDay(nowMs: number, s: DispatchSettings): { day: string; sameDay: boolean } | null {
  const now = zonedParts(nowMs, s.timezone);
  const beforeCutoff = s.cutoff === null || now.secondOfDay < cutoffSecond(s.cutoff);
  if (beforeCutoff && isWorkingDay(now.ymd, s)) return { day: now.ymd, sameDay: true };
  const day = nextWorkingDay(addDays(now.ymd, 1), s);
  return day ? { day, sameDay: false } : null;
}

/** Adds working days to a dispatch day; day 0 is the dispatch day itself. */
export function addWorkingDays(ymd: string, n: number, s: DispatchSettings): string | null {
  let day = ymd;
  for (let left = n; left > 0; left--) {
    const next = nextWorkingDay(addDays(day, 1), s);
    if (!next) return null;
    day = next;
  }
  return day;
}

export interface DeliveryEstimate {
  /** Dates as "YYYY-MM-DD" in the store timezone. */
  from: string;
  to: string;
  dispatchDay: string;
}

/** Earliest and latest delivery dates: the dispatch day plus the rule's transit days, counted in working days. */
export function deliveryEstimate(
  nowMs: number,
  s: DispatchSettings,
  etaMinDays: number | null | undefined,
  etaMaxDays: number | null | undefined,
): DeliveryEstimate | null {
  const ok = (n: unknown): n is number => typeof n === 'number' && Number.isInteger(n) && n >= 0;
  if (!ok(etaMinDays) || !ok(etaMaxDays) || etaMaxDays < etaMinDays) return null;
  const d = dispatchDay(nowMs, s);
  if (!d) return null;
  const from = addWorkingDays(d.day, etaMinDays, s);
  const to = addWorkingDays(d.day, etaMaxDays, s);
  return from && to ? { from, to, dispatchDay: d.day } : null;
}

/** "Thu 12 – Sat 14 Nov" for a delivery estimate; the days are calendar days, so the text is built in UTC. */
export function formatEstimate(e: DeliveryEstimate, locale: FormatLocale, nowMs: number, timeZone: string): string {
  const noon = (ymd: string) => ymdToUtcMs(ymd) + DAY_MS / 2;
  const today = zonedParts(nowMs, timeZone).ymd;
  return formatDateRange(noon(e.from), noon(e.to), locale, { timeZone: 'UTC', now: noon(today) });
}

/** The Dispatch_Countdown (Req 11.8): ms left to order for same-day dispatch, or null when it must not show. */
export function dispatchCountdownMs(nowMs: number, s: DispatchSettings, sellable: boolean): number | null {
  if (!s.cutoff || !sellable) return null;
  const now = zonedParts(nowMs, s.timezone);
  if (!isWorkingDay(now.ymd, s)) return null;
  const left = (cutoffSecond(s.cutoff) - now.secondOfDay) * 1000;
  return left > 0 ? left : null;
}

export const SALE_COUNTDOWN_WINDOW_MS = 48 * 3_600_000;

export interface SaleCountdownEvidence {
  endsAt: number;
  laterPrice: number;
}

/** Reads a variant's Live_Data `countdown`; null unless it has a valid end and a later price. */
export function parseSaleCountdown(raw: unknown): SaleCountdownEvidence | null {
  if (!raw || typeof raw !== 'object') return null;
  const o = raw as { ends_at?: unknown; later_price?: unknown };
  const endsAt = typeof o.ends_at === 'string' ? Date.parse(o.ends_at) : NaN;
  const later = typeof o.later_price === 'number' ? o.later_price : typeof o.later_price === 'string' ? Number(o.later_price) : NaN;
  return Number.isFinite(endsAt) && Number.isFinite(later) && later >= 0 ? { endsAt, laterPrice: later } : null;
}

/** The Sale_Countdown (Req 11.6): ms left while the end lies ahead and within 48 hours; null otherwise. */
export function saleCountdownMs(nowMs: number, e: SaleCountdownEvidence | null): number | null {
  if (!e) return null;
  const left = e.endsAt - nowMs;
  return left > 0 && left <= SALE_COUNTDOWN_WINDOW_MS ? left : null;
}

/** A clock that starts from the server's time and advances with the monotonic clock, so the device clock never matters. */
export interface ServerClock {
  now(): number;
}

export function createServerClock(serverTime: string | number, mono: () => number = () => performance.now()): ServerClock | null {
  const base = typeof serverTime === 'number' ? serverTime : Date.parse(serverTime);
  if (!Number.isFinite(base)) return null;
  const at = mono();
  return { now: () => base + (mono() - at) };
}

/** "02:03:09"; the hours run past 24 up to 48. Latin digits. */
export function formatClock(ms: number, locale: FormatLocale = 'en'): string {
  const total = Math.max(0, Math.floor(ms / 1000));
  const two = (n: number) => formatNumber(n, locale).padStart(2, '0');
  return `${two(Math.floor(total / 3600))}:${two(Math.floor((total % 3600) / 60))}:${two(total % 60)}`;
}

/** The whole minute the screen-reader text is built from; it changes once a minute, not every second. */
export const minuteOf = (ms: number): number => Math.floor(Math.max(0, ms) / 60000);

/** "9:00 PM" style local end time in the store timezone, for the static text. */
export function formatEndTime(ms: number, locale: FormatLocale, timeZone: string): string {
  return new Intl.DateTimeFormat(locale === 'hi' ? 'hi-IN' : 'en-IN', {
    timeZone, hour: 'numeric', minute: '2-digit', day: 'numeric', month: 'short', numberingSystem: 'latn',
  }).format(new Date(ms));
}

export interface LiveDelivery {
  serverTime: string | null;
  dispatch: DispatchSettings | null;
  /** True while the variant has stock to dispatch now (in stock or low stock, not backorder). */
  sellable: boolean;
  countdown: SaleCountdownEvidence | null;
}

/** Reads the delivery and countdown evidence of one variant from a Live_Data response body; null when the variant is absent. */
export function pickLiveDelivery(body: unknown, productId: string, variantId: string): LiveDelivery | null {
  const b = body as { products?: unknown; server_time?: unknown; dispatch?: unknown } | null;
  if (!b || !Array.isArray(b.products)) return null;
  const p = b.products.find((x) => x && typeof x === 'object' && (x as { id?: unknown }).id === productId) as
    | { available?: boolean; variants?: Array<{ id?: string; stock_state?: string; countdown?: unknown }> }
    | undefined;
  if (!p || p.available === false || !Array.isArray(p.variants)) return null;
  const v = p.variants.find((x) => x?.id === variantId);
  if (!v) return null;
  return {
    serverTime: typeof b.server_time === 'string' ? b.server_time : null,
    dispatch: parseDispatchSettings(b.dispatch),
    sellable: v.stock_state === 'in_stock' || v.stock_state === 'low_stock',
    countdown: parseSaleCountdown(v.countdown),
  };
}

export interface PostalCheck {
  serviceable: boolean | null;
  cod: boolean;
  etaMin: number | null;
  etaMax: number | null;
}

/** Reads a `store_check_postal_code` result; null for an error envelope or an unexpected shape. */
export function parsePostalCheck(raw: unknown): PostalCheck | null {
  if (!raw || typeof raw !== 'object' || (raw as { error?: unknown }).error) return null;
  const o = raw as Record<string, unknown>;
  const num = (v: unknown) => (typeof v === 'number' && Number.isFinite(v) ? v : null);
  return {
    serviceable: typeof o.serviceable === 'boolean' ? o.serviceable : null,
    cod: o.cod_available === true,
    etaMin: num(o.eta_min_days),
    etaMax: num(o.eta_max_days),
  };
}
