// Cart count shown in the header and the bottom navigation (Req 2.9).
import { getCart } from './storage';

export const CART_CHANNEL = 'sf.cart';

/** Number of items in the stored Cart; 0 when there is no Cart or its lines are not stored. */
export function cartItemCount(cart: ReturnType<typeof getCart> = getCart()): number {
  if (!cart?.lines) return 0;
  let n = 0;
  for (const line of Object.values(cart.lines)) {
    const q = line?.qty;
    if (typeof q === 'number' && Number.isFinite(q) && q > 0) n += Math.floor(q);
  }
  return n;
}

/** Call after the Cart changes: every other open tab then recounts within moments. */
export function notifyCartChanged(): void {
  try {
    const ch = new BroadcastChannel(CART_CHANNEL);
    ch.postMessage('changed');
    ch.close();
  } catch {
    /* BroadcastChannel unavailable: the `storage` event still reaches other tabs */
  }
}

/** Calls `onChange` with the new count when the Cart changes in any tab. Returns the unsubscribe function. */
export function watchCartCount(onChange: (count: number) => void): () => void {
  const update = () => onChange(cartItemCount());
  let channel: BroadcastChannel | null = null;
  try {
    channel = new BroadcastChannel(CART_CHANNEL);
    channel.onmessage = update;
  } catch {
    channel = null;
  }
  const onStorage = (e: StorageEvent) => {
    if (e.key === null || e.key === CART_CHANNEL) update();
  };
  window.addEventListener('storage', onStorage);
  update();
  return () => {
    channel?.close();
    window.removeEventListener('storage', onStorage);
  };
}
