/**
 * Client-side checkout input checks (Req 13.3, 13.6, 13.7).
 *
 * These only save the shopper a round trip. The Store_API stays the authority and
 * repeats every rule: email and control characters follow internal.validate helpers,
 * the GSTIN rule is internal.storefront_gstin_valid, quantity bounds are
 * internal.assert_cart_item_allowed.
 *
 * Errors are i18n keys (see src/i18n/*.json, group "validation"), never display text.
 */

export type ValidationErrorKey =
  | 'validation.required'
  | 'validation.controlCharacters'
  | 'validation.mobileInvalid'
  | 'validation.emailInvalid'
  | 'validation.pinInvalid'
  | 'validation.tooLong'
  | 'validation.gstinInvalid'
  | 'validation.quantityInvalid'
  | 'validation.quantityMin'
  | 'validation.quantityMax';

export interface ValidationError {
  key: ValidationErrorKey;
  /** Values for the message's placeholders, such as {max} or {min}. */
  params?: Record<string, number>;
}

export type ValidationResult<T = string> = { ok: true; value: T } | { ok: false; error: ValidationError };

const ok = <T>(value: T): ValidationResult<T> => ({ ok: true, value });
const fail = <T = string>(key: ValidationErrorKey, params?: Record<string, number>): ValidationResult<T> => ({
  ok: false,
  error: params ? { key, params } : { key },
});

/** Same character class the backend rejects in single-line text. */
// eslint-disable-next-line no-control-regex
const CONTROL_CHARS = /[\u0000-\u001F\u007F]/;

export const NAME_MAX = 100;
export const ADDRESS_LINE_MAX = 200;
export const LANDMARK_MAX = 100;
export const CITY_MAX = 100;
export const EMAIL_MAX = 254;
/** Backend default of the setting cart.max_quantity_per_variant. */
export const DEFAULT_MAX_QUANTITY = 100;

/** Trims and collapses inner whitespace. */
function tidy(input: string): string {
  return input.trim().replace(/\s+/g, ' ');
}

function checkText(input: string, max: number, required: boolean): ValidationResult {
  const value = tidy(input ?? '');
  if (value === '') return required ? fail('validation.required') : ok('');
  if (CONTROL_CHARS.test(input)) return fail('validation.controlCharacters');
  if (value.length > max) return fail('validation.tooLong', { max });
  return ok(value);
}

/**
 * Indian mobile number: after removing spaces and hyphens, a leading +91 or 0,
 * 10 digits starting with 6, 7, 8 or 9. Returns the 10 digits.
 */
export function validateMobile(input: string): ValidationResult {
  let s = (input ?? '').replace(/[\s-]/g, '');
  if (s === '') return fail('validation.required');
  if (s.startsWith('+91')) s = s.slice(3);
  else if (s.startsWith('0')) s = s.slice(1);
  return /^[6-9][0-9]{9}$/.test(s) ? ok(s) : fail('validation.mobileInvalid');
}

/** The number in international form, for example +919876543210. */
export function toE164(mobile: string): string {
  return `+91${mobile}`;
}

/** Email address, lowercased; same rule as the backend. */
export function validateEmail(input: string): ValidationResult {
  const s = (input ?? '').trim().toLowerCase();
  if (s === '') return fail('validation.required');
  if (s.length > EMAIL_MAX || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(s)) return fail('validation.emailInvalid');
  return ok(s);
}

/** PIN code: 6 digits, the first 1 to 9. Spaces are ignored. */
export function validatePin(input: string): ValidationResult {
  const s = (input ?? '').replace(/\s/g, '');
  if (s === '') return fail('validation.required');
  return /^[1-9][0-9]{5}$/.test(s) ? ok(s) : fail('validation.pinInvalid');
}

export interface PinPlace {
  city: string;
  state: string;
}

/** Fetches a place by PIN code from the bundled shards (task 3.4); null when unknown. */
export type PinLookup = (pin: string) => Promise<PinPlace | null>;

/**
 * Checks the PIN code and, when valid, asks the injected lookup for the city and state.
 * An unknown code is not an error here: the shard may be outdated and the backend
 * decides serviceability, so the fields simply stay empty and editable.
 */
export async function lookupPin(
  input: string,
  lookup: PinLookup,
): Promise<ValidationResult<{ pin: string; place: PinPlace | null }>> {
  const r = validatePin(input);
  if (!r.ok) return r;
  let place: PinPlace | null = null;
  try {
    place = await lookup(r.value);
  } catch {
    place = null;
  }
  return ok({ pin: r.value, place });
}

export function validateName(input: string): ValidationResult {
  return checkText(input, NAME_MAX, true);
}

export function validateAddressLine(input: string, required = true): ValidationResult {
  return checkText(input, ADDRESS_LINE_MAX, required);
}

export function validateLandmark(input: string): ValidationResult {
  return checkText(input, LANDMARK_MAX, false);
}

export function validateCity(input: string): ValidationResult {
  return checkText(input, CITY_MAX, true);
}

const GSTIN_CHARS = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ';
const GSTIN_SHAPE = /^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z][1-9A-Z]Z[0-9A-Z]$/;

/** Mirrors internal.storefront_gstin_valid (its fallback rule, which spec 2's check also follows). */
export function isValidGstin(gstin: string): boolean {
  if (!GSTIN_SHAPE.test(gstin)) return false;
  const state = Number(gstin.slice(0, 2));
  if (!(state >= 1 && state <= 38) && state !== 97 && state !== 99) return false;
  let sum = 0;
  for (let i = 1; i <= 14; i++) {
    const p = GSTIN_CHARS.indexOf(gstin[i - 1]!) * (i % 2 === 1 ? 1 : 2);
    sum += Math.floor(p / 36) + (p % 36);
  }
  return GSTIN_CHARS[(36 - (sum % 36)) % 36] === gstin[14];
}

/** GSTIN is optional: an empty value is valid and returns ''. */
export function validateGstin(input: string): ValidationResult {
  const s = (input ?? '').replace(/\s/g, '').toUpperCase();
  if (s === '') return ok('');
  return isValidGstin(s) ? ok(s) : fail('validation.gstinInvalid');
}

export interface QuantityLimits {
  /** The product's min_order_qty attribute; values of 1 or less mean no minimum. */
  minOrderQty?: number | null;
  /** cart.max_quantity_per_variant; defaults to 100. */
  maxQuantity?: number | null;
}

/** Quantity of a Cart line: a whole number from the minimum order quantity to the maximum. */
export function validateQuantity(quantity: number, limits: QuantityLimits = {}): ValidationResult<number> {
  const max = limits.maxQuantity ?? DEFAULT_MAX_QUANTITY;
  const rawMin = limits.minOrderQty;
  const min = rawMin != null && Number.isFinite(rawMin) && rawMin > 1 ? Math.ceil(rawMin) : 1;
  if (!Number.isInteger(quantity) || quantity < 1) return fail('validation.quantityInvalid');
  if (quantity < min) return fail('validation.quantityMin', { min });
  if (quantity > max) return fail('validation.quantityMax', { max });
  return ok(quantity);
}

/** Replaces {name} placeholders in a translated message. */
export function formatMessage(template: string, params: Record<string, number> = {}): string {
  return template.replace(/\{(\w+)\}/g, (m, k: string) => (k in params ? String(params[k]) : m));
}
