/**
 * Product_Card badges (Req 8.3). A card shows at most 2 badges, in the Business_Preset's priority order,
 * each only while its rule holds. Every rule reads Backend data passed in; nothing is assumed.
 */
export type BadgeKey = 'sale' | 'new' | 'best_seller' | 'low_stock' | 'free_delivery' | 'made_in_india';

export const MAX_BADGES = 2;
export const NEW_WINDOW_DAYS = 30;
const DAY_MS = 86_400_000;

export interface BadgeInput {
  /** The variant is in a Price_Reduction (a Prior_Price above the price, per the price block). */
  priceReduction?: boolean;
  /** Publication time, epoch ms. */
  publishedAt?: number | null;
  /** The product is among the 20 best-selling products of the last 30 days (a build-time flag). */
  bestSeller?: boolean;
  /** The Low_Stock_Notice rule holds for the product. */
  lowStock?: boolean;
  /** The price in paise or rupees, in the same unit as `freeDeliveryThreshold`. */
  price?: number | null;
  freeDeliveryThreshold?: number | null;
  /** Declared country of origin, as written in the product's declarations. */
  countryOfOrigin?: string | null;
}

/** The rule of each badge. */
export function badgeHolds(key: BadgeKey, p: BadgeInput, now: number): boolean {
  switch (key) {
    case 'sale':
      return p.priceReduction === true;
    case 'new':
      return typeof p.publishedAt === 'number' && p.publishedAt <= now && now - p.publishedAt < NEW_WINDOW_DAYS * DAY_MS;
    case 'best_seller':
      return p.bestSeller === true;
    case 'low_stock':
      return p.lowStock === true;
    case 'free_delivery':
      return (
        typeof p.price === 'number' &&
        typeof p.freeDeliveryThreshold === 'number' &&
        p.freeDeliveryThreshold > 0 &&
        p.price >= p.freeDeliveryThreshold
      );
    case 'made_in_india':
      return typeof p.countryOfOrigin === 'string' && /^(india|bharat|in)$/i.test(p.countryOfOrigin.trim());
  }
}

/** Up to 2 badges whose rules hold, in the order of `priority`; unknown or repeated keys are ignored. */
export function selectBadges(p: BadgeInput, priority: readonly string[], now: number): BadgeKey[] {
  const out: BadgeKey[] = [];
  for (const key of priority) {
    if (out.length >= MAX_BADGES) break;
    if (!isBadgeKey(key) || out.includes(key)) continue;
    if (badgeHolds(key, p, now)) out.push(key);
  }
  return out;
}

const KEYS: readonly string[] = ['sale', 'new', 'best_seller', 'low_stock', 'free_delivery', 'made_in_india'];
export const isBadgeKey = (k: string): k is BadgeKey => KEYS.includes(k);
