/**
 * PLP state (Req 4.11, 8.4, 8.6-8.8): filters, sort order and loaded count, written to the page URL and read back.
 * Pure, so it runs at build time and in the island. Lists use repeated parameters (`cat=a&cat=b`, `o.Size=M&o.Size=L`),
 * so a value may hold any character. Invalid values in a URL are dropped.
 */
export const PAGE_SIZE = 24;
/** The Store_API's page depth cap is 5,000 products; 208 pages of 24 stay inside it. */
export const MAX_SHOWN = 4992;
const MAX_LIST = 50;
const MAX_OPTIONS = 20;
const MAX_VALUE_LEN = 100;

export const SORTS = ['featured', 'relevance', 'newest', 'price_asc', 'price_desc', 'title_asc'] as const;
export type PlpSort = (typeof SORTS)[number];

export interface PlpState {
  sort: PlpSort;
  q: string;
  categories: string[];
  collections: string[];
  tags: string[];
  types: string[];
  /** Option name to chosen values. */
  options: Record<string, string[]>;
  priceMin: number | null;
  priceMax: number | null;
  /** Number of products loaded: a multiple of 24 from 24. */
  shown: number;
}

export interface PlpScope {
  /** Fixed by the page: the category or collection being listed. */
  categoryId?: string | null;
  collectionId?: string | null;
  salesChannelId?: string | null;
  regionId?: string | null;
  currency: string;
}

export const emptyState = (q = ''): PlpState => ({
  sort: defaultSort(q), q, categories: [], collections: [], tags: [], types: [], options: {}, priceMin: null, priceMax: null, shown: PAGE_SIZE,
});

/** Featured (the store's order) for categories, relevance for searches (Req 8.7). */
export const defaultSort = (q: string): PlpSort => (q ? 'relevance' : 'featured');

const cleanList = (xs: string[]): string[] =>
  [...new Set(xs.map((x) => x.trim()).filter((x) => x && x.length <= MAX_VALUE_LEN))].slice(0, MAX_LIST);

const asPrice = (s: string | null): number | null => {
  if (s === null || s.trim() === '') return null;
  const n = Number(s);
  return Number.isFinite(n) && n >= 0 && n < 1e9 ? Math.round(n * 100) / 100 : null;
};

/** Rounds a loaded count up to a whole page and keeps it in range. */
export function normalizeShown(n: unknown): number {
  const v = typeof n === 'number' ? n : Number(n);
  if (!Number.isFinite(v) || v < PAGE_SIZE) return PAGE_SIZE;
  return Math.min(MAX_SHOWN, Math.ceil(Math.floor(v) / PAGE_SIZE) * PAGE_SIZE);
}

export function parsePlpState(search: string | URLSearchParams): PlpState {
  const p = typeof search === 'string' ? new URLSearchParams(search) : search;
  const q = (p.get('q') ?? '').trim().slice(0, MAX_VALUE_LEN);
  const sortRaw = p.get('sort') ?? '';
  let sort: PlpSort = (SORTS as readonly string[]).includes(sortRaw) ? (sortRaw as PlpSort) : defaultSort(q);
  if (sort === 'relevance' && !q) sort = 'featured';
  const options: Record<string, string[]> = {};
  for (const name of new Set([...p.keys()].filter((k) => k.startsWith('o.')))) {
    const key = name.slice(2);
    const vals = cleanList(p.getAll(name));
    if (key && key.length <= MAX_VALUE_LEN && vals.length && Object.keys(options).length < MAX_OPTIONS) options[key] = vals;
  }
  let priceMin = asPrice(p.get('min'));
  let priceMax = asPrice(p.get('max'));
  if (priceMin !== null && priceMax !== null && priceMin > priceMax) [priceMin, priceMax] = [priceMax, priceMin];
  return {
    sort, q,
    categories: cleanList(p.getAll('cat')),
    collections: cleanList(p.getAll('col')),
    tags: cleanList(p.getAll('tag')),
    types: cleanList(p.getAll('type')),
    options, priceMin, priceMax,
    shown: normalizeShown(p.get('n')),
  };
}

/** The query string of a state; defaults are left out, so the first page of the default listing has none. */
export function serializePlpState(s: PlpState): string {
  const p = new URLSearchParams();
  if (s.q) p.set('q', s.q);
  if (s.sort !== defaultSort(s.q)) p.set('sort', s.sort);
  for (const [k, list] of [['cat', s.categories], ['col', s.collections], ['tag', s.tags], ['type', s.types]] as const) {
    for (const v of list) p.append(k, v);
  }
  for (const name of Object.keys(s.options).sort()) for (const v of s.options[name]) p.append(`o.${name}`, v);
  if (s.priceMin !== null) p.set('min', String(s.priceMin));
  if (s.priceMax !== null) p.set('max', String(s.priceMax));
  if (s.shown > PAGE_SIZE) p.set('n', String(s.shown));
  return p.toString();
}

/** Number of applied filter values (the search text and sort order are not filters). */
export function filterCount(s: PlpState): number {
  return s.categories.length + s.collections.length + s.tags.length + s.types.length +
    Object.values(s.options).reduce((n, v) => n + v.length, 0) + (s.priceMin !== null ? 1 : 0) + (s.priceMax !== null ? 1 : 0);
}

export const clearFilters = (s: PlpState): PlpState => ({
  ...s, categories: [], collections: [], tags: [], types: [], options: {}, priceMin: null, priceMax: null, shown: PAGE_SIZE,
});

export type ChipKind = 'cat' | 'col' | 'tag' | 'type' | 'option' | 'min' | 'max';
export interface Chip { kind: ChipKind; id: string; name?: string }

/** One chip per applied value (Req 8.6). `id` is the value; the island looks the label up in the facets. */
export function chipsOf(s: PlpState): Chip[] {
  const out: Chip[] = [];
  s.categories.forEach((id) => out.push({ kind: 'cat', id }));
  s.collections.forEach((id) => out.push({ kind: 'col', id }));
  s.tags.forEach((id) => out.push({ kind: 'tag', id }));
  s.types.forEach((id) => out.push({ kind: 'type', id }));
  for (const name of Object.keys(s.options).sort()) s.options[name].forEach((id) => out.push({ kind: 'option', id, name }));
  if (s.priceMin !== null) out.push({ kind: 'min', id: String(s.priceMin) });
  if (s.priceMax !== null) out.push({ kind: 'max', id: String(s.priceMax) });
  return out;
}

export function removeChip(s: PlpState, c: Chip): PlpState {
  const without = (xs: string[]) => xs.filter((x) => x !== c.id);
  const next: PlpState = { ...s, shown: PAGE_SIZE };
  switch (c.kind) {
    case 'cat': next.categories = without(s.categories); break;
    case 'col': next.collections = without(s.collections); break;
    case 'tag': next.tags = without(s.tags); break;
    case 'type': next.types = without(s.types); break;
    case 'option': {
      const rest = without(s.options[c.name ?? ''] ?? []);
      next.options = { ...s.options };
      if (rest.length) next.options[c.name ?? ''] = rest;
      else delete next.options[c.name ?? ''];
      break;
    }
    case 'min': next.priceMin = null; break;
    case 'max': next.priceMax = null; break;
  }
  return next;
}

/** A Postgres array literal, which PostgREST reads from a GET query. */
export const pgArray = (xs: string[]): string => `{${xs.map((x) => `"${x.replace(/(["\\])/g, '\\$1')}"`).join(',')}}`;

/**
 * Arguments of `api.store_list_products` for one page. The page's own category or collection applies unless the shopper
 * chose values of that type. Featured uses the Store_API's default order (Req 8.7).
 */
export function listArgs(s: PlpState, scope: PlpScope, page: number, pageSize: number = PAGE_SIZE): Record<string, unknown> {
  const cats = s.categories.length ? s.categories : scope.categoryId ? [scope.categoryId] : [];
  const cols = s.collections.length ? s.collections : scope.collectionId ? [scope.collectionId] : [];
  const args: Record<string, unknown> = {
    p_sales_channel_id: scope.salesChannelId || undefined,
    p_region_id: scope.regionId || undefined,
    p_currency_code: scope.currency,
    p_q: s.q || undefined,
    p_category_ids: cats.length ? pgArray(cats) : undefined,
    p_collection_ids: cols.length ? pgArray(cols) : undefined,
    p_tag_ids: s.tags.length ? pgArray(s.tags) : undefined,
    p_type_ids: s.types.length ? pgArray(s.types) : undefined,
    p_options: Object.keys(s.options).length ? s.options : undefined,
    p_price_min: s.priceMin ?? undefined,
    p_price_max: s.priceMax ?? undefined,
    p_sort: s.sort === 'featured' ? undefined : s.sort,
    p_page: page,
    p_page_size: pageSize,
  };
  return args;
}

/** The pages that make up `shown` products: page numbers 1..n of 24. */
export const pagesFor = (shown: number): number[] =>
  Array.from({ length: Math.ceil(normalizeShown(shown) / PAGE_SIZE) }, (_, i) => i + 1);
