/**
 * Product_Card data and markup (Req 8.2, 8.3). `cardOf` reads one product of `store_list_products`; `cardHtml` writes the
 * card for products loaded in the browser, with the same classes and attributes as `ProductCard.astro`.
 */
import { selectBadges, type BadgeKey } from './badges';
import { formatMoney, savingPercent, type FormatLocale } from './format';

type Obj = Record<string, unknown>;
const isObj = (x: unknown): x is Obj => !!x && typeof x === 'object' && !Array.isArray(x);
const str = (x: unknown): string => (typeof x === 'string' ? x : '');
const num = (x: unknown): number | null => (typeof x === 'number' && Number.isFinite(x) ? x : x !== null && x !== '' && Number.isFinite(Number(x)) ? Number(x) : null);

export const MAX_SWATCHES = 5;
const COLOUR_OPTION = /^(colou?rs?|shade|रंग)$/i;
/** Values safe to use as a CSS colour (a keyword or a hex code). Anything else gets a text swatch. */
const CSS_COLOUR = /^(#[0-9a-f]{3,8}|[a-z]{3,20})$/i;

export interface Swatch { value: string; css: string | null }
export interface CardData {
  id: string;
  handle: string;
  title: string;
  imageId: string | null;
  imageUrl: string | null;
  /** Lowest variant price, in major units; null when no variant has a price. */
  price: number | null;
  /** True when variants differ in price: shown "from". */
  from: boolean;
  /** Prior_Price of the lowest-priced variant when it is above the price (a Price_Reduction). */
  prior: number | null;
  currency: string;
  swatches: Swatch[];
  extraSwatches: number;
  badges: BadgeKey[];
  /** Set when the product has exactly one variant, so a card can add it to the Cart. */
  singleVariantId: string | null;
  attributes: Record<string, string>;
}

export interface CardContext {
  badgePriority: readonly string[];
  now: number;
  freeDeliveryThreshold?: number | null;
  bestSellerIds?: ReadonlySet<string>;
}

export function swatchesOf(p: Obj): { swatches: Swatch[]; extra: number } {
  const opt = (Array.isArray(p.options) ? p.options : []).find((o) => isObj(o) && COLOUR_OPTION.test(str(o.title).trim()));
  if (!isObj(opt)) return { swatches: [], extra: 0 };
  // Only values some variant uses are offered.
  const used = new Set<string>();
  for (const v of Array.isArray(p.variants) ? p.variants : []) {
    if (!isObj(v)) continue;
    for (const o of Array.isArray(v.options) ? v.options : []) if (isObj(o) && o.option_id === opt.id) used.add(str(o.value));
  }
  const values = (Array.isArray(opt.values) ? opt.values : []).map((x) => (isObj(x) ? str(x.value) : '')).filter((v) => v && used.has(v));
  const all = values.map((value) => ({ value, css: CSS_COLOUR.test(value) ? value : null }));
  return { swatches: all.slice(0, MAX_SWATCHES), extra: Math.max(0, all.length - MAX_SWATCHES) };
}

export function cardOf(product: unknown, ctx: CardContext): CardData | null {
  if (!isObj(product) || !str(product.id) || !str(product.handle)) return null;
  const variants = (Array.isArray(product.variants) ? product.variants : []).filter(isObj);
  const priced = variants
    .map((v) => ({ v, price: isObj(v.price) ? v.price : null }))
    .map(({ v, price }) => ({ v, price, amount: price ? num(price.calculated_amount) : null }))
    .filter((x): x is { v: Obj; price: Obj; amount: number } => x.price !== null && x.amount !== null);
  priced.sort((a, b) => a.amount - b.amount);
  const lowest = priced[0];
  const price = lowest?.amount ?? null;
  const original = lowest ? num(lowest.price.original_amount) : null;
  const prior = price !== null && original !== null && original > price ? original : null;
  const highest = priced[priced.length - 1];
  const images = (Array.isArray(product.images) ? product.images : []).filter(isObj);
  const first = images[0];
  const { swatches, extra } = swatchesOf(product);
  const attrs: Record<string, string> = {};
  for (const a of Array.isArray(product.attributes) ? product.attributes : []) if (isObj(a) && str(a.key)) attrs[str(a.key)] = str(a.value);
  const id = str(product.id);
  const badges = selectBadges(
    {
      priceReduction: prior !== null,
      publishedAt: Date.parse(str(product.created_at)) || null,
      bestSeller: ctx.bestSellerIds?.has(id) ?? false,
      price,
      freeDeliveryThreshold: ctx.freeDeliveryThreshold ?? null,
      countryOfOrigin: str(product.origin_country) || null,
    },
    ctx.badgePriority,
    ctx.now,
  );
  return {
    id,
    handle: str(product.handle),
    title: str(product.title),
    imageId: first ? str(first.id) || null : null,
    imageUrl: (first ? str(first.url) : '') || str(product.thumbnail) || null,
    price,
    from: !!lowest && !!highest && highest.amount > lowest.amount,
    prior,
    currency: lowest ? str(lowest.price.currency_code).toUpperCase() || 'INR' : 'INR',
    swatches,
    extraSwatches: extra,
    badges,
    singleVariantId: variants.length === 1 ? str(variants[0].id) || null : null,
    attributes: attrs,
  };
}

export interface CardLabels {
  from: string;
  priceOnRequest: string;
  save: string; // "{percent} off"
  moreColours: string; // "+{count}"
  chooseOptions: string;
  unavailable: string;
  addToCart: string;
  /** Quick view control: its text and its screen-reader label with "{title}". */
  quickView: string;
  quickViewFor: string;
  /** Text of the dialog's link to the full product page. */
  viewFull: string;
  /** Badge key to its text. */
  badges: Record<string, string>;
  /** Screen-reader text for the price: "Current price {price}" and "Previous price {price}". */
  srCurrent: string;
  srPrior: string;
}

export const esc = (s: string): string =>
  s.replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c] as string);

const fill = (tpl: string, vars: Record<string, string | number>): string => tpl.replace(/\{(\w+)\}/g, (m, k: string) => (k in vars ? String(vars[k]) : m));

/** Text shown for the price of a card, split for markup. */
export function priceParts(c: CardData, locale: FormatLocale, labels: CardLabels) {
  if (c.price === null) return { current: labels.priceOnRequest, prior: null, saving: null, from: false };
  const saving = c.prior !== null ? savingPercent(c.prior, c.price) : 0;
  return {
    current: formatMoney(c.price, c.currency, locale),
    prior: c.prior !== null ? formatMoney(c.prior, c.currency, locale) : null,
    saving: saving > 0 ? fill(labels.save, { percent: `${saving}%` }) : null,
    from: c.from,
  };
}

/** `/product/<handle>`, in the shopper's language. */
export const productPath = (handle: string, locale: FormatLocale): string => `${locale === 'hi' ? '/hi' : ''}/product/${encodeURIComponent(handle)}`;

/** Card markup for a product loaded in the browser. Every dynamic value is escaped. */
export function cardHtml(c: CardData, locale: FormatLocale, labels: CardLabels): string {
  const href = esc(productPath(c.handle, locale));
  const pp = priceParts(c, locale, labels);
  const img = c.imageUrl
    ? `<img class="pm-card__img" src="${esc(c.imageUrl)}" width="480" height="480" alt="" loading="lazy" decoding="async">`
    : '<span class="pm-card__img pm-card__img--empty" aria-hidden="true"></span>';
  const badges = c.badges.length
    ? `<ul class="pm-card__badges">${c.badges.map((b) => `<li><span class="pm-badge">${esc(labels.badges[b] ?? b)}</span></li>`).join('')}</ul>`
    : '';
  const sw = c.swatches.length
    ? `<ul class="pm-swatches" aria-label="${esc(c.swatches.map((s) => s.value).join(', '))}">${c.swatches
        .map((s) => `<li class="pm-swatch" title="${esc(s.value)}"${s.css ? ` data-colour="${esc(s.css)}"` : ''}>${s.css ? '' : esc(s.value.slice(0, 2))}</li>`)
        .join('')}${c.extraSwatches ? `<li class="pm-swatch pm-swatch--more">${esc(fill(labels.moreColours, { count: c.extraSwatches }))}</li>` : ''}</ul>`
    : '';
  const price =
    `<p class="pm-card__price" translate="no">${pp.from ? `<span class="pm-card__from">${esc(labels.from)}</span> ` : ''}` +
    `<span class="pm-card__now"><span class="pm-visually-hidden">${esc(fill(labels.srCurrent, { price: pp.current }))}</span><span aria-hidden="true">${esc(pp.current)}</span></span>` +
    (pp.prior ? ` <s class="pm-card__prior"><span class="pm-visually-hidden">${esc(fill(labels.srPrior, { price: pp.prior }))}</span><span aria-hidden="true">${esc(pp.prior)}</span></s>` : '') +
    (pp.saving ? ` <span class="pm-card__saving">${esc(pp.saving)}</span>` : '') +
    '</p>';
  const action = c.singleVariantId && c.price !== null
    ? `<button type="button" class="pm-button pm-button--secondary pm-card__add" data-add-to-cart data-product-id="${esc(c.id)}" data-variant-id="${esc(c.singleVariantId)}">${esc(labels.addToCart)}</button>`
    : `<a class="pm-button pm-button--secondary pm-card__add" href="${href}">${esc(labels.chooseOptions)}</a>`;
    // Quick view carries the card's own values, so the dialog needs no second request (skill: quick-view-modal).
  const quick =
    `<button type="button" class="pm-card__quick" data-pm-quick-view data-quick-title="${esc(c.title)}" data-quick-url="${href}"` +
    ` data-quick-image="${esc(c.imageUrl ?? '')}" data-quick-price="${esc(pp.current)}"` +
    (pp.prior ? ` data-quick-prior="${esc(pp.prior)}"` : '') +
    ` data-quick-badges="${esc(c.badges.map((b) => labels.badges[b] ?? b).join('|'))}"` +
    (c.price !== null && c.singleVariantId
      ? ` data-quick-product-id="${esc(c.id)}" data-quick-variant-id="${esc(c.singleVariantId)}"`
      : '') +
    ` data-quick-add="${esc(labels.addToCart)}" data-quick-full="${esc(labels.viewFull)}"` +
    ` aria-label="${esc(fill(labels.quickViewFor, { title: c.title }))}">${esc(labels.quickView)}</button>`;
  return (`<li class="pm-card pm-product-card" data-live-product="${esc(c.id)}" data-product-id="${esc(c.id)}">` +
    `<div class="pm-card__media"><a class="pm-card__link" href="${href}" tabindex="-1" aria-hidden="true"></a>${img}${badges}${quick}</div>` +
    `<div class="pm-card__body"><h3 class="pm-card__title"><a href="${href}">${esc(c.title)}</a></h3>${sw}` +
    `<div class="pm-card__foot">${price}<p class="pm-unavailable-note" data-unavailable-note data-product-id="${esc(c.id)}" hidden>${esc(labels.unavailable)}</p>${action}</div></div></li>`
  );
}
