/**
 * PDP model and rules (Req 9, 10.10). Pure, so the build, the island and the tests share it.
 * `parsePdpProduct` reads one product of `store_catalog_export`; the other helpers answer the variant, stock, gallery,
 * review and offer questions of the page.
 */
type Obj = Record<string, unknown>;
const isObj = (x: unknown): x is Obj => !!x && typeof x === 'object' && !Array.isArray(x);
const str = (x: unknown): string => (typeof x === 'string' ? x : '');
const num = (x: unknown): number | null =>
  typeof x === 'number' && Number.isFinite(x) ? x : typeof x === 'string' && x.trim() !== '' && Number.isFinite(Number(x)) ? Number(x) : null;
const arr = (x: unknown): unknown[] => (Array.isArray(x) ? x : []);

export interface PdpOptionModel { id: string; title: string; values: string[] }
export interface PdpVariantModel {
  id: string;
  title: string;
  sku: string;
  thumbnail: string | null;
  /** Option ID to the chosen value. */
  options: Record<string, string>;
  price: number | null;
  prior: number | null;
  mrp: number | null;
  netQuantity: number | null;
  netQuantityUnit: string | null;
  tiers: { minQuantity: number; amount: number }[];
  allowBackorder: boolean;
}
export interface PdpImage { id: string; url: string }
export interface PdpModel {
  id: string;
  handle: string;
  title: string;
  subtitle: string;
  description: string;
  images: PdpImage[];
  options: PdpOptionModel[];
  variants: PdpVariantModel[];
  currency: string;
  keyHighlights: string[];
  rating: { count: number; average: number } | null;
  categories: { id: string; name: string; handle: string }[];
  attributes: { key: string; value: unknown }[];
  originCountry: string;
  pairings: Record<string, string[]>;
}

export function parsePdpProduct(raw: unknown, fallbackCurrency = 'INR'): PdpModel | null {
  if (!isObj(raw) || !str(raw.id) || !str(raw.handle)) return null;
  const prices = isObj(raw.variant_prices) ? raw.variant_prices : {};
  const decls = isObj(raw.declarations) ? raw.declarations : {};
  const options: PdpOptionModel[] = arr(raw.options).filter(isObj).map((o) => ({
    id: str(o.id),
    title: str(o.title),
    values: arr(o.values).filter(isObj).map((v) => str(v.value)).filter(Boolean),
  })).filter((o) => o.id && o.values.length > 0);
  let currency = '';
  const variants: PdpVariantModel[] = arr(raw.variants).filter(isObj).map((v) => {
    const id = str(v.id);
    const vp = isObj(prices[id]) ? (prices[id] as Obj) : null;
    const p = isObj(v.price) ? v.price : null;
    if (!currency && p && str(p.currency_code)) currency = str(p.currency_code).toUpperCase();
    const decl = isObj(decls[id]) ? (decls[id] as Obj) : {};
    const price = num(vp?.amount) ?? num(p?.calculated_amount);
    const prior = num(vp?.prior_price);
    return {
      id,
      title: str(v.title),
      sku: str(v.sku),
      thumbnail: str(v.thumbnail) || null,
      options: Object.fromEntries(arr(v.options).filter(isObj).map((o) => [str(o.option_id), str(o.value)])),
      price,
      prior: price !== null && prior !== null && prior > price ? prior : null,
      mrp: num(decl.mrp),
      netQuantity: num(decl.net_quantity),
      netQuantityUnit: str(decl.net_quantity_unit) || null,
      tiers: arr(vp?.tiers).filter(isObj)
        .map((t) => ({ minQuantity: num(t.min_quantity) ?? 0, amount: num(t.amount) ?? -1 }))
        .filter((t) => t.minQuantity > 1 && t.amount >= 0),
      allowBackorder: v.allow_backorder === true,
    };
  }).filter((v) => v.id);
  const images = arr(raw.images).filter(isObj).map((i) => ({ id: str(i.id), url: str(i.url) })).filter((i) => i.url);
  if (!images.length && str(raw.thumbnail)) images.push({ id: 'thumbnail', url: str(raw.thumbnail) });
  const rating = isObj(raw.rating) && (num(raw.rating.review_count) ?? 0) > 0
    ? { count: Math.trunc(num(raw.rating.review_count) as number), average: num(raw.rating.average) ?? 0 }
    : null;
  const pairings = isObj(raw.pairings)
    ? Object.fromEntries(Object.entries(raw.pairings).map(([k, v]) => [k, arr(v).map(str).filter(Boolean)]))
    : {};
  return {
    id: str(raw.id),
    handle: str(raw.handle),
    title: str(raw.title),
    subtitle: str(raw.subtitle),
    description: str(raw.description),
    images,
    options,
    variants,
    currency: currency || fallbackCurrency.toUpperCase(),
    keyHighlights: arr(raw.key_highlights).map(str).map((s) => s.trim()).filter(Boolean),
    rating,
    categories: arr(raw.categories).filter(isObj).map((c) => ({ id: str(c.id), name: str(c.name), handle: str(c.handle) })),
    attributes: arr(raw.attributes).filter(isObj).map((a) => ({ key: str(a.key), value: a.value })).filter((a) => a.key),
    originCountry: str(raw.origin_country),
    pairings,
  };
}

// --- Variants ---------------------------------------------------------------------------------------------------------

export type Selection = Record<string, string>;

/** The variant whose options equal the selection; null until every option has a value or when no variant matches. */
export function variantFor(m: PdpModel, sel: Selection): PdpVariantModel | null {
  if (m.options.some((o) => !sel[o.id])) return null;
  return m.variants.find((v) => m.options.every((o) => v.options[o.id] === sel[o.id])) ?? null;
}

/** The first option without a value (Req 9.6). */
export function missingOption(m: PdpModel, sel: Selection): PdpOptionModel | null {
  return m.options.find((o) => !sel[o.id]) ?? null;
}

export function selectionOf(m: PdpModel, v: PdpVariantModel): Selection {
  return Object.fromEntries(m.options.map((o) => [o.id, v.options[o.id] ?? '']).filter(([, val]) => val));
}

/** The opening selection: the `?variant=` variant, the only variant, or nothing (the shopper chooses). */
export function initialSelection(m: PdpModel, variantParam?: string | null): Selection {
  const byParam = variantParam ? m.variants.find((v) => v.id === variantParam) : undefined;
  if (byParam) return selectionOf(m, byParam);
  if (m.variants.length === 1) return selectionOf(m, m.variants[0]);
  // An option with one value needs no choice.
  return Object.fromEntries(m.options.filter((o) => o.values.length === 1).map((o) => [o.id, o.values[0]]));
}

/** The variant shown in the price block while none is chosen: the cheapest one. */
export function displayVariant(m: PdpModel, chosen: PdpVariantModel | null): PdpVariantModel | null {
  if (chosen) return chosen;
  const priced = m.variants.filter((v) => v.price !== null).sort((a, b) => (a.price as number) - (b.price as number));
  return priced[0] ?? m.variants[0] ?? null;
}

/** True when prices differ across variants, so a price shown before a choice reads "from". */
export const pricesDiffer = (m: PdpModel): boolean => new Set(m.variants.map((v) => v.price)).size > 1;

// --- Stock ------------------------------------------------------------------------------------------------------------

export type StockState = 'in_stock' | 'low_stock' | 'out_of_stock' | 'backorder';
const STATES: readonly string[] = ['in_stock', 'low_stock', 'out_of_stock', 'backorder'];

/** A variant's Stock_State from a Live_Data body; null when Live_Data has none. */
export function stockStateOf(body: unknown, productId: string, variantId: string): StockState | null {
  if (!isObj(body) || !Array.isArray(body.products)) return null;
  const p = body.products.find((x) => isObj(x) && x.id === productId);
  if (!isObj(p) || p.available === false) return null;
  const v = arr(p.variants).find((x) => isObj(x) && x.id === variantId);
  const s = isObj(v) ? str(v.stock_state) : '';
  return STATES.includes(s) ? (s as StockState) : null;
}

export const isSellable = (s: StockState | null): boolean => s !== 'out_of_stock';

/** An option value is out of stock when it has variants and none of them can be bought (Req 9.3). Unknown stock is not marked. */
export function valueOutOfStock(m: PdpModel, optionId: string, value: string, stock: (variantId: string) => StockState | null): boolean {
  const vs = m.variants.filter((v) => v.options[optionId] === value);
  if (!vs.length) return true;
  return vs.every((v) => stock(v.id) === 'out_of_stock');
}

// --- Gallery ----------------------------------------------------------------------------------------------------------

/** The image index to show for a variant: the one whose URL is the variant's thumbnail; -1 when none. */
export function imageIndexFor(m: PdpModel, v: PdpVariantModel | null): number {
  if (!v?.thumbnail) return -1;
  return m.images.findIndex((i) => i.url === v.thumbnail);
}

export const positionLabel = (index: number, total: number, template: string): string =>
  template.replace('{index}', String(index + 1)).replace('{total}', String(total));

// --- URL and share ----------------------------------------------------------------------------------------------------

/** `?variant=` of the current URL with the variant set, other parameters kept. */
export function withVariantParam(search: string, variantId: string | null): string {
  const q = new URLSearchParams(search);
  if (variantId) q.set('variant', variantId);
  else q.delete('variant');
  const s = q.toString();
  return s ? `?${s}` : '';
}

export const whatsappShareUrl = (pageUrl: string, title: string): string =>
  `https://wa.me/?text=${encodeURIComponent(`${title} ${pageUrl}`.trim())}`;

// --- Reviews (Req 9.12) -----------------------------------------------------------------------------------------------

export interface PdpReview { id: string; rating: number; title: string | null; body: string; author: string; createdAt: string; verified: boolean }
export type ReviewSort = 'newest' | 'highest' | 'lowest';

export function parsePdpReviews(raw: unknown): PdpReview[] {
  const rows = isObj(raw) ? arr(raw.reviews) : [];
  return rows.filter(isObj).flatMap((r) => {
    const rating = num(r.rating);
    if (!str(r.id) || rating === null || rating < 1 || rating > 5 || typeof r.body !== 'string') return [];
    return [{
      id: str(r.id), rating, title: str(r.title) || null, body: r.body, author: str(r.author), createdAt: str(r.created_at),
      verified: r.verified_purchase === true,
    }];
  });
}

export function sortReviews(rs: readonly PdpReview[], sort: ReviewSort): PdpReview[] {
  const t = (r: PdpReview) => Date.parse(r.createdAt) || 0;
  const by = {
    newest: (a: PdpReview, b: PdpReview) => t(b) - t(a),
    highest: (a: PdpReview, b: PdpReview) => b.rating - a.rating || t(b) - t(a),
    lowest: (a: PdpReview, b: PdpReview) => a.rating - b.rating || t(b) - t(a),
  }[sort];
  return [...rs].sort(by);
}

export const filterReviews = (rs: readonly PdpReview[], stars: number | null): PdpReview[] =>
  stars === null ? [...rs] : rs.filter((r) => Math.round(r.rating) === stars);

/** Review count per star, 5 down to 1. */
export function ratingDistribution(rs: readonly PdpReview[]): { stars: number; count: number }[] {
  return [5, 4, 3, 2, 1].map((stars) => ({ stars, count: rs.filter((r) => Math.round(r.rating) === stars).length }));
}

// --- Offers (Req 10.10) -----------------------------------------------------------------------------------------------

export interface PdpOffer { id: string; code: string | null; description: string; conditions: string[] }

const words = (x: unknown): string[] =>
  arr(x).flatMap((e) => (typeof e === 'string' ? [e] : isObj(e) ? [str(e.text) || str(e.description) || str(e.label)] : [])).map((s) => s.trim()).filter(Boolean);

/**
 * The Promotion offers that apply to this product, with their conditions. An offer with target conditions that the
 * product does not meet by ID or handle is left out; the text of the conditions is the Backend's own words.
 */
export function offersFor(offers: unknown, formatValue: (type: string, value: number, currency: string) => string): PdpOffer[] {
  const rows = isObj(offers) ? arr(offers.offers) : [];
  return rows.filter(isObj).flatMap((o) => {
    const v = isObj(o.value) ? o.value : null;
    const amount = v ? num(v.value) : null;
    if (!str(o.id) || !v || amount === null) return [];
    return [{
      id: str(o.id),
      code: o.is_automatic === true ? null : str(o.code) || null,
      description: formatValue(str(v.type), amount, str(v.currency_code).toUpperCase() || 'INR'),
      conditions: [...words(o.conditions), ...words(o.buy_conditions), ...words(o.target_conditions)],
    }];
  });
}

// --- Misc -------------------------------------------------------------------------------------------------------------

/** Plain text of a product's description for a meta description. */
export const plainText = (html: string, max = 160): string =>
  html.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, max);

/** Component_Switches from the public Store_Settings (`storefront.component.<key>`): only an explicit off turns one off. */
export function componentSwitches(settings: Record<string, unknown>): Record<string, boolean> {
  const prefix = 'storefront.component.';
  const out: Record<string, boolean> = {};
  for (const [k, v] of Object.entries(settings)) {
    if (!k.startsWith(prefix)) continue;
    const off = v === false || v === 'off' || (isObj(v) && (v.enabled === false || v.on === false));
    if (off) out[k.slice(prefix.length)] = false;
  }
  return out;
}

export interface CategoryRow { id: string; handle: string; name: string; parent: string | null }

export function parseCategories(raw: unknown): CategoryRow[] {
  const rows = isObj(raw) ? arr(raw.categories) : [];
  return rows.filter(isObj).map((c) => ({ id: str(c.id), handle: str(c.handle), name: str(c.name), parent: str(c.parent_category_id) || null }))
    .filter((c) => c.id && c.handle)
    .filter((c) => !c.handle.startsWith('demo-'));
}

/** Handles from the top-level category down to this one, joined with `/` (the `/shop/<category path>` of the PLP). */
export function categoryPath(rows: readonly CategoryRow[], id: string): string {
  const byId = new Map(rows.map((r) => [r.id, r]));
  const parts: string[] = [];
  for (let cur = byId.get(id), n = 0; cur && n < 10; cur = cur.parent ? byId.get(cur.parent) : undefined, n++) parts.unshift(cur.handle);
  return parts.join('/');
}

/** The chain of categories (top level first) down to `id`, for breadcrumbs. */
export function categoryChain(rows: readonly CategoryRow[], id: string): CategoryRow[] {
  const byId = new Map(rows.map((r) => [r.id, r]));
  const chain: CategoryRow[] = [];
  for (let cur = byId.get(id), n = 0; cur && n < 10; cur = cur.parent ? byId.get(cur.parent) : undefined, n++) chain.unshift(cur);
  return chain;
}
