// Price_Block: static render from build data, then a Live_Island update from Live_Data (Req 2.1, 10.1-10.6).
// The block reserves its height, so a late update cannot shift the layout. Interface text comes from `labels`.
import { useEffect, useState } from 'preact/hooks';
import '../styles/price-block.css';
import { buildPriceBlock, pickLiveVariant, type PriceInput } from '../lib/price-display';
import type { FormatLocale } from '../lib/format';
import { pageLiveClient } from '../lib/live-client';
import type { PriceBlockLabels } from './price-labels';

export interface PriceBlockProps {
  locale: FormatLocale;
  initial: PriceInput;
  labels: PriceBlockLabels;
  /** Live_Data request URL, or null for a static-only block. */
  liveUrl?: string | null;
  productId?: string;
  variantId?: string;
  /** Component_Switch: off shows the price and tax label only, with no Prior_Price, saving or tier table. */
  switchOn?: boolean;
  /** Shown for a Customer_Group price. */
  idPrefix?: string;
}

// Preact's JSX types declare `translate` as boolean, but the attribute needs the string "no".
const NO_TRANSLATE: Record<string, string> = { translate: 'no' };

const fill = (s: string, p: Record<string, string>) => s.replace(/\{(\w+)\}/g, (m, k: string) => p[k] ?? m);

export default function PriceBlock({
  locale,
  initial,
  labels,
  liveUrl = null,
  productId = '',
  variantId = '',
  switchOn = true,
  idPrefix = 'pm-price',
}: PriceBlockProps) {
  const [input, setInput] = useState<PriceInput>(initial);
  const [stale, setStale] = useState(false);
  const [explain, setExplain] = useState(false);

  useEffect(() => {
    if (!liveUrl) return;
    let cancelled = false;
    // One shared request per page; a signed-in customer's prices come from store_price_for_customer (Req 2.7).
    pageLiveClient()
      .load(liveUrl)
      .then((res) => {
        if (cancelled) return;
        const v = res.status === 'ready' ? pickLiveVariant(res.body, productId, variantId) : null;
        const amount = v?.price?.amount;
        if (!v || typeof amount !== 'number') return setStale(true);
        // Live_Data is the truth: a missing prior_price ends the Price_Reduction.
        setInput((cur) => ({ ...cur, amount, priorPrice: v.prior_price ?? null }));
        setStale(false);
      })
      .catch(() => !cancelled && setStale(true));
    return () => {
      cancelled = true;
    };
  }, [liveUrl, productId, variantId]);

  const m = buildPriceBlock(switchOn ? input : { amount: input.amount, currency: input.currency }, locale);
  const explainId = `${idPrefix}-explain`;

  if (m.onRequest) {
    return (
      <div class="pm-price-block pm-price-block--request" data-state="request">
        <p class="pm-price-block__request">{labels.onRequest}</p>
        <p class="pm-price-block__note">{labels.onRequestHint}</p>
      </div>
    );
  }

  return (
    <div class="pm-price-block" data-state={m.reduction ? 'reduction' : 'regular'} data-stale={stale ? 'true' : 'false'}>
      {m.customerGroup && <p class="pm-price-block__group">{labels.yourPrice}</p>}
      <p class="pm-price-block__line">
        <span class="pm-visually-hidden">{fill(labels.srCurrent, { price: m.price ?? '' })}</span>
        <strong class="pm-price-block__now" {...NO_TRANSLATE} aria-hidden="true">{m.price}</strong>
        {m.reduction && (
          <>
            <span class="pm-visually-hidden">{fill(labels.srPrior, { price: m.priorPrice ?? '' })}</span>
            <del class="pm-price-block__prior" {...NO_TRANSLATE} aria-hidden="true">{m.priorPrice}</del>
          </>
        )}
      </p>
      <p class="pm-price-block__tax">{labels.inclTax}</p>
      {m.reduction && (
        <p class="pm-price-block__saving">
          <span>
            {m.savingPercent
              ? fill(labels.saving, { amount: m.savingAmount ?? '', percent: m.savingPercent })
              : fill(labels.savingAmountOnly, { amount: m.savingAmount ?? '' })}
          </span>
          <button
            type="button"
            class="pm-price-block__explain-btn"
            aria-expanded={explain}
            aria-controls={explainId}
            onClick={() => setExplain((v) => !v)}
          >
            {labels.explainControl}
          </button>
        </p>
      )}
      {m.reduction && (
        <p id={explainId} class="pm-price-block__note" hidden={!explain}>
          {labels.priorExplain}
        </p>
      )}
      {m.mrp && (
        <p class="pm-price-block__mrp">
          {labels.mrp} <span {...NO_TRANSLATE}>{m.mrp}</span>
        </p>
      )}
      {m.unitPrice && (
        <p class="pm-price-block__unit">
          {labels.unitPrice} <span {...NO_TRANSLATE}>{m.unitPrice}</span>
        </p>
      )}
      {m.tiers.length > 0 && (
        <table class="pm-price-block__tiers">
          <caption>{labels.tiersCaption}</caption>
          <thead>
            <tr>
              <th scope="col">{labels.tierQuantity}</th>
              <th scope="col">{labels.tierPrice}</th>
              <th scope="col">{labels.tierSaving}</th>
            </tr>
          </thead>
          <tbody>
            {m.tiers.map((t) => (
              <tr key={t.quantity}>
                <th scope="row">{t.quantity}</th>
                <td {...NO_TRANSLATE}>{t.unitPrice}</td>
                <td {...NO_TRANSLATE}>{t.saving ?? labels.noSaving}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
      {stale && <p class="pm-price-block__note">{labels.cartConfirms}</p>}
    </div>
  );
}
