// Build-time reads for the PDP. The build data step writes src/data/*.json; each read falls back to an empty value, so a build
// with no backend data still succeeds. Reviews are read per product from `store_list_reviews` (a review change triggers a build).
import { withRealMedia } from './product-media';
type Obj = Record<string, unknown>;
const files = import.meta.glob<unknown>(
  ['../data/catalog.json', '../data/offers.json', '../data/delivery-rules.json', '../data/settings.json'],
  { eager: true, import: 'default' },
);
const isObj = (x: unknown): x is Obj => !!x && typeof x === 'object' && !Array.isArray(x);
const read = (name: string): unknown => files[`../data/${name}.json`];
// The starter catalogue ships demo ranges (fashion, electronics, groceries). They are not Plusmark products and
// must never surface in the storefront, even though the shared backend still holds them.
const isDemoProduct = (p: Obj): boolean =>
  (Array.isArray(p.categories) ? p.categories : []).some((c) => isObj(c) && String(c.handle ?? '').startsWith('demo-'));

export interface PdpBuildData {
  products: Obj[];
  currency: string;
  regionId: string | null;
  offers: unknown;
  rules: Obj;
  settings: Obj;
}

export function loadPdpData(): PdpBuildData {
  const catalog = read('catalog');
  const rules = read('delivery-rules');
  const settings = read('settings');
  return {
    products: isObj(catalog) && Array.isArray(catalog.products) ? catalog.products.filter(isObj).filter((p) => !isDemoProduct(p)).map(withRealMedia) : [],
    currency: (isObj(catalog) && typeof catalog.currency_code === 'string' && catalog.currency_code ? catalog.currency_code : 'inr').toUpperCase(),
    regionId: isObj(catalog) && typeof catalog.region_id === 'string' ? catalog.region_id : null,
    offers: read('offers') ?? { offers: [] },
    rules: isObj(rules) ? rules : {},
    settings: isObj(settings) ? settings : {},
  };
}

/** The published reviews of a product (newest first, at most 50). `enabled` is false when the reviews Optional_Feature is off, or the backend is not configured or fails. */
export async function loadReviews(productId: string): Promise<{ enabled: boolean; reviews: unknown }> {
  const env = import.meta.env as Record<string, string | undefined>;
  const base = (env.PUBLIC_SUPABASE_URL ?? '').replace(/\/+$/, '');
  const key = env.PUBLIC_SUPABASE_PUBLISHABLE_KEY ?? '';
  if (!base || !key || /^sb_secret_/.test(key) || process.env.BUILD_DATA_MODE === 'fixture') return { enabled: false, reviews: [] };
  try {
    const q = new URLSearchParams({ p_product_id: productId, p_limit: '50' });
    const res = await fetch(`${base}/rest/v1/rpc/store_list_reviews?${q}`, {
      headers: { apikey: key, Authorization: `Bearer ${key}`, Accept: 'application/json', 'Accept-Profile': 'api' },
      signal: AbortSignal.timeout(15000),
    });
    if (!res.ok) return { enabled: false, reviews: [] };
    const body: unknown = await res.json();
    return isObj(body) && Array.isArray(body.reviews) ? { enabled: true, reviews: body } : { enabled: false, reviews: [] };
  } catch {
    // The reviews Optional_Feature may be off, or the backend unreachable: the page builds without them.
    return { enabled: false, reviews: [] };
  }
}
