/**
 * Price block model (Req 10.1-10.6; design "Price block").
 * Pure: turns a variant's price, Prior_Price, MRP, net quantity and tier prices into display values.
 * - The Prior_Price, the saving and the sale state exist only in a Price_Reduction: the backend supplied
 *   a Prior_Price above the current price. They are never derived from the MRP.
 * - The MRP is shown on its own line and is never struck through and never used for a saving.
 */
import {
  formatMoney,
  formatPercent,
  formatUnitPrice,
  savingAmount,
  savingPercent,
  tierSavings,
  formatTier,
  type FormatLocale,
  type NetUnit,
} from './format';

export interface PriceInput {
  /** Current price in major units, tax-inclusive; null or undefined means price on request. */
  amount: number | null | undefined;
  currency?: string;
  /** Supplied by the backend only inside a genuine Price_Reduction. */
  priorPrice?: number | null;
  mrp?: number | null;
  netQuantity?: number | null;
  netQuantityUnit?: NetUnit | string | null;
  /** The Business_Preset requires a unit sale price (Req 10.5). */
  requireUnitPrice?: boolean;
  tiers?: { minQuantity: number; amount: number }[] | null;
  /** The price is a Customer_Group price for the signed-in shopper. */
  customerGroup?: boolean;
}

export interface PriceTierView {
  quantity: string;
  unitPrice: string;
  /** Saving per unit against the single-unit price; null when the tier saves nothing. */
  saving: string | null;
}

export interface PriceBlockModel {
  /** True when no price is available: show the price-on-request state. */
  onRequest: boolean;
  price: string | null;
  /** Always true when a price is shown: the text "incl. of all taxes" follows the price. */
  taxInclusive: boolean;
  reduction: boolean;
  priorPrice: string | null;
  savingAmount: string | null;
  /** The whole-number percentage, rounded down, formatted ("20%"). */
  savingPercent: string | null;
  mrp: string | null;
  unitPrice: string | null;
  tiers: PriceTierView[];
  customerGroup: boolean;
}

const finite = (n: unknown): n is number => typeof n === 'number' && Number.isFinite(n);

/** True only when the backend supplied a Prior_Price strictly above a positive current price. */
export function isPriceReduction(amount: number | null | undefined, prior: number | null | undefined): boolean {
  return finite(amount) && finite(prior) && amount >= 0 && prior > amount;
}

export function buildPriceBlock(input: PriceInput, locale: FormatLocale = 'en'): PriceBlockModel {
  const currency = input.currency ?? 'INR';
  const empty: PriceBlockModel = {
    onRequest: true, price: null, taxInclusive: false, reduction: false, priorPrice: null,
    savingAmount: null, savingPercent: null, mrp: null, unitPrice: null, tiers: [], customerGroup: false,
  };
  const { amount } = input;
  if (!finite(amount) || amount < 0) return empty;

  const reduction = isPriceReduction(amount, input.priorPrice);
  const prior = reduction ? (input.priorPrice as number) : null;
  const pct = prior === null ? 0 : savingPercent(prior, amount);

  const unit =
    input.requireUnitPrice && finite(input.netQuantity) && input.netQuantityUnit
      ? formatUnitPrice(amount, input.netQuantity, input.netQuantityUnit, currency, locale)
      : null;

  const tiers = tierSavings(
    amount,
    (input.tiers ?? [])
      .filter((t) => finite(t.minQuantity) && finite(t.amount) && t.minQuantity > 1 && t.amount >= 0)
      .map((t) => ({ minQuantity: t.minQuantity, unitPrice: t.amount })),
  ).map((t): PriceTierView => {
    const f = formatTier(t, currency, locale);
    return { quantity: f.quantity, unitPrice: f.unitPrice, saving: t.savingPerUnit > 0 ? f.saving : null };
  });

  return {
    onRequest: false,
    price: formatMoney(amount, currency, locale),
    taxInclusive: true,
    reduction,
    priorPrice: prior === null ? null : formatMoney(prior, currency, locale),
    savingAmount: prior === null ? null : formatMoney(savingAmount(prior, amount), currency, locale),
    // A saving under 1% rounds down to 0%: show the amount only.
    savingPercent: prior !== null && pct >= 1 ? formatPercent(pct, locale) : null,
    mrp: finite(input.mrp) && input.mrp > 0 ? formatMoney(input.mrp, currency, locale) : null,
    unitPrice: unit && unit !== '—' ? unit : null,
    tiers,
    customerGroup: !!input.customerGroup,
  };
}

/** The slice of a Live_Data variant that the price block reads. */
export interface LiveVariantPrice {
  id?: string;
  price?: { amount?: number | null; currency_code?: string } | null;
  prior_price?: number | null;
}

/** Finds a variant's price update in a Live_Data response body; null when absent. */
export function pickLiveVariant(body: unknown, productId: string, variantId: string): LiveVariantPrice | null {
  const products = (body as { products?: unknown })?.products;
  if (!Array.isArray(products)) return null;
  const p = products.find((x) => x && typeof x === 'object' && (x as { id?: unknown }).id === productId) as
    | { available?: boolean; variants?: LiveVariantPrice[] }
    | undefined;
  if (!p || p.available === false || !Array.isArray(p.variants)) return null;
  return p.variants.find((v) => v?.id === variantId) ?? null;
}
