// Text of the request forms (src/i18n/requests.<locale>.json). Used at build time and bundled into the page scripts.
import en from '../../i18n/requests.en.json';
import hi from '../../i18n/requests.hi.json';
import { interpolate, type Locale, type Params } from '../i18n';

const DICT: Record<Locale, Record<string, string>> = { en, hi: { ...en, ...hi } };

/** Text of the request forms in a language (English fills any gap). */
export const rq = (locale: Locale, key: string, params?: Params): string => interpolate(DICT[locale][key] ?? key, params);

export const requestTextFor = (locale: string): ((key: string, params?: Params) => string) => {
  const l: Locale = locale === 'hi' ? 'hi' : 'en';
  return (key, params) => rq(l, key, params);
};
