/**
 * Search engine data (Req 20, design "Search engine data"). Pure, so the layout, the pages and the tests share it.
 * Meta descriptions, `noindex` rules, JSON-LD (Product, BreadcrumbList, Organization) and social card tags.
 * Sitemaps and robots.txt come from scripts/build-data/seo.mjs, which the Site_Build runs after Astro.
 */
import type { PdpModel, PdpReview, PdpVariantModel } from './pdp';
import { filterCount, parsePlpState } from './plp-state';

export const DESCRIPTION_MAX = 155;

/** Plain text of `html` or text: tags removed, whitespace collapsed. */
export function stripText(s: string): string {
  return s.replace(/<[^>]*>/g, ' ').replace(/&nbsp;/gi, ' ').replace(/&amp;/gi, '&').replace(/&lt;/gi, '<').replace(/&gt;/gi, '>').replace(/&quot;/gi, '"').replace(/&#39;/g, "'").replace(/\s+/g, ' ').trim();
}

/** A description of at most 155 characters, cut at a word end with an ellipsis (Req 20.1). Empty text gives the fallback. */
export function metaDescription(text: string, fallback = ''): string {
  const plain = stripText(text) || stripText(fallback);
  const chars = [...plain];
  if (chars.length <= DESCRIPTION_MAX) return plain;
  const cut = chars.slice(0, DESCRIPTION_MAX - 1).join('');
  const space = cut.lastIndexOf(' ');
  return `${(space > DESCRIPTION_MAX / 2 ? cut.slice(0, space) : cut).replace(/[\s,;:.\-–—]+$/, '')}…`;
}

/** A unique page title: the page's own name first, then the brand. */
export const pageTitle = (name: string, brand: string): string => (name && brand ? `${name} | ${brand}` : name || brand);

/** The robots meta value of a page, or null when the page may be indexed (Req 20.2). */
export const robotsContent = (noindex: boolean): string | null => (noindex ? 'noindex, follow' : null);

/** True for a PLP URL whose query holds more than one filter value; the page then asks not to be indexed (Req 20.2). */
export const isOverFiltered = (search: string): boolean => filterCount(parsePlpState(search)) > 1;

type Json = Record<string, unknown>;
const abs = (url: string, site: string): string => (/^https?:\/\//.test(url) ? url : `${site.replace(/\/+$/, '')}${url.startsWith('/') ? '' : '/'}${url}`);

export interface Crumb { label: string; href: string }

/** `BreadcrumbList` of a PLP or PDP (Req 20.5). The last crumb has no link in the page and takes the page URL. */
export function breadcrumbJsonLd(crumbs: readonly Crumb[], pageUrl: string, site: string): Json {
  return {
    '@context': 'https://schema.org',
    '@type': 'BreadcrumbList',
    itemListElement: crumbs.map((c, i) => ({
      '@type': 'ListItem',
      position: i + 1,
      name: c.label,
      item: c.href ? abs(c.href, site) : pageUrl,
    })),
  };
}

export interface OrganizationInput { name: string; logoUrl?: string; phone?: string; email?: string }

/** `FAQPage` for the questions the home page actually answers on screen. Nothing is added that a shopper cannot read. */
export function faqJsonLd(items: readonly { q: string; a: string }[]): Json {
  return {
    '@context': 'https://schema.org',
    '@type': 'FAQPage',
    mainEntity: items.map((i) => ({
      '@type': 'Question',
      name: i.q,
      acceptedAnswer: { '@type': 'Answer', text: i.a },
    })),
  };
}

/** `Organization` of the home page, from the Client_Branding name and logo and the contact details (Req 20.5). */
export function organizationJsonLd(o: OrganizationInput, siteUrl: string): Json {
  const contact: Json = { '@type': 'ContactPoint', contactType: 'customer support' };
  if (o.phone) contact.telephone = o.phone;
  if (o.email) contact.email = o.email;
  return {
    '@context': 'https://schema.org',
    '@type': 'Organization',
    name: o.name,
    url: siteUrl,
    ...(o.logoUrl ? { logo: abs(o.logoUrl, siteUrl) } : {}),
    ...(contact.telephone || contact.email ? { contactPoint: contact } : {}),
  };
}

export type SchemaAvailability = 'https://schema.org/InStock' | 'https://schema.org/OutOfStock' | 'https://schema.org/BackOrder';

/** Availability from the build's stock figure when it has one, otherwise in stock (a listed product is on sale). */
export function availabilityOf(v: PdpVariantModel, quantity: unknown): SchemaAvailability {
  const q = typeof quantity === 'number' ? quantity : null;
  if (q !== null && q <= 0) return v.allowBackorder ? 'https://schema.org/BackOrder' : 'https://schema.org/OutOfStock';
  return 'https://schema.org/InStock';
}

export interface ProductLdInput {
  model: PdpModel;
  /** Absolute URL of the page. */
  url: string;
  brand: string;
  /** Published reviews of the product, the only source of the rating (Req 20.4). */
  reviews: readonly PdpReview[];
  /** Raw catalog product, for the stock figures and a Price_List end time. */
  raw?: Json;
}

const priceText = (n: number): string => String(Math.round(n * 100) / 100);

/** `Product` with an `Offer` (one priced variant) or an `AggregateOffer` (several), at the built prices (Req 20.3, 20.4). */
export function productJsonLd(i: ProductLdInput): Json {
  const { model, raw } = i;
  const prices = (raw && typeof raw.variant_prices === 'object' && raw.variant_prices ? raw.variant_prices : {}) as Record<string, Json | undefined>;
  const stock = (raw && typeof raw.variant_stock === 'object' && raw.variant_stock ? raw.variant_stock : {}) as Record<string, unknown>;
  const priced = model.variants.filter((v) => v.price !== null);
  const endOf = (v: PdpVariantModel): string | undefined => {
    const e = prices[v.id]?.ends_at ?? prices[v.id]?.sale_ends_at;
    return typeof e === 'string' && Number.isFinite(Date.parse(e)) ? new Date(e).toISOString() : undefined;
  };
  const offerOf = (v: PdpVariantModel): Json => ({
    '@type': 'Offer',
    price: priceText(v.price as number),
    priceCurrency: model.currency,
    availability: availabilityOf(v, stock[v.id]),
    url: i.url,
    ...(endOf(v) ? { priceValidUntil: endOf(v) } : {}),
  });
  const ld: Json = {
    '@context': 'https://schema.org',
    '@type': 'Product',
    name: model.title,
    image: model.images.map((m) => m.url),
    brand: { '@type': 'Brand', name: i.brand },
  };
  const description = metaDescription(model.description || model.subtitle);
  if (description) ld.description = description;
  const sku = (priced[0] ?? model.variants[0])?.sku;
  if (sku) ld.sku = sku;
  if (priced.length === 1) ld.offers = offerOf(priced[0]);
  else if (priced.length > 1) {
    const amounts = priced.map((v) => v.price as number);
    const ends = priced.map(endOf).filter((e): e is string => !!e).sort();
    ld.offers = {
      '@type': 'AggregateOffer',
      lowPrice: priceText(Math.min(...amounts)),
      highPrice: priceText(Math.max(...amounts)),
      priceCurrency: model.currency,
      offerCount: priced.length,
      availability: priced.some((v) => availabilityOf(v, stock[v.id]) === 'https://schema.org/InStock') ? 'https://schema.org/InStock' : availabilityOf(priced[0], stock[priced[0].id]),
      url: i.url,
      ...(ends.length ? { priceValidUntil: ends[0] } : {}),
    };
  }
  if (i.reviews.length > 0) {
    const avg = i.reviews.reduce((s, r) => s + r.rating, 0) / i.reviews.length;
    ld.aggregateRating = { '@type': 'AggregateRating', ratingValue: Math.round(avg * 10) / 10, reviewCount: i.reviews.length };
  }
  return ld;
}

/** JSON for a `<script type="application/ld+json">` body; `<` is escaped so text cannot close the tag. */
export const jsonLdText = (data: unknown): string => JSON.stringify(data).replace(/</g, '\\u003c').replace(/\u2028/g, '\\u2028').replace(/\u2029/g, '\\u2029');

export interface SocialInput { title: string; description?: string; image?: string; url: string; type?: 'website' | 'product'; locale: 'en' | 'hi'; siteName?: string }
export interface MetaTag { attr: 'name' | 'property'; key: string; content: string }

/** Open Graph and Twitter card tags with the page's title, description and main image (Req 20.7). */
export function socialTags(s: SocialInput): MetaTag[] {
  const tags: MetaTag[] = [
    { attr: 'property', key: 'og:type', content: s.type ?? 'website' },
    { attr: 'property', key: 'og:title', content: s.title },
    { attr: 'property', key: 'og:url', content: s.url },
    { attr: 'property', key: 'og:locale', content: s.locale === 'hi' ? 'hi_IN' : 'en_IN' },
    { attr: 'name', key: 'twitter:card', content: s.image ? 'summary_large_image' : 'summary' },
    { attr: 'name', key: 'twitter:title', content: s.title },
  ];
  if (s.siteName) tags.push({ attr: 'property', key: 'og:site_name', content: s.siteName });
  if (s.description) tags.push({ attr: 'property', key: 'og:description', content: s.description }, { attr: 'name', key: 'twitter:description', content: s.description });
  if (s.image) tags.push({ attr: 'property', key: 'og:image', content: s.image }, { attr: 'name', key: 'twitter:image', content: s.image });
  return tags;
}
