// Request-time reads of an On_Demand_Page (design KD-5). The Worker's internal route renders the same components as the
// build, but takes the record from the Store_API instead of src/data/*.json. Only the Supabase project is called (Req 21.7).
type Obj = Record<string, unknown>;
type Fetcher = (input: string, init?: RequestInit) => Promise<Response>;
const isObj = (x: unknown): x is Obj => !!x && typeof x === 'object' && !Array.isArray(x);

export interface OnDemandEnv {
  SUPABASE_URL?: string;
  SUPABASE_ANON_KEY?: string;
}

export interface OnDemandScope {
  regionId: string | null;
  currency: string;
}

async function rpc(env: OnDemandEnv, name: string, params: Record<string, string>, doFetch: Fetcher): Promise<unknown> {
  const base = (env.SUPABASE_URL ?? '').replace(/\/+$/, '');
  if (!base) throw new Error('SUPABASE_URL is not configured');
  const headers: Record<string, string> = { Accept: 'application/json', 'Accept-Profile': 'api' };
  if (env.SUPABASE_ANON_KEY) {
    headers.apikey = env.SUPABASE_ANON_KEY;
    headers.Authorization = `Bearer ${env.SUPABASE_ANON_KEY}`;
  }
  const q = new URLSearchParams(params).toString();
  const res = await doFetch(`${base}/rest/v1/rpc/${name}${q ? `?${q}` : ''}`, { method: 'GET', headers });
  if (!res.ok) throw new Error(`${name} answered ${res.status}`);
  return res.json();
}

const scopeParams = (s: OnDemandScope): Record<string, string> => ({
  ...(s.regionId ? { p_region_id: s.regionId } : {}),
  ...(s.currency ? { p_currency_code: s.currency.toLowerCase() } : {}),
});

/** One published product by handle, or null when the Store_API has none. */
export async function loadProduct(env: OnDemandEnv, handle: string, scope: OnDemandScope, doFetch: Fetcher = fetch): Promise<Obj | null> {
  const body = await rpc(env, 'store_get_product', { p_handle: handle, ...scopeParams(scope) }, doFetch);
  return isObj(body) && typeof body.id === 'string' && !isObj(body.error) ? body : null;
}

/** The `{ categories: [...] }` and `{ collections: [...] }` documents, in the shape of the build's JSON files. */
export async function loadTaxonomy(env: OnDemandEnv, kind: 'categories' | 'collections', doFetch: Fetcher = fetch): Promise<Obj> {
  const body = await rpc(env, kind === 'categories' ? 'store_list_categories' : 'store_list_collections', {}, doFetch);
  return isObj(body) && Array.isArray(body[kind]) ? body : { [kind]: [] };
}

export interface Listing {
  items: Obj[];
  total: number;
  facets: Obj;
}

/** First page (24 products) of a category (with the ids below it) or a collection. */
export async function loadListing(
  env: OnDemandEnv,
  scope: OnDemandScope,
  match: { categoryIds?: string[]; collectionId?: string },
  doFetch: Fetcher = fetch,
): Promise<Listing> {
  const params: Record<string, string> = { ...scopeParams(scope), p_page: '1', p_page_size: '24', p_sort: 'newest' };
  if (match.categoryIds?.length) params.p_category_ids = `{${match.categoryIds.map((i) => `"${i}"`).join(',')}}`;
  if (match.collectionId) params.p_collection_ids = `{"${match.collectionId}"}`;
  const body = await rpc(env, 'store_list_products', params, doFetch);
  if (!isObj(body) || !Array.isArray(body.items)) return { items: [], total: 0, facets: {} };
  return {
    items: body.items.filter(isObj),
    total: typeof body.total === 'number' ? body.total : body.items.length,
    facets: isObj(body.facets) ? body.facets : {},
  };
}

/** Splits `rest` of `/_ondemand/<rest>` into the language and the record kind. Null for any other shape. */
export function parseOnDemandPath(rest: string): { locale: 'en' | 'hi'; kind: 'product' | 'category' | 'collection'; segments: string[] } | null {
  let parts = rest.split('/').filter(Boolean);
  let locale: 'en' | 'hi' = 'en';
  if (parts[0] === 'hi') {
    locale = 'hi';
    parts = parts.slice(1);
  }
  if (parts.length < 2) return null;
  const segments = parts.slice(1).map((s) => {
    try { return decodeURIComponent(s); } catch { return s; }
  });
  if (parts[0] === 'product' && segments.length === 1) return { locale, kind: 'product', segments };
  if (parts[0] === 'collections' && segments.length === 1) return { locale, kind: 'collection', segments };
  if (parts[0] === 'shop') return { locale, kind: 'category', segments };
  return null;
}
