// Running Experiments written by the build data step (scripts/build-data/data.mjs) to src/data/experiments.json.
// Without the file there are none.
import { normalizeExperiments, type RunningExperiment } from './head-script';

export function loadExperiments(): RunningExperiment[] {
  const files = import.meta.glob<unknown>('../data/experiments.json', { eager: true, import: 'default' });
  return normalizeExperiments(Object.values(files)[0]);
}
