// Optional_Features and the reply time from the public Store_Settings (Req 15.6). A feature whose setting is missing
// or not true is off, so a build without the data shows no entry point.
import { componentSwitches } from '../pdp';

export interface Features {
  reviews: boolean;
  enquiries: boolean;
  quotations: boolean;
  wishlists: boolean;
  /** The Back_In_Stock_Alert Component_Switch (on unless the store switched it off). */
  backInStock: boolean;
  /** Hours within which the store replies to an Enquiry or Quotation request. */
  replyHours: number;
}

export const DEFAULT_REPLY_HOURS = 48;

export function featuresFrom(settings: Record<string, unknown>): Features {
  const on = (k: string): boolean => settings[`feature.${k}`] === true;
  const hours = Number(settings['storefront.enquiry_reply_hours']);
  return {
    reviews: on('reviews'),
    enquiries: on('enquiries'),
    quotations: on('quotations'),
    wishlists: on('wishlists'),
    backInStock: componentSwitches(settings).back_in_stock_alert !== false,
    replyHours: Number.isInteger(hours) && hours > 0 ? hours : DEFAULT_REPLY_HOURS,
  };
}
