// Browser storage allowlist (design "Data Models", Property 28). The only module that touches
// localStorage / sessionStorage; every other key is rejected.

export type StorageKind = 'local' | 'session';
export type StorageClass = 'essential' | 'analytics';

const ALLOWED: Record<string, { kind: StorageKind; cls: StorageClass }> = {
  'sf.auth': { kind: 'local', cls: 'essential' },
  'sf.cart': { kind: 'local', cls: 'essential' },
  'sf.order': { kind: 'session', cls: 'essential' },
  'sf.lang': { kind: 'local', cls: 'essential' },
  'sf.consent': { kind: 'local', cls: 'essential' },
  'sf.pin': { kind: 'local', cls: 'essential' },
  'sf.recent': { kind: 'local', cls: 'essential' },
  'sf.saved': { kind: 'local', cls: 'essential' },
  'sf.searches': { kind: 'local', cls: 'essential' },
  'sf.shown': { kind: 'session', cls: 'essential' },
  'sf.closed': { kind: 'local', cls: 'essential' },
  'sf.sid': { kind: 'local', cls: 'analytics' },
  'sf.exp': { kind: 'local', cls: 'analytics' },
  'sf.events': { kind: 'local', cls: 'analytics' },
};

export type StorageKey = string;

let analyticsAllowed = false;
const memory = new Map<string, string>();

/** Set from the Consent_Choice; withdrawing consent removes the analytics keys. */
export function setAnalyticsConsent(allowed: boolean): void {
  analyticsAllowed = allowed;
  if (!allowed) for (const k of Object.keys(ALLOWED)) if (ALLOWED[k].cls === 'analytics') removeItem(k);
}

function area(key: string): Storage | null {
  const spec = ALLOWED[key];
  if (!spec) throw new Error(`Storage key "${key}" is not on the allowlist`);
  try {
    return spec.kind === 'local' ? globalThis.localStorage : globalThis.sessionStorage;
  } catch {
    return null;
  }
}

function permitted(key: string): boolean {
  return ALLOWED[key].cls === 'essential' || analyticsAllowed;
}

export function getItem(key: StorageKey): string | null {
  const a = area(key);
  if (!permitted(key)) return null;
  try {
    return a ? a.getItem(key) : (memory.get(key) ?? null);
  } catch {
    return memory.get(key) ?? null;
  }
}

export function setItem(key: StorageKey, value: string): boolean {
  const a = area(key);
  if (!permitted(key)) return false;
  try {
    if (a) a.setItem(key, value);
    else memory.set(key, value);
  } catch {
    memory.set(key, value);
  }
  return true;
}

export function removeItem(key: StorageKey): void {
  const a = area(key);
  memory.delete(key);
  try {
    a?.removeItem(key);
  } catch {
    /* storage unavailable */
  }
}

export function getJson<T>(key: StorageKey): T | null {
  const raw = getItem(key);
  if (raw == null) return null;
  try {
    return JSON.parse(raw) as T;
  } catch {
    return null;
  }
}

export function setJson(key: StorageKey, value: unknown): boolean {
  return setItem(key, JSON.stringify(value));
}

// --- Cart session (sf.cart): the Cart ID and Cart_Token stay on the device (Req 12.8). ---

export interface StoredCart {
  id: string;
  token: string;
  /** Line snapshots keyed by line id: what the shopper last saw, to mark a line that changed (Req 12.4). */
  lines?: Record<string, StoredCartLine>;
}

export interface StoredCartLine {
  price?: number;
  available?: boolean;
  qty?: number;
  variantId?: string;
  productId?: string;
  title?: string;
  variantTitle?: string;
  handle?: string;
  thumbnail?: string | null;
}

export const getCart = (): StoredCart | null => {
  const c = getJson<StoredCart>('sf.cart');
  return c && typeof c.id === 'string' && typeof c.token === 'string' ? c : null;
};
export const setCart = (cart: StoredCart): boolean => setJson('sf.cart', cart);
export const clearCart = (): void => removeItem('sf.cart');
