// Build-time helper: collects the basket and journey text from the dictionaries (keys `journey.*`).
import { t, type Locale } from '../lib/i18n';

const KEYS = [
  'freeProgress', 'freeReached', 'savings', 'goesWellTitle', 'bundleTitle', 'bundleTotal', 'bundleSave', 'bundleAdd', 'add',
  'recentTitle', 'recentClear', 'firstOrderTitle', 'firstOrderClose', 'progressLabel', 'stepDone', 'stepCurrent', 'stickyAdd',
] as const;

export type JourneyLabels = Record<(typeof KEYS)[number], string>;

export const journeyLabels = (locale: Locale): JourneyLabels =>
  Object.fromEntries(KEYS.map((k) => [k, t(locale, `journey.${k}`)])) as JourneyLabels;
