// The PDP's interface text (src/i18n/pdp.<locale>.json). Kept in its own files so the page's text ships as one object to
// the page's island; other text comes from the shared dictionaries through `t`.
import en from '../i18n/pdp.en.json';
import hi from '../i18n/pdp.hi.json';
import { interpolate, type Locale } from './i18n';

export type PdpText = typeof en;
export type PdpTextKey = keyof PdpText;
const DICT: Record<Locale, PdpText> = { en, hi };

/** The full text object of a locale; a missing Hindi key falls back to English. */
export const pdpText = (locale: Locale): PdpText => ({ ...en, ...DICT[locale] });

export const pt = (locale: Locale, key: PdpTextKey, params?: Record<string, string | number>): string =>
  interpolate(pdpText(locale)[key], params);

/** Fills `{name}` placeholders of an already-loaded text. */
export const fillText = (s: string, p: Record<string, string | number>): string => interpolate(s, p);
