// Legal and content pages (Req 16.1-16.4, 16.6, 16.7, 16.10, 17.4). Pure helpers over the public Store_Settings that the
// build data step wrote to src/data/settings.json. All admin-authored text passes through the sanitizer (Req 21.3).
import { sanitizeHtml, toPlainText } from './sanitize';
import type { Locale } from './i18n';

export const POLICY_SLUGS = ['returns', 'refunds', 'exchanges', 'cancellations', 'shipping', 'payments', 'warranties', 'privacy', 'terms'] as const;
export type PolicySlug = (typeof POLICY_SLUGS)[number];

/** Settings key of each policy inside `storefront.policies`; the privacy notice has its own setting. */
const POLICY_KEY: Record<Exclude<PolicySlug, 'privacy'>, string> = {
  returns: 'returns', refunds: 'refunds', exchanges: 'exchanges', cancellations: 'cancellations',
  shipping: 'shipping', payments: 'payments', warranties: 'warranties', terms: 'terms',
};

export const ACK_HOURS = 48;
export const RESOLUTION_MONTHS = 1;
/** National Consumer Helpline of the Department of Consumer Affairs. */
export const NATIONAL_CONSUMER_HELPLINE = { phone: '1915', alternatePhone: '1800-11-4000', website: 'https://consumerhelpline.gov.in' };

type Settings = Record<string, unknown>;
const isObj = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v);
const str = (v: unknown): string => (typeof v === 'string' ? v : '');

export function isPolicySlug(slug: string): slug is PolicySlug {
  return (POLICY_SLUGS as readonly string[]).includes(slug);
}

/** Content text for a locale: the locale's text, else English (marked as a fallback), else empty. */
function pickLocalized(v: unknown, locale: Locale): { html: string; fallback: boolean } {
  if (typeof v === 'string') return { html: sanitizeHtml(v), fallback: locale !== 'en' };
  if (!isObj(v)) return { html: '', fallback: false };
  const own = sanitizeHtml(str(v[locale]));
  if (own) return { html: own, fallback: false };
  if (locale === 'en') return { html: '', fallback: false };
  const en = sanitizeHtml(str(v.en));
  return { html: en, fallback: Boolean(en) };
}

export interface PolicyContent {
  slug: PolicySlug;
  /** Sanitized HTML; empty when the store has not written the policy. */
  html: string;
  /** True when Hindi was asked for and the English text is shown instead. */
  fallback: boolean;
}

export function policyContent(settings: Settings, slug: PolicySlug, locale: Locale): PolicyContent {
  const raw = slug === 'privacy'
    ? settings['storefront.privacy_notice']
    : isObj(settings['storefront.policies']) ? settings['storefront.policies'][POLICY_KEY[slug]] : undefined;
  return { slug, ...pickLocalized(raw, locale) };
}

export interface SellerPage {
  seller: { legalName: string; registeredAddress: string; gstin: string; phone: string; email: string };
  grievance: { name: string; designation: string; phone: string; email: string };
  acknowledgementHours: number;
  resolutionMonths: number;
  helpline: typeof NATIONAL_CONSUMER_HELPLINE;
}

export function sellerPage(settings: Settings): SellerPage {
  const s = isObj(settings['storefront.seller_details']) ? settings['storefront.seller_details'] : {};
  const g = isObj(settings['storefront.grievance_officer']) ? settings['storefront.grievance_officer'] : {};
  return {
    seller: {
      legalName: toPlainText(str(s.legal_name)), registeredAddress: toPlainText(str(s.registered_address)), gstin: toPlainText(str(s.gstin)),
      phone: toPlainText(str(s.customer_care_phone)), email: toPlainText(str(s.customer_care_email)),
    },
    grievance: { name: toPlainText(str(g.name)), designation: toPlainText(str(g.designation)), phone: toPlainText(str(g.phone)), email: toPlainText(str(g.email)) },
    acknowledgementHours: ACK_HOURS,
    resolutionMonths: RESOLUTION_MONTHS,
    helpline: NATIONAL_CONSUMER_HELPLINE,
  };
}

export interface ContactPage { phone: string; email: string; whatsapp: string; supportHours: string }

/** Phone and email come from the Seller_Details; WhatsApp and support hours from `storefront.contact` (Req 16.10). */
export function contactPage(settings: Settings, locale: Locale): ContactPage {
  const s = isObj(settings['storefront.seller_details']) ? settings['storefront.seller_details'] : {};
  const c = isObj(settings['storefront.contact']) ? settings['storefront.contact'] : {};
  const hours = isObj(c.support_hours) ? c.support_hours : {};
  return {
    phone: toPlainText(str(s.customer_care_phone)),
    email: toPlainText(str(s.customer_care_email)),
    whatsapp: toPlainText(str(c.whatsapp)),
    supportHours: toPlainText(str(hours[locale]) || str(hours.en)),
  };
}

export interface CertificatePage { date: string; textHtml: string; imageUrl: string }

export function certificatePage(settings: Settings): CertificatePage {
  const c = isObj(settings['storefront.compliance_certificate']) ? settings['storefront.compliance_certificate'] : {};
  const image = str(c.image_url);
  return { date: str(c.date), textHtml: sanitizeHtml(str(c.text)), imageUrl: /^https:\/\/\S+$/.test(image) ? image : '' };
}

/** `2026-03-05` as a long date in the language, from the calendar date alone (no time zone shift). */
export function formatCertificateDate(date: string, locale: Locale): string {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(date);
  if (!m) return '';
  const d = new Date(Date.UTC(Number(m[1]), Number(m[2]) - 1, Number(m[3])));
  return new Intl.DateTimeFormat(locale === 'hi' ? 'hi-IN' : 'en-IN', { dateStyle: 'long', timeZone: 'UTC' }).format(d);
}

export const SORT_ORDERS = ['featured', 'relevance', 'newest', 'priceAsc', 'priceDesc', 'rating', 'bestSelling'] as const;
export type SortOrder = (typeof SORT_ORDERS)[number];

/** The factor that each sort order uses (Req 8.7, 16.6); the page text is written from this table. */
export const RANKING_FACTORS: Record<SortOrder, string> = {
  featured: 'storeOrder',
  relevance: 'textMatch',
  newest: 'publicationTime',
  priceAsc: 'priceLowToHigh',
  priceDesc: 'priceHighToLow',
  rating: 'ratingAndCount',
  bestSelling: 'unitsSold30Days',
};

/** Message keys (under `legal.ranking`) of the rows of the Ranking_Disclosure, in display order. */
export function rankingRows(): { order: string; factor: string }[] {
  return SORT_ORDERS.map((o) => ({ order: `legal.ranking.order.${o}`, factor: `legal.ranking.factor.${RANKING_FACTORS[o]}` }));
}

// ---- PDP: return, warranty and delivery summary, and the Mandatory_Declarations (Req 16.3, 16.4) ----

export interface PdpSummaryItem { kind: 'returns' | 'warranty' | 'delivery'; policy: PolicySlug; text: string }

/** First sentence (up to 200 characters) of the plain text of a policy, for the short summary. */
export function policySummary(html: string): string {
  const text = toPlainText(html).replace(/\s+/g, ' ').trim();
  if (!text) return '';
  const end = text.search(/[.!?।](\s|$)/);
  const first = end >= 0 ? text.slice(0, end + 1) : text;
  return first.length > 200 ? `${first.slice(0, 197).trimEnd()}...` : first;
}

/** The three summary lines. A line's text is empty when the store has not written the policy; the link still shows. */
export function pdpSummary(settings: Settings, locale: Locale): PdpSummaryItem[] {
  const rows: [PdpSummaryItem['kind'], PolicySlug][] = [['returns', 'returns'], ['warranty', 'warranties'], ['delivery', 'shipping']];
  return rows.map(([kind, policy]) => ({ kind, policy, text: policySummary(policyContent(settings, policy, locale).html) }));
}

export interface ProductAttribute { key: string; value: unknown }
export interface VariantDeclaration {
  mrp?: number | null; currency_code?: string; net_quantity?: number | null; net_quantity_unit?: string | null;
  best_before_date?: string | null; manufacture_month?: string | null;
}
export interface DeclarationProduct { attributes?: ProductAttribute[]; declarations?: Record<string, VariantDeclaration> }

export type DeclarationKind =
  | 'country_of_origin' | 'manufacturer' | 'importer' | 'generic_name' | 'consumer_care'
  | 'net_quantity' | 'manufacture_month' | 'best_before_date';

export interface DeclarationLine { kind: DeclarationKind; value: string }

const ATTRIBUTE_KINDS: DeclarationKind[] = ['country_of_origin', 'manufacturer', 'importer', 'generic_name', 'consumer_care'];

function attrText(v: unknown): string {
  if (typeof v === 'string') return toPlainText(v).trim();
  if (isObj(v)) return [v.name, v.address].map((x) => toPlainText(str(x)).trim()).filter(Boolean).join(', ');
  if (typeof v === 'number') return String(v);
  return '';
}

const UNIT_LABEL: Record<string, string> = { g: 'g', kg: 'kg', ml: 'ml', l: 'L', mm: 'mm', cm: 'cm', m: 'm', unit: 'units' };

function monthYear(date: string, locale: Locale): string {
  const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(date);
  if (!m) return '';
  return new Intl.DateTimeFormat(locale === 'hi' ? 'hi-IN' : 'en-IN', { month: 'long', year: 'numeric', timeZone: 'UTC' })
    .format(new Date(Date.UTC(Number(m[1]), Number(m[2]) - 1, 1)));
}

/**
 * The Mandatory_Declarations that apply to the product and the chosen variant, in display order. A declaration the store has not
 * set is left out, so the page shows only what is true. The importer shows only when set (an imported product).
 */
export function mandatoryDeclarations(product: DeclarationProduct, variantId: string | null | undefined, locale: Locale = 'en'): DeclarationLine[] {
  const attrs = new Map((product.attributes ?? []).map((a) => [a.key, a.value]));
  const out: DeclarationLine[] = [];
  for (const kind of ATTRIBUTE_KINDS) {
    const value = attrText(attrs.get(kind));
    if (value) out.push({ kind, value });
  }
  const d = variantId ? product.declarations?.[variantId] : undefined;
  if (d) {
    if (typeof d.net_quantity === 'number' && d.net_quantity > 0 && d.net_quantity_unit) {
      out.push({ kind: 'net_quantity', value: `${new Intl.NumberFormat(locale === 'hi' ? 'hi-IN' : 'en-IN').format(d.net_quantity)} ${UNIT_LABEL[d.net_quantity_unit] ?? d.net_quantity_unit}` });
    }
    if (d.manufacture_month) {
      const v = monthYear(d.manufacture_month, locale);
      if (v) out.push({ kind: 'manufacture_month', value: v });
    }
    if (d.best_before_date) {
      const v = formatCertificateDate(d.best_before_date.slice(0, 10), locale);
      if (v) out.push({ kind: 'best_before_date', value: v });
    }
  }
  return out;
}

// ---- Site_Build warnings (Req 17.4) ----

/** Warnings for a missing privacy notice language. An unset notice in both languages warns twice. */
export function privacyNoticeWarnings(settings: Settings): string[] {
  const n = settings['storefront.privacy_notice'];
  const has = (l: Locale) => isObj(n) && Boolean(toPlainText(str(n[l])).trim());
  const out: string[] = [];
  if (!has('en')) out.push('The English privacy notice is missing.');
  if (!has('hi')) out.push('The Hindi privacy notice is missing.');
  return out;
}
