// Path helpers for the shell: English pages sit at their path, Hindi pages under /hi.
import type { Locale } from './i18n';

/** Path without the /hi prefix, always starting with "/" and without a trailing slash (except "/"). */
export function stripLocale(pathname: string): string {
  const p = pathname.replace(/^\/hi(?=\/|$)/, '') || '/';
  return p.length > 1 ? p.replace(/\/+$/, '') : p;
}

export function localizePath(locale: Locale, path: string): string {
  const p = stripLocale(path);
  if (locale === 'en') return p;
  return p === '/' ? '/hi' : `/hi${p}`;
}

export function otherLocale(locale: Locale): Locale {
  return locale === 'en' ? 'hi' : 'en';
}

/** Same page in the other language. The query string is added in the browser (the pages are static). */
export function alternatePath(locale: Locale, pathname: string): string {
  return localizePath(otherLocale(locale), pathname);
}

export type NavKey = 'home' | 'categories' | 'search' | 'cart' | 'account';

/** Which bottom-navigation item marks the current page. Categories is a menu, so it is never "current". */
export function currentNav(pathname: string): NavKey | null {
  const p = stripLocale(pathname);
  if (p === '/') return 'home';
  if (p === '/search' || p.startsWith('/search/')) return 'search';
  if (p === '/cart') return 'cart';
  if (p === '/account' || p.startsWith('/account/')) return 'account';
  return null;
}
