/**
 * Formatting for prices, counts, percentages, dates and durations (Req 5.7, 5.8).
 * Pure, with no Node-only APIs: it runs at build time, in the Worker and in islands.
 * Numbers always use Latin digits (`numberingSystem: 'latn'`); INR uses lakh and crore grouping.
 * Amounts are in major units (rupees, not paise).
 */

export type FormatLocale = 'en' | 'hi';
export const DEFAULT_TIMEZONE = 'Asia/Kolkata';
/** Shown for a missing or non-finite value. */
export const MISSING = '—';

const INTL_LOCALE: Record<FormatLocale, string> = { en: 'en-IN', hi: 'hi-IN' };

const isNum = (n: unknown): n is number => typeof n === 'number' && Number.isFinite(n);

/** Rounds to 2 decimals (the paisa), half away from zero, tolerant of binary float error. */
export function roundToPaisa(n: number): number {
  const s = Math.sign(n);
  return (s * Math.round(Math.abs(n) * 100 + 1e-9)) / 100;
}

const nfCache = new Map<string, Intl.NumberFormat>();
function nf(locale: FormatLocale, opts: Intl.NumberFormatOptions): Intl.NumberFormat {
  const key = locale + JSON.stringify(opts);
  let f = nfCache.get(key);
  if (!f) {
    f = new Intl.NumberFormat(INTL_LOCALE[locale], { ...opts, numberingSystem: 'latn' });
    nfCache.set(key, f);
  }
  return f;
}

/** A whole or decimal number with locale grouping (lakh and crore in en-IN and hi-IN). */
export function formatNumber(n: number | null | undefined, locale: FormatLocale = 'en', maxFractionDigits = 0): string {
  if (!isNum(n)) return MISSING;
  return nf(locale, { maximumFractionDigits: maxFractionDigits }).format(n);
}

/** A count such as reviews or units sold. */
export function formatCount(n: number | null | undefined, locale: FormatLocale = 'en'): string {
  return isNum(n) ? formatNumber(Math.trunc(n), locale) : MISSING;
}

/**
 * Money. INR shows no decimals unless the amount has paise; any other currency uses
 * its own number of decimals (0 for JPY, 3 for KWD, 2 for USD).
 */
export function formatMoney(amount: number | null | undefined, currency = 'INR', locale: FormatLocale = 'en'): string {
  if (!isNum(amount)) return MISSING;
  const code = currency.toUpperCase();
  if (code === 'INR') {
    const v = roundToPaisa(amount);
    const hasPaise = Math.abs(v - Math.round(v)) > 1e-9;
    const d = hasPaise ? 2 : 0;
    return nf(locale, { style: 'currency', currency: 'INR', minimumFractionDigits: d, maximumFractionDigits: d }).format(v);
  }
  return nf(locale, { style: 'currency', currency: code }).format(amount);
}

/** Format a whole-number percentage ("20%"). Input is a percentage (20), not a fraction. */
export function formatPercent(pct: number | null | undefined, locale: FormatLocale = 'en'): string {
  if (!isNum(pct)) return MISSING;
  return nf(locale, { style: 'percent', maximumFractionDigits: 0 }).format(pct / 100);
}

/** The saving as a whole percentage, rounded down (Req 10.2). 0 when there is no saving. */
export function savingPercent(prior: number, price: number): number {
  if (!isNum(prior) || !isNum(price) || prior <= 0 || price >= prior) return 0;
  return Math.floor(((prior - price) / prior) * 100 + 1e-9);
}

/** The saving as an amount, rounded to the paisa. */
export function savingAmount(prior: number, price: number): number {
  if (!isNum(prior) || !isNum(price) || price >= prior) return 0;
  return roundToPaisa(prior - price);
}

export type NetUnit = 'kg' | 'g' | 'mg' | 'L' | 'l' | 'ml' | 'm' | 'cm' | 'mm' | 'unit' | 'piece' | 'pc';
type BaseUnit = 'kg' | 'L' | 'm' | 'unit';

const TO_BASE: Record<string, [BaseUnit, number]> = {
  kg: ['kg', 1], g: ['kg', 0.001], mg: ['kg', 0.000001],
  l: ['L', 1], ml: ['L', 0.001],
  m: ['m', 1], cm: ['m', 0.01], mm: ['m', 0.001],
  unit: ['unit', 1], piece: ['unit', 1], pc: ['unit', 1],
};

/** The unit sale price per 1 kg, 1 L, 1 m or 1 unit, rounded to the paisa (Req 10.5). Null when it cannot be computed. */
export function unitPrice(
  price: number,
  netQuantity: number,
  unit: NetUnit | string,
): { amount: number; per: BaseUnit } | null {
  const conv = TO_BASE[unit.toLowerCase()];
  if (!conv || !isNum(price) || !isNum(netQuantity) || netQuantity <= 0) return null;
  const qtyBase = netQuantity * conv[1];
  return { amount: roundToPaisa(price / qtyBase), per: conv[0] };
}

const PER_LABEL: Record<FormatLocale, Record<BaseUnit, string>> = {
  en: { kg: 'kg', L: 'L', m: 'm', unit: 'piece' },
  hi: { kg: 'किग्रा', L: 'लीटर', m: 'मीटर', unit: 'नग' },
};

/** "₹250 / kg"-style unit price. */
export function formatUnitPrice(
  price: number | null | undefined,
  netQuantity: number | null | undefined,
  unit: NetUnit | string | null | undefined,
  currency = 'INR',
  locale: FormatLocale = 'en',
): string {
  if (!isNum(price) || !isNum(netQuantity) || !unit) return MISSING;
  const u = unitPrice(price, netQuantity, unit);
  if (!u) return MISSING;
  return `${formatMoney(u.amount, currency, locale)} / ${PER_LABEL[locale][u.per]}`;
}

export interface Tier { minQuantity: number; unitPrice: number }
export interface TierDisplay { minQuantity: number; unitPrice: number; savingPerUnit: number }

/** Each tier's saving per unit against the single-unit price (Req 10.6), sorted by minimum quantity. */
export function tierSavings(singlePrice: number, tiers: Tier[]): TierDisplay[] {
  return [...tiers]
    .sort((a, b) => a.minQuantity - b.minQuantity)
    .map((t) => ({ ...t, savingPerUnit: roundToPaisa(singlePrice - t.unitPrice) }));
}

/** "Buy 10+ at ₹90 each, save ₹10 per unit" parts, formatted. */
export function formatTier(t: TierDisplay, currency = 'INR', locale: FormatLocale = 'en') {
  return {
    quantity: `${formatCount(t.minQuantity, locale)}+`,
    unitPrice: formatMoney(t.unitPrice, currency, locale),
    saving: formatMoney(t.savingPerUnit, currency, locale),
  };
}

type DateInput = Date | string | number;
const toDate = (d: DateInput | null | undefined): Date | null => {
  if (d === null || d === undefined) return null;
  const v = d instanceof Date ? d : new Date(d);
  return Number.isNaN(v.getTime()) ? null : v;
};

const dfCache = new Map<string, Intl.DateTimeFormat>();
function df(locale: FormatLocale, tz: string, opts: Intl.DateTimeFormatOptions): Intl.DateTimeFormat {
  const key = locale + tz + JSON.stringify(opts);
  let f = dfCache.get(key);
  if (!f) {
    f = new Intl.DateTimeFormat(INTL_LOCALE[locale], { ...opts, timeZone: tz, numberingSystem: 'latn' });
    dfCache.set(key, f);
  }
  return f;
}

const yearOf = (d: Date, tz: string) => Number(df('en', tz, { year: 'numeric' }).format(d));

/** Weekday, day and short month in the store timezone; the year only outside the current year (Req 5.8). */
export function formatDate(
  date: DateInput | null | undefined,
  locale: FormatLocale = 'en',
  opts: { timeZone?: string; now?: DateInput } = {},
): string {
  const d = toDate(date);
  if (!d) return MISSING;
  const tz = opts.timeZone ?? DEFAULT_TIMEZONE;
  const now = toDate(opts.now) ?? new Date();
  const withYear = yearOf(d, tz) !== yearOf(now, tz);
  return df(locale, tz, {
    weekday: 'short', day: 'numeric', month: 'short', ...(withYear ? { year: 'numeric' } : {}),
  }).format(d);
}

/** A delivery date range such as "Tue 12 – Thu 14 Nov"; one date when both ends fall on the same day. */
export function formatDateRange(
  from: DateInput | null | undefined,
  to: DateInput | null | undefined,
  locale: FormatLocale = 'en',
  opts: { timeZone?: string; now?: DateInput } = {},
): string {
  const a = toDate(from);
  const b = toDate(to);
  if (!a || !b) return MISSING;
  const tz = opts.timeZone ?? DEFAULT_TIMEZONE;
  const first = formatDate(a, locale, opts);
  const last = formatDate(b, locale, opts);
  if (first === last) return first;
  const ymd = (d: Date) => df('en', tz, { year: 'numeric', month: 'numeric', day: 'numeric' }).format(d);
  if (ymd(a) === ymd(b)) return first;
  const sameMonthYear = df('en', tz, { year: 'numeric', month: 'numeric' }).format(a) ===
    df('en', tz, { year: 'numeric', month: 'numeric' }).format(b);
  if (sameMonthYear) {
    // Drop the month (and year) from the first date: "Tue 12 – Thu 14 Nov".
    const short = df(locale, tz, { weekday: 'short', day: 'numeric' }).format(a);
    return `${short} – ${last}`;
  }
  return `${first} – ${last}`;
}

const DURATION_LABELS: Record<FormatLocale, { d: string; h: string; m: string; lessThanMinute: string }> = {
  en: { d: 'day', h: 'hr', m: 'min', lessThanMinute: 'less than a minute' },
  hi: { d: 'दिन', h: 'घंटे', m: 'मिनट', lessThanMinute: 'एक मिनट से कम' },
};

/** "3 hr 20 min" for the "order within" countdown. Shows at most two units; negative values count as zero. */
export function formatDuration(ms: number | null | undefined, locale: FormatLocale = 'en'): string {
  if (!isNum(ms)) return MISSING;
  const L = DURATION_LABELS[locale];
  const totalMin = Math.floor(Math.max(0, ms) / 60000);
  if (totalMin < 1) return L.lessThanMinute;
  const days = Math.floor(totalMin / 1440);
  const hours = Math.floor((totalMin % 1440) / 60);
  const mins = totalMin % 60;
  const parts: string[] = [];
  if (days) parts.push(`${formatNumber(days, locale)} ${L.d}`);
  if (hours) parts.push(`${formatNumber(hours, locale)} ${L.h}`);
  if (mins && !days) parts.push(`${formatNumber(mins, locale)} ${L.m}`);
  return parts.slice(0, 2).join(' ');
}
