// Build-time helper: collects the price block's interface text from the dictionaries (keys under `price.*`).
import { t, type Locale } from '../lib/i18n';

const KEYS = [
  'onRequest', 'onRequestHint', 'yourPrice', 'srCurrent', 'srPrior', 'inclTax', 'saving', 'savingAmountOnly',
  'explainControl', 'priorExplain', 'mrp', 'unitPrice', 'tiersCaption', 'tierQuantity', 'tierPrice', 'tierSaving',
  'noSaving', 'cartConfirms',
] as const;

export type PriceBlockLabels = Record<(typeof KEYS)[number], string>;

export function priceBlockLabels(locale: Locale): PriceBlockLabels {
  return Object.fromEntries(KEYS.map((k) => [k, t(locale, `price.${k}`)])) as PriceBlockLabels;
}

/** Component_Switch: a component shows while its switch is not off. `price_block` is this component's key. */
export function switchIsOn(switches: Record<string, boolean> | null | undefined, key = 'price_block'): boolean {
  return switches?.[key] !== false;
}
