/**
 * Home page Sections (Req 6.4, 6.5). Pure: the build reads `storefront.sections` from the public Store_Settings
 * (or uses the default list), and product rails resolve from the catalog export. A rail with fewer than 2
 * products is left out.
 */
import type { Locale } from './i18n';

type Obj = Record<string, unknown>;
const isObj = (x: unknown): x is Obj => !!x && typeof x === 'object' && !Array.isArray(x);
const str = (x: unknown): string => (typeof x === 'string' ? x : '');

export const SECTION_TYPES = [
  'hero_banner', 'category_grid', 'collection_grid', 'product_rail', 'review_highlights',
  'trust_strip', 'brand_story', 'offer_banner', 'faq', 'newsletter',
] as const;
export type SectionType = (typeof SECTION_TYPES)[number];
export const isSectionType = (x: unknown): x is SectionType => typeof x === 'string' && (SECTION_TYPES as readonly string[]).includes(x);

export const MIN_RAIL_PRODUCTS = 2;
export const MAX_RAIL_PRODUCTS = 12;
export const MAX_CATEGORY_TILES = 8;
export const RECENT_MAX = 10;

export interface Section {
  id: string;
  type: SectionType;
  settings: Obj;
}

/** Default Sections, used when the store has saved none. */
export const DEFAULT_SECTIONS: Section[] = [
  { id: 'hero', type: 'hero_banner', settings: {} },
  { id: 'categories', type: 'category_grid', settings: {} },
  { id: 'best', type: 'product_rail', settings: { source: 'best_sellers', title: 'bestSellers' } },
  { id: 'offer', type: 'offer_banner', settings: {} },
  { id: 'reviews', type: 'review_highlights', settings: {} },
  { id: 'trust', type: 'trust_strip', settings: {} },
  { id: 'new', type: 'product_rail', settings: { source: 'newest', title: 'newArrivals' } },
  { id: 'story', type: 'brand_story', settings: {} },
  { id: 'faq', type: 'faq', settings: {} },
  { id: 'newsletter', type: 'newsletter', settings: {} },
];

/** Reads the saved Sections: unknown types and hidden entries are dropped; a missing or empty value gives the defaults. */
export function normalizeSections(raw: unknown): Section[] {
  const list = isObj(raw) && Array.isArray(raw.sections) ? raw.sections : raw;
  if (!Array.isArray(list)) return DEFAULT_SECTIONS;
  const out: Section[] = [];
  list.forEach((s, i) => {
    if (!isObj(s) || !isSectionType(s.type) || s.hidden === true || s.enabled === false) return;
    out.push({ id: str(s.id) || `${s.type}-${i}`, type: s.type, settings: isObj(s.settings) ? s.settings : {} });
  });
  return out.length > 0 ? out : DEFAULT_SECTIONS;
}

/** A setting written as text or as `{ en, hi }`. */
export function localized(v: unknown, locale: Locale): string {
  if (typeof v === 'string') return v;
  if (isObj(v)) return str(v[locale]) || str(v.en);
  return '';
}

/** Only site-relative paths and https links are used as hrefs. */
export function safeHref(v: unknown): string | null {
  const s = str(v).trim();
  if (/^\/(?!\/)/.test(s) || /^https:\/\//i.test(s)) return s;
  return null;
}

export type RailSource = 'collection' | 'category' | 'newest' | 'best_sellers' | 'picked';


/** Products of a rail, in display order, at most 12. `bestSellerIds` comes from the 30-day best-seller read. */
export function resolveRail(
  settings: Obj, products: Obj[], bestSellerIds: readonly string[] = [],
): Obj[] {
  const source = str(settings.source) as RailSource;
  const limit = Math.min(MAX_RAIL_PRODUCTS, Math.max(1, Number(settings.limit) || MAX_RAIL_PRODUCTS));
  const inCollection = (p: Obj, key: string) =>
    (Array.isArray(p.collection_ids) ? p.collection_ids : []).map(str).includes(key) || str(p.collection_id) === key ||
    (Array.isArray(p.collections) ? p.collections : []).some((c) => isObj(c) && (str(c.id) === key || str(c.handle) === key));
  const inCategory = (p: Obj, key: string) =>
    (Array.isArray(p.category_ids) ? p.category_ids : []).map(str).includes(key) ||
    (Array.isArray(p.categories) ? p.categories : []).some((c) => isObj(c) && (str(c.id) === key || str(c.handle) === key));
  let picked: Obj[] = [];
  switch (source) {
    case 'collection': picked = products.filter((p) => inCollection(p, str(settings.collection))); break;
    case 'category': picked = products.filter((p) => inCategory(p, str(settings.category))); break;
    case 'newest':
      picked = [...products].sort((a, b) => (Date.parse(str(b.created_at)) || 0) - (Date.parse(str(a.created_at)) || 0));
      break;
    case 'best_sellers': {
      const order = new Map(bestSellerIds.map((id, i) => [id, i]));
      picked = products.filter((p) => order.has(str(p.id))).sort((a, b) => (order.get(str(a.id)) ?? 0) - (order.get(str(b.id)) ?? 0));
      break;
    }
    case 'picked': {
      const want = Array.isArray(settings.products) ? settings.products.map(str) : [];
      const byKey = new Map<string, Obj>();
      for (const p of products) { byKey.set(str(p.id), p); byKey.set(str(p.handle), p); }
      picked = want.map((k) => byKey.get(k)).filter((p): p is Obj => !!p);
      break;
    }
    default: picked = [];
  }
  return picked.slice(0, limit);
}

/** A rail with fewer than 2 products is left out (Req 6.5). */
export const railShows = (n: number): boolean => n >= MIN_RAIL_PRODUCTS;

export interface Tile { href: string; name: string; imageUrl: string | null }

/** Top-level categories as tiles, in the store's rank order, at most 8. */
export function categoryTiles(categories: Obj[], locale: Locale, prefix: (p: string) => string): Tile[] {
  return categories
    .filter((c) => !c.parent_category_id && str(c.handle) && str(c.name))
    .sort((a, b) => (Number(a.rank) || 0) - (Number(b.rank) || 0))
    .slice(0, MAX_CATEGORY_TILES)
    .map((c) => ({
      href: prefix(`/shop/${encodeURIComponent(str(c.handle))}`),
      name: (isObj(c.metadata) && locale === 'hi' && str(c.metadata.name_hi)) || str(c.name),
      imageUrl: isObj(c.metadata) ? str(c.metadata.image_url) || null : null,
    }));
}

export function collectionTiles(collections: Obj[], locale: Locale, prefix: (p: string) => string): Tile[] {
  return collections
    .filter((c) => str(c.handle) && str(c.title))
    .map((c) => ({
      href: prefix(`/collection/${encodeURIComponent(str(c.handle))}`),
      name: (isObj(c.metadata) && locale === 'hi' && str(c.metadata.title_hi)) || str(c.title),
      imageUrl: isObj(c.metadata) ? str(c.metadata.image_url) || null : null,
    }));
}

export interface OfferView { id: string; text: string; code: string | null; endsAt: string | null }

/** Offer banner: the first Promotion that runs now and is not the first-order offer. None gives null. */
export function activeOffer(offers: unknown, now: number, locale: Locale): OfferView | null {
  const list = isObj(offers) && Array.isArray(offers.offers) ? offers.offers : [];
  for (const o of list) {
    if (!isObj(o) || o.first_order_offer === true) continue;
    const starts = Date.parse(str(o.starts_at));
    const ends = Date.parse(str(o.ends_at));
    if (Number.isFinite(starts) && starts > now) continue;
    if (Number.isFinite(ends) && ends <= now) continue;
    const v = isObj(o.value) ? o.value : {};
    const amount = Number(v.value);
    if (!Number.isFinite(amount) || amount <= 0) continue;
    const cur = str(v.currency_code).toUpperCase() || 'INR';
    const nf = new Intl.NumberFormat(locale === 'hi' ? 'hi-IN' : 'en-IN');
    const off = str(v.type) === 'percentage' ? `${nf.format(amount)}%` : `${cur === 'INR' ? '₹' : `${cur} `}${nf.format(amount)}`;
    const text = locale === 'hi' ? `${off} की छूट` : `${off} off`;
    return { id: str(o.id), text, code: str(o.code) || null, endsAt: Number.isFinite(ends) ? str(o.ends_at) : null };
  }
  return null;
}

export interface TrustItem { text: string }

/** Trust_Strip statements: confirmed ones only, from section settings or the delivery rules. */
export function trustItems(
  settings: Obj, rules: unknown, locale: Locale,
  label: (key: 'cod' | 'free', amount: string) => string,
  money: (n: number) => string,
): TrustItem[] {
  if (Array.isArray(settings.items)) {
    return settings.items.map((i) => ({ text: localized(i, locale) })).filter((i) => i.text);
  }
  const r = isObj(rules) ? rules : {};
  const out: TrustItem[] = [];
  const cod = isObj(r.cod) ? Number(r.cod.max_order_amount) : NaN;
  if (Number.isFinite(cod) && cod > 0) out.push({ text: label('cod', money(cod)) });
  const free = Number(r.free_delivery_threshold);
  if (Number.isFinite(free) && free > 0) out.push({ text: label('free', money(free)) });
  return out;
}

export interface RecentEntry { id: string; handle: string }

/** Reads `sf.recent`: strings (ids or handles) or objects with id and handle; newest first, at most 10. */
export function parseRecent(raw: unknown): string[] {
  const list = Array.isArray(raw) ? raw : [];
  const out: string[] = [];
  for (const e of list) {
    const k = typeof e === 'string' ? e : isObj(e) ? str(e.id) || str(e.handle) : '';
    if (k && !out.includes(k)) out.push(k);
    if (out.length >= RECENT_MAX) break;
  }
  return out;
}
