/**
 * PDP_Blocks of the Business_Presets (Req 6.6 to 6.8). Pure: each block turns the product's data into a view, or into null
 * when the product has none, so the page shows a block only with data and in the order of the store's list.
 * Attributes come from the preset files' attribute definitions (block per attribute), so no block key is hard-coded twice.
 */
import { PRESETS } from './presets';
import type { PdpModel, PdpVariantModel } from './pdp';

export type BlockRow = { key: string; value: string; boolean?: boolean };
export type BlockView =
  | { kind: 'rows'; rows: BlockRow[] }
  | { kind: 'tiers'; tiers: { minQuantity: number; amount: number }[]; rows: BlockRow[] }
  | { kind: 'compare'; head: string[]; rows: { key: string; values: string[] }[] }
  | { kind: 'quote' };

/** Blocks that the page shows with its own components, or that other parts of the page already cover. */
export const DEFAULT_BLOCKS: readonly string[] = ['description', 'specifications'];
const OWN_RENDER = new Set(['description', 'specifications', 'unit_price']);
/** Attributes shown by the declarations component or by the page itself. */
const NEVER_IN_SPECS = new Set(['key_highlights', 'return_days', 'country_of_origin', 'manufacturer', 'importer', 'generic_name', 'consumer_care', 'price_on_request']);
const COMPARE_BLOCK = 'key_specifications';
export const MAX_COMPARED = 2;

type AttrDef = { key: string; unit: string | null; block: string };
/** Block key to its attributes, in the order of the preset files. */
const BLOCK_ATTRS: Record<string, AttrDef[]> = {};
for (const preset of Object.values(PRESETS)) {
  for (const a of preset.attributes as AttrDef[]) {
    if (a.block === 'declarations') continue;
    const list = (BLOCK_ATTRS[a.block] ??= []);
    if (!list.some((x) => x.key === a.key)) list.push({ key: a.key, unit: a.unit, block: a.block });
  }
}

export const attributesOfBlock = (block: string): string[] => (BLOCK_ATTRS[block] ?? []).map((a) => a.key);

const text = (v: unknown): string => (typeof v === 'string' || typeof v === 'number' ? String(v).trim() : '');
const isTrue = (v: unknown): boolean => v === true || (typeof v === 'string' && v.trim().toLowerCase() === 'true');
const isBool = (v: unknown): boolean => typeof v === 'boolean' || v === 'true' || v === 'false';
const attrOf = (m: PdpModel, key: string): unknown => m.attributes.find((a) => a.key === key)?.value;

/** A product shows price on request when its attribute says so, or when no variant has a price. */
export function isPriceOnRequest(m: PdpModel): boolean {
  if (isTrue(attrOf(m, 'price_on_request'))) return true;
  return m.variants.length > 0 && m.variants.every((v) => v.price === null);
}

/** The single unit of a number attribute, as "kg"; empty when the unit is not single. */
const singleUnit = (u: string | null): string => (u && !u.includes('|') ? u : '');

function rowsOf(m: PdpModel, block: string, formatDate: (iso: string) => string): BlockRow[] {
  const rows: BlockRow[] = [];
  for (const def of BLOCK_ATTRS[block] ?? []) {
    const raw = attrOf(m, def.key);
    if (raw === undefined || raw === null) continue;
    if (isBool(raw)) { rows.push({ key: def.key, value: isTrue(raw) ? 'true' : 'false', boolean: true }); continue; }
    let value = text(raw);
    if (!value) continue;
    if (/^\d{4}-\d{2}-\d{2}/.test(value)) value = formatDate(value);
    const unit = singleUnit(def.unit);
    rows.push({ key: def.key, value: unit && /^\d/.test(value) ? `${value} ${unit}` : value });
  }
  return rows;
}

/** The variant that the static page shows: the only one, or the first with a price. */
const firstVariant = (m: PdpModel): PdpVariantModel | null => m.variants.find((v) => v.price !== null) ?? m.variants[0] ?? null;

export interface BlockContext {
  model: PdpModel;
  /** Products of the build by handle, for the comparison block. */
  byHandle: Map<string, PdpModel>;
  formatDate: (iso: string) => string;
  priceOnRequest: boolean;
}

/** The comparison table: this product and up to 2 paired products, on the key specification attributes (Req 6.7). */
function compareView(ctx: BlockContext): BlockView | null {
  const others = (ctx.model.pairings.comparison ?? []).map((h) => ctx.byHandle.get(h)).filter((p): p is PdpModel => !!p && p.id !== ctx.model.id).slice(0, MAX_COMPARED);
  if (others.length === 0) return null;
  const products = [ctx.model, ...others];
  const rows = attributesOfBlock(COMPARE_BLOCK)
    .map((key) => ({ key, values: products.map((p) => text(attrOf(p, key))) }))
    .filter((r) => r.values.some((v) => v !== ''));
  if (rows.length === 0) return null;
  return { kind: 'compare', head: products.map((p) => p.title), rows };
}

/** The view of one block, or null when the product has no data for it. */
export function blockView(block: string, ctx: BlockContext): BlockView | null {
  if (OWN_RENDER.has(block)) return null;
  const m = ctx.model;
  if (block === 'comparison') return compareView(ctx);
  if (block === 'quotation_request') return ctx.priceOnRequest ? { kind: 'quote' } : null;
  if (block === 'quantity_tiers') {
    const v = firstVariant(m);
    const tiers = v?.tiers ?? [];
    const rows = rowsOf(m, block, ctx.formatDate);
    return tiers.length > 0 || rows.length > 0 ? { kind: 'tiers', tiers, rows } : null;
  }
  if (block === 'net_quantity') {
    const rows = rowsOf(m, block, ctx.formatDate);
    const v = firstVariant(m);
    if (rows.length === 0 && v?.netQuantity != null) rows.push({ key: 'net_quantity', value: `${v.netQuantity}${v.netQuantityUnit ? ` ${v.netQuantityUnit}` : ''}` });
    return rows.length > 0 ? { kind: 'rows', rows } : null;
  }
  const rows = rowsOf(m, block, ctx.formatDate);
  return rows.length > 0 ? { kind: 'rows', rows } : null;
}

/** Attributes that a listed block shows, so the specifications block does not repeat them. */
export function claimedAttributes(blocks: readonly string[]): Set<string> {
  const claimed = new Set<string>();
  for (const b of blocks) if (b !== 'specifications') attributesOfBlock(b).forEach((k) => claimed.add(k));
  NEVER_IN_SPECS.forEach((k) => claimed.add(k));
  return claimed;
}

/** The blocks to show, in the store's order; the default blocks when the store lists none. */
export const blocksToShow = (blocks: readonly string[]): string[] => (blocks.length > 0 ? [...blocks] : [...DEFAULT_BLOCKS]);
