// Data that the header, bottom navigation and footer show on every page.
// The build data step (scripts/build-data, task 3.2) writes src/data/shell.json, which `loadShellData` reads.
// Setting keys: storefront.seller_details, storefront.grievance_officer (migration 20261110008000), and the
// Client_Branding name and logo from the public Store_Settings.
import type { Locale } from './i18n';

export type Localized = Record<Locale, string>;

export interface ShellCategory {
  slug: string;
  name: Localized;
}

export interface SellerDetails {
  legalName: string;
  registeredAddress: string;
  gstin: string;
  customerCarePhone: string;
  customerCareEmail: string;
}

export interface GrievanceOfficer {
  name: string;
  designation: string;
  phone: string;
  email: string;
}

export interface ShellData {
  brand: { name: string; logoUrl?: string };
  /** Up to 8 top-level categories, in the order the store sets. */
  categories: ShellCategory[];
  seller: SellerDetails;
  grievanceOfficer: GrievanceOfficer;
}

export const MAX_MENU_CATEGORIES = 8;

export const FIXTURE_SHELL_DATA: ShellData = {
  brand: { name: 'Plusmark' },
  categories: [],
  seller: {
    legalName: '',
    registeredAddress: '',
    gstin: '',
    customerCarePhone: '',
    customerCareEmail: '',
  },
  grievanceOfficer: {
    name: '',
    designation: '',
    phone: '',
    email: '',
  },
};

const text = (v: unknown): string => (typeof v === 'string' ? v : '');

/** Keeps at most 8 categories and drops entries without a slug or an English name. */
export function normalizeShellData(raw: Partial<ShellData> | null | undefined): ShellData {
  const base = FIXTURE_SHELL_DATA;
  if (!raw) return base;
  const categories = (raw.categories ?? base.categories)
    .filter((c) => c && text(c.slug) && text(c.name?.en))
    .slice(0, MAX_MENU_CATEGORIES)
    .map((c) => ({ slug: c.slug, name: { en: c.name.en, hi: text(c.name.hi) || c.name.en } }));
  return {
    brand: { name: text(raw.brand?.name) || base.brand.name, logoUrl: raw.brand?.logoUrl || undefined },
    categories,
    seller: { ...base.seller, ...raw.seller },
    grievanceOfficer: { ...base.grievanceOfficer, ...raw.grievanceOfficer },
  };
}

// src/data/shell.json is written by scripts/build-data (live or fixture mode); without it the fixture applies.
const generated = import.meta.glob<Partial<ShellData>>('../data/shell.json', { eager: true, import: 'default' });

/** Build-time read of the shell data that the build data step wrote. */
export function loadShellData(): ShellData {
  const raw = Object.values(generated)[0];
  return normalizeShellData(raw && Object.keys(raw).length ? raw : FIXTURE_SHELL_DATA);
}
