// Small island: loads the count after the first render and follows the Cart in every tab.
import { useEffect, useState } from 'preact/hooks';
import { watchCartCount } from '../../lib/cart-count';

interface Props {
  /** Translated, with a {count} placeholder, for example "{count} items in your cart". */
  label: string;
}

export default function CartCount({ label }: Props) {
  const [count, setCount] = useState(0);
  useEffect(() => watchCartCount(setCount), []);
  if (count < 1) return null;
  return (
    <>
      <span class="pm-cart-count" aria-hidden="true">
        {count > 99 ? '99+' : count}
      </span>
      <span class="pm-visually-hidden">{label.replace('{count}', String(count))}</span>
    </>
  );
}
