// The fixed inline `<head>` script (design KD-9, KD-14; Req 3.8, 19.5, 19.6, 21.1).
// Its text is the same on every page, so one CSP hash covers it. It reads the Consent_Choice (`sf.consent`)
// and the analytics session ID (`sf.sid`), assigns each running Experiment, and sets `data-pm-exp` on <html>
// before the first paint, then starts the Save-Data observer. Sessions without analytics consent, or without
// a session ID yet, get the control and no attribute entry for the treatment.
import { SAVE_DATA_SCRIPT } from './images';

export interface RunningExperiment {
  id: string;
  /** Share of sessions in the treatment, from 0 to 1. */
  share: number;
  /** Persuasion_Component key (ationale.json) that the Experiment changes; absent in older data. */
  component?: string;
}

/** Id of the `application/json` block that holds the running Experiments. */
export const EXPERIMENTS_BLOCK_ID = 'pm-experiments';

/** FNV-1a, 32 bit, over UTF-16 code units; the same function as in the inline script. */
export function fnv1a32(s: string): number {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 16777619) >>> 0;
  }
  return h >>> 0;
}

/** Variant of a session for an Experiment: treatment when `fnv1a32(sid:id) / 2^32` is below the share. */
export function assignVariant(sessionId: string, exp: RunningExperiment): 't' | 'c' {
  return fnv1a32(`${sessionId}:${exp.id}`) / 4294967296 < exp.share ? 't' : 'c';
}

/** Keeps well-formed Experiments only; ids are limited to characters that are safe in an attribute token. */
export function normalizeExperiments(raw: unknown): RunningExperiment[] {
  if (!Array.isArray(raw)) return [];
  return raw
    .filter((e): e is RunningExperiment => !!e && typeof e.id === 'string' && /^[A-Za-z0-9_-]{1,64}$/.test(e.id) && typeof e.share === 'number' && e.share >= 0 && e.share <= 1)
    .map((e) => {
      const out: RunningExperiment = { id: e.id, share: e.share };
      if (typeof e.component === 'string' && /^[a-z][a-z0-9_]{0,62}$/.test(e.component)) out.component = e.component;
      return out;
    });
}

/** JSON for the `application/json` block; `<` is escaped so the block cannot close its own tag. */
export function experimentsJson(list: RunningExperiment[]): string {
  return JSON.stringify(normalizeExperiments(list)).replace(/</g, '\\u003c');
}

const EXPERIMENT_SCRIPT = `(function(){try{var d=document.documentElement;var b=document.getElementById('${EXPERIMENTS_BLOCK_ID}');if(!b)return;var l=JSON.parse(b.textContent||'[]');if(!l.length)return;var c=JSON.parse(localStorage.getItem('sf.consent')||'null');var p=c&&(c.purposes||c);if(!p||p.analytics!==true)return;var s=localStorage.getItem('sf.sid');if(!s)return;try{var o=JSON.parse(s);if(o&&typeof o==='object')s=o.id}catch(e){}if(typeof s!=='string'||!s)return;var a=[],x=[];for(var i=0;i<l.length;i++){var h=2166136261,k=s+':'+l[i].id;for(var j=0;j<k.length;j++){h^=k.charCodeAt(j);h=Math.imul(h,16777619)>>>0}var v=h/4294967296<l[i].share?'t':'c';a.push(l[i].id+'='+v);if(v==='t'&&l[i].component)x.push(l[i].component)}d.setAttribute('data-pm-exp',a.join(' '));if(x.length)d.setAttribute('data-pm-xt',x.join(' '))}catch(e){}})();`;

/** The whole inline script of the page head. */
export const HEAD_SCRIPT = `${EXPERIMENT_SCRIPT}${SAVE_DATA_SCRIPT}`;
