/**
 * Evidence rules of the social proof and trust components (Req 11.2-11.5, 11.12, 11.21, 2.4).
 * Each function takes typed evidence from the Backend and returns null when the evidence is missing or incomplete,
 * so a component renders nothing without it. No count, rating or claim comes from a literal.
 */

export const POPULARITY_BANDS = [5, 10, 25, 50, 100, 250, 500, 1000] as const;
export const MIN_HIGHLIGHT_CHARS = 100;

const isObj = (x: unknown): x is Record<string, unknown> => !!x && typeof x === 'object' && !Array.isArray(x);
const isNum = (x: unknown): x is number => typeof x === 'number' && Number.isFinite(x);

// --- Review_Summary (Req 11.2) -----------------------------------------------------------------------------------------

export interface ReviewSummaryEvidence { count: number; average: number }

/** Reads `store_list_reviews`'s `summary`. Null below 1 published review or for an invalid rating. */
export function parseReviewSummary(raw: unknown): ReviewSummaryEvidence | null {
  const s = isObj(raw) && isObj(raw.summary) ? raw.summary : raw;
  if (!isObj(s) || !isNum(s.count) || !isNum(s.average)) return null;
  const count = Math.trunc(s.count);
  if (count < 1 || s.average < 1 || s.average > 5) return null;
  return { count, average: s.average };
}

/** The average to 1 decimal place, with Latin digits. */
export const formatRating = (average: number): string => (Math.round(average * 10) / 10).toFixed(1);

// --- Review_Highlights (Req 11.3) --------------------------------------------------------------------------------------

export interface ReviewEvidence { id: string; rating: number; title: string | null; body: string; author: string; createdAt: string }

export function parseReviews(raw: unknown): ReviewEvidence[] {
  const rows = isObj(raw) && Array.isArray(raw.reviews) ? raw.reviews : [];
  const out: ReviewEvidence[] = [];
  for (const r of rows) {
    if (!isObj(r) || typeof r.id !== 'string' || !isNum(r.rating) || typeof r.body !== 'string' || typeof r.created_at !== 'string') continue;
    out.push({
      id: r.id,
      rating: r.rating,
      title: typeof r.title === 'string' ? r.title : null,
      body: r.body,
      author: typeof r.author === 'string' ? r.author : '',
      createdAt: r.created_at,
    });
  }
  return out;
}

/**
 * The newest review rated 4 or 5 and the newest rated 1 to 3, each with at least 100 characters of text.
 * Null unless both exist.
 */
export function pickHighlights(reviews: readonly ReviewEvidence[]): { positive: ReviewEvidence; critical: ReviewEvidence } | null {
  const long = reviews.filter((r) => r.body.trim().length >= MIN_HIGHLIGHT_CHARS);
  const newest = (xs: ReviewEvidence[]) => xs.reduce<ReviewEvidence | null>((a, r) => (!a || Date.parse(r.createdAt) > Date.parse(a.createdAt) ? r : a), null);
  const positive = newest(long.filter((r) => r.rating >= 4 && r.rating <= 5));
  const critical = newest(long.filter((r) => r.rating >= 1 && r.rating < 4));
  return positive && critical ? { positive, critical } : null;
}

// --- Popularity_Notice (Req 11.4) --------------------------------------------------------------------------------------

/** The largest band at or below `count`; null below 5 or for an invalid count. */
export function popularityBand(count: number | null | undefined): number | null {
  if (!isNum(count) || count < POPULARITY_BANDS[0]) return null;
  let band: number = POPULARITY_BANDS[0];
  for (const b of POPULARITY_BANDS) if (count >= b) band = b;
  return band;
}

/**
 * Live_Data carries only the band (`popularity_band`). A value that is not one of the bands is not evidence, so the
 * notice never states a raw count.
 */
export function parsePopularityBand(v: unknown): number | null {
  return isNum(v) && (POPULARITY_BANDS as readonly number[]).includes(v) ? v : null;
}

// --- Low_Stock_Notice (Req 11.5) ---------------------------------------------------------------------------------------

/**
 * The exact quantity while it is above 0 and at or below the threshold and backorders are not allowed.
 * `threshold` null means the Backend already limited the quantity to the threshold (it sends none above it).
 */
export function lowStockQuantity(q: unknown, allowBackorder: unknown, threshold: number | null = null): number | null {
  if (!isNum(q) || allowBackorder !== false) return null;
  if (q <= 0 || !Number.isInteger(q)) return null;
  return threshold !== null && q > threshold ? null : q;
}

export interface LiveVariantEvidence {
  popularityBand: number | null;
  quantity: number | null;
}

/** Reads the Popularity_Notice and Low_Stock_Notice evidence for one variant from a Live_Data body. */
export function pickLiveSocial(body: unknown, productId: string, variantId: string): LiveVariantEvidence | null {
  if (!isObj(body) || !Array.isArray(body.products)) return null;
  const p = body.products.find((x) => isObj(x) && x.id === productId);
  if (!isObj(p) || p.available === false || !Array.isArray(p.variants)) return null;
  const v = p.variants.find((x) => isObj(x) && x.id === variantId);
  if (!isObj(v)) return null;
  return { popularityBand: parsePopularityBand(p.popularity_band), quantity: lowStockQuantity(v.sellable_quantity, v.allow_backorder) };
}

// --- Trust_Strip (Req 11.12) -------------------------------------------------------------------------------------------

export type TrustKey = 'securePayment' | 'cod' | 'returns' | 'gstInvoice' | 'origin';

export interface TrustEvidence {
  /** Store_Settings confirm an online payment method and the Backend verifies payments. */
  securePayment?: boolean;
  /** The postal check of the shopper's code confirms Cash_On_Delivery. */
  cod?: boolean;
  /** The product's return window in days; above 0 only. */
  returnDays?: number | null;
  /** The Backend issues GST invoices. */
  gstInvoice?: boolean;
  /** The product's declared country of origin. */
  origin?: string | null;
}

export interface TrustItem { key: TrustKey; value?: string }

/** Only the statements that the evidence confirms, in a fixed order. */
export function trustItems(e: TrustEvidence | null | undefined): TrustItem[] {
  if (!e) return [];
  const out: TrustItem[] = [];
  if (e.securePayment === true) out.push({ key: 'securePayment' });
  if (e.cod === true) out.push({ key: 'cod' });
  if (isNum(e.returnDays) && e.returnDays > 0 && Number.isInteger(e.returnDays)) out.push({ key: 'returns', value: String(e.returnDays) });
  if (e.gstInvoice === true) out.push({ key: 'gstInvoice' });
  if (typeof e.origin === 'string' && e.origin.trim()) out.push({ key: 'origin', value: e.origin.trim() });
  return out;
}
