/**
 * Evidence rules of the basket and journey components (Req 11.10, 11.11, 11.13-11.15, 11.19, 11.20, 9.7).
 * Pure functions: each returns null (or an empty list) when the data does not support the component, so nothing is invented.
 */
import { getJson, removeItem, setJson } from './storage';
import { interruptionDue } from './honesty';

const isNum = (x: unknown): x is number => typeof x === 'number' && Number.isFinite(x);

export const PERCENT_MAX = 100;

export interface FreeDeliveryProgress {
  /** Amount still needed; 0 once reached. */
  remaining: number;
  /** 0 to 100. */
  percent: number;
  reached: boolean;
}

/** Free_Delivery_Progress: needs a positive threshold and a subtotal (Req 11.10). */
export function freeDeliveryProgress(subtotal: unknown, threshold: unknown): FreeDeliveryProgress | null {
  if (!isNum(subtotal) || !isNum(threshold) || threshold <= 0 || subtotal < 0) return null;
  const reached = subtotal >= threshold;
  return { remaining: reached ? 0 : threshold - subtotal, percent: Math.min(100, Math.floor((subtotal / threshold) * 100)), reached };
}

export interface SavingsLine {
  quantity: number;
  price: number;
  /** The line's Prior_Price per unit, only when it is a valid reduction evidence. */
  priorPrice?: number | null;
}

/** Savings_Summary: each line's saving against its Prior_Price plus Promotion discounts; null unless above 0 (Req 11.11). */
export function savingsTotal(lines: readonly SavingsLine[], promotionDiscount: unknown = 0): number | null {
  let total = isNum(promotionDiscount) && promotionDiscount > 0 ? promotionDiscount : 0;
  for (const l of lines) {
    if (!isNum(l.quantity) || l.quantity <= 0 || !isNum(l.price) || !isNum(l.priorPrice) || l.priorPrice <= l.price) continue;
    total += (l.priorPrice - l.price) * l.quantity;
  }
  return total > 0 ? Math.round(total * 100) / 100 : null;
}

export interface JourneyProduct {
  id: string;
  title: string;
  price: number;
  available: boolean;
  url?: string;
}

/** Goes_Well_With: the paired products that are available, without the product itself and without repeats (Req 11.13). */
export function pairedProducts(self: string, paired: readonly JourneyProduct[]): JourneyProduct[] {
  const seen = new Set<string>([self]);
  return paired.filter((p) => p && p.available && !seen.has(p.id) && !!seen.add(p.id));
}

export interface BundleEvidence {
  id: string;
  products: JourneyProduct[];
  /** Total price of the set after the Promotion. */
  bundlePrice: number;
}

export interface BundleTotals {
  total: number;
  saving: number;
}

/** Bundle_Offer: the set's total price and saving; null unless every product is available and the saving is above 0 (Req 11.14). */
export function bundleTotals(b: BundleEvidence | null): BundleTotals | null {
  if (!b || b.products.length < 2 || !isNum(b.bundlePrice) || b.products.some((p) => !p.available || !isNum(p.price))) return null;
  const separate = b.products.reduce((s, p) => s + p.price, 0);
  const saving = Math.round((separate - b.bundlePrice) * 100) / 100;
  return saving > 0 ? { total: b.bundlePrice, saving } : null;
}

export const RECENT_MAX = 10;

export function recentlyViewed(): string[] {
  const v = getJson<unknown>('sf.recent');
  return Array.isArray(v) ? v.filter((x): x is string => typeof x === 'string').slice(0, RECENT_MAX) : [];
}

/** Records a viewed product on the device: newest first, no repeats, at most 10 (Req 11.15). */
export function recordViewed(id: string): string[] {
  const next = [id, ...recentlyViewed().filter((x) => x !== id)].slice(0, RECENT_MAX);
  setJson('sf.recent', next);
  return next;
}

export const clearRecentlyViewed = (): void => removeItem('sf.recent');

export const FIRST_ORDER_ID = 'first-order-offer';

/** First_Order_Offer: only with a configured Promotion, once per session and not for 30 days after a close (Req 11.19). */
export const firstOrderOfferDue = (hasPromotion: boolean, now = Date.now()): boolean => hasPromotion && interruptionDue(FIRST_ORDER_ID, now);

export type StepState = 'done' | 'current' | 'upcoming';

/** Checkout_Progress: the state of each step; an unknown current step marks none as current (Req 11.20). */
export function checkoutStepStates(steps: readonly string[], current: string): { step: string; state: StepState }[] {
  const at = steps.indexOf(current);
  return steps.map((step, i) => ({ step, state: at < 0 ? 'upcoming' : i < at ? 'done' : i === at ? 'current' : 'upcoming' }));
}

export const STICKY_BELOW_PX = 768;

/** Sticky_Buy_Bar: below 768 px while the Buy_Box is out of view (Req 9.7). */
export const stickyBarVisible = (viewportWidth: number, buyBoxInView: boolean): boolean => viewportWidth < STICKY_BELOW_PX && !buyBoxInView;
