// The PDP's buying area as one Live_Island (Req 9.3-9.7, 9.10, 10.1-10.6, 11, 2.1): variant buttons and swatches, the price
// block, stock and delivery information, quantity, add-to-cart with its confirmation, and the Sticky_Buy_Bar.
// The static render holds the cheapest variant's price and the options; Live_Data then fills stock, prices and availability.
import type { ComponentChildren } from 'preact';
import { useEffect, useMemo, useRef, useState } from 'preact/hooks';
import PriceBlock from './PriceBlock';
import DeliveryDate from './DeliveryDate';
import Countdown from './Countdown';
import { LowStockNotice, PopularityNotice } from './SocialProof';
import { FreeDeliveryProgress, StickyBuyBar } from './BasketJourney';
import type { PriceBlockLabels } from './price-labels';
import type { DeliveryLabels, CountdownLabels } from './delivery-labels';
import type { SocialLabels } from './social-labels';
import type { JourneyLabels } from './journey-labels';
import type { PdpText } from '../lib/pdp-text';
import {
  displayVariant, imageIndexFor, initialSelection, isSellable, missingOption, pricesDiffer, stockStateOf, valueOutOfStock,
  variantFor, withVariantParam, type PdpModel, type Selection, type StockState,
} from '../lib/pdp';
import { applyAvailability, isProductUnavailable, pageLiveClient, syncHandleUrl } from '../lib/live-client';
import { formatMoney, type FormatLocale } from '../lib/format';
import { localizePath } from '../lib/shell-nav';
import { recordViewed } from '../lib/basket-journey';

export interface PdpBuyBoxProps {
  children?: ComponentChildren;
  locale: FormatLocale;
  text: PdpText;
  /** The product without its description, images and attributes. */
  model: PdpModel;
  liveUrl: string | null;
  switches: Record<string, boolean>;
  /** Components under a running Experiment: the variant that sees each one (see ExperimentSlot.astro). */
  showTo?: Record<string, 'treatment' | 'control'>;
  requireUnitPrice?: boolean;
  /** A price-on-request product of the B2B preset: Quotation and Enquiry controls replace the price and add-to-cart (Req 6.8). */
  priceOnRequest?: boolean;
  requestLinks?: { quotation: string; enquiry: string } | null;
  labels: { price: PriceBlockLabels; delivery: DeliveryLabels; countdown: CountdownLabels; social: SocialLabels; journey: JourneyLabels };
  freeDeliveryThreshold: number | null;
  countryCode: string;
  /** Order facts shown under the actions: who ships it, who sells it and how it is invoiced. */
  facts?: { shipsFrom: string; soldBy: string } | null;
  /** "Total for {qty}: {amount}". */
  totalLabel?: string;
  /** The line under the total: what the order desk confirms before dispatch. */
  panelNote?: string;
}

const COLOUR_OPTION = /^(colou?rs?|shade|रंग)$/i;
const CSS_COLOUR = /^(#[0-9a-f]{3,8}|[a-z]{3,20})$/i;
const MIN_QTY = 1;
const MAX_QTY = 100;
// Preact's JSX types declare `translate` as boolean; the attribute needs the string "no".
const NO_TRANSLATE: Record<string, string> = { translate: 'no' };
const fill = (s: string, p: Record<string, string | number>) => s.replace(/\{(\w+)\}/g, (m, k: string) => (k in p ? String(p[k]) : m));
const BUY_BOX_ID = 'pdp-buybox';
const optionButtonId = (optionId: string, i: number) => `pdp-opt-${optionId}-${i}`;

interface Added { title: string; qty: number; subtotal: number; currency: string }

/** Wraps a tested component so CSS shows it to one Experiment variant and the Exposure observer finds its area. */
function Slot({ k, showTo, children }: { k: string; showTo: Record<string, 'treatment' | 'control'>; children: ComponentChildren }) {
  return showTo[k] ? <div data-pm-component={k} data-pm-show={showTo[k]}>{children}</div> : <>{children}</>;
}

export default function PdpBuyBox({ children, locale, text, model, liveUrl, switches, showTo = {}, requireUnitPrice = false, priceOnRequest = false, requestLinks = null, labels, freeDeliveryThreshold, countryCode, facts = null, totalLabel = '', panelNote = '' }: PdpBuyBoxProps) {
  const [selection, setSelection] = useState<Selection>(() => initialSelection(model, null));
  const [qty, setQty] = useState(1);
  const [body, setBody] = useState<unknown>(null);
  const [missing, setMissing] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');
  const [added, setAdded] = useState<Added | null>(null);
  const addRef = useRef<HTMLButtonElement>(null);
  const hasMounted = useRef(false);

  // The `?variant=` of the address opens that variant (Req 9.4).
  useEffect(() => {
    const id = new URLSearchParams(location.search).get('variant');
    if (id) setSelection(initialSelection(model, id));
    recordViewed(model.id);
  }, [model]);

  // One shared Live_Data request per page: stock, availability and a changed handle (Req 1.11, 2.1).
  useEffect(() => {
    if (!liveUrl) return;
    let cancelled = false;
    pageLiveClient().load(liveUrl).then((res) => {
      if (cancelled || res.status !== 'ready') return;
      setBody(res.body);
      applyAvailability(document, res.body);
      syncHandleUrl(res.body, model.id, model.handle);
    }, () => undefined);
    return () => { cancelled = true; };
  }, [liveUrl, model.id, model.handle]);

  const chosen = variantFor(model, selection);
  const shown = displayVariant(model, chosen);
  const shownId = shown?.id ?? '';
  const stock = (variantId: string): StockState | null => stockStateOf(body, model.id, variantId);
  const state = chosen ? stock(chosen.id) : null;
  const unavailable = isProductUnavailable(body, model.id);
  const soldOut = !!chosen && state !== null && !isSellable(state);

  // The address and the gallery follow the variant (Req 9.4).
  useEffect(() => {
    if (!hasMounted.current) { hasMounted.current = true; return; }
    if (chosen) history.replaceState(history.state, '', location.pathname + withVariantParam(location.search, chosen.id) + location.hash);
    window.dispatchEvent(new CustomEvent('pdp:variant', { detail: { variantId: chosen?.id ?? null, imageIndex: imageIndexFor(model, chosen) } }));
  }, [chosen?.id]);

  const pick = (optionId: string, value: string) => {
    setSelection((s) => ({ ...s, [optionId]: value }));
    setMissing(null);
    setError('');
    setAdded(null);
  };

  const add = async (checkout = false) => {
    if (busy || unavailable) return;
    const miss = missingOption(model, selection);
    if (miss || !chosen) {
      // Name the missing option, move the focus to it and add nothing (Req 9.6).
      const o = miss ?? model.options[0];
      setMissing(o?.id ?? null);
      if (o) {
        const buttons = [...document.querySelectorAll<HTMLElement>(`[data-pdp-option="${CSS.escape(o.id)}"] button`)];
        const target = buttons[0];
        target?.scrollIntoView({ block: 'center' });
        target?.focus();
      }
      return;
    }
    if (soldOut) return;
    setBusy(true);
    setError('');
    try {
      const cart = await import('../lib/cart/store');
      const ok = await cart.addItem(model.id, chosen.id, qty);
      if (!ok) { setError(text.addError); return; }
      if (checkout) {
        location.assign(localizePath(locale, '/checkout'));
        return;
      }
      const s = cart.$cart.get();
      setAdded({ title: model.title, qty, subtotal: s.totals.subtotal, currency: s.currency });
    } catch {
      setError(text.addError);
    } finally {
      setBusy(false);
    }
  };

  const options = useMemo(() => model.options, [model]);
  const asRequest = priceOnRequest && !!requestLinks;
  const price = shown && !asRequest
    ? {
        amount: shown.price, currency: model.currency, priorPrice: shown.prior, mrp: shown.mrp,
        netQuantity: shown.netQuantity, netQuantityUnit: shown.netQuantityUnit,
        tiers: shown.tiers.length ? shown.tiers : null, requireUnitPrice,
      }
    : { amount: null, currency: model.currency };
  const showFrom = !chosen && pricesDiffer(model);
  const missingTitle = missing ? (options.find((o) => o.id === missing)?.title ?? '') : '';
  const statusText = !chosen || state === null ? '' : state === 'out_of_stock' ? text.outOfStock : state === 'backorder' ? text.backorder : text.inStock;
  const addDisabled = unavailable || busy || soldOut;

  return (
    <div class="pm-buybox" data-live-product={model.id}>
      <div class="pm-buybox__core" id={BUY_BOX_ID}>
        <Slot k="popularity_notice" showTo={showTo}><PopularityNotice locale={locale} labels={labels.social} liveUrl={liveUrl} productId={model.id} variantId={shownId} switchOn={switches.popularity_notice !== false} /></Slot>
        {showFrom && <p class="pm-buybox__from">{text.from}</p>}
        <Slot k="price_block" showTo={showTo}><PriceBlock
          key={shownId}
          locale={locale}
          initial={price}
          labels={labels.price}
          liveUrl={asRequest ? null : liveUrl}
          productId={model.id}
          variantId={shownId}
          switchOn={switches.price_block !== false}
          idPrefix="pdp-price"
        /></Slot>
        <Slot k="sale_countdown" showTo={showTo}><Countdown kind="sale" locale={locale} labels={labels.countdown} liveUrl={liveUrl} productId={model.id} variantId={shownId} switchOn={switches.sale_countdown !== false} currency={model.currency} /></Slot>

        <div id="pdp-variants">{children}</div>
        {options.map((o) => {
          const isColour = COLOUR_OPTION.test(o.title.trim());
          const gid = `pdp-opt-label-${o.id}`;
          return (
            <div class="pm-variants" role="group" aria-labelledby={gid} data-pdp-option={o.id} key={o.id}>
              <p class="pm-variants__label" id={gid}>
                {o.title}{selection[o.id] ? <>: <strong>{selection[o.id]}</strong></> : null}
              </p>
              <ul class="pm-variants__list">
                {o.values.map((v, i) => {
                  const on = selection[o.id] === v;
                  const oos = valueOutOfStock(model, o.id, v, stock);
                  const css = isColour && CSS_COLOUR.test(v) ? v : null;
                  const candidate = variantFor(model, { ...selection, [o.id]: v });
                  return (
                    <li key={v}>
                      <button
                        type="button"
                        id={optionButtonId(o.id, i)}
                        class={`pm-vbtn${css ? ' pm-vbtn--swatch' : ''}${oos ? ' is-oos' : ''}`}
                        aria-pressed={on}
                        aria-label={oos ? fill(text.outOfStockValue, { value: v }) : undefined}
                        data-value={v}
                        title={oos ? fill(text.outOfStockValue, { value: v }) : v}
                        onClick={() => pick(o.id, v)}
                      >
                        {css ? <span class="pm-vbtn__dot" data-colour={css} aria-hidden="true" /> : null}
                        <span class={css ? 'pm-visually-hidden' : undefined}>{v}</span>
                        {!asRequest && candidate?.price != null && !isColour && <small>{formatMoney(candidate.price,model.currency,locale)}</small>}
                      </button>
                    </li>
                  );
                })}
              </ul>
            </div>
          );
        })}
        <p class="pm-error pm-buybox__missing" role="alert" hidden={!missing}>
          {missing ? fill(text.missingOption, { option: missingTitle }) : ''}
        </p>

      </div>
      <aside class="pm-purchase-panel" id="pdp-delivery" aria-label={text.purchaseOptions}>
        {!asRequest && shown?.price != null && (
          <div class="pm-ref-amount">
            {showFrom && <small>{text.from} </small>}
            <span {...NO_TRANSLATE}>{formatMoney(shown.price, model.currency, locale)}</span>
            <small>{labels.price.inclTax}</small>
          </div>
        )}
        <div class="pm-buybox__status" aria-live="polite">
          {statusText && <p class={`pm-stock${soldOut ? ' pm-stock--out' : ''}`}>{statusText}</p>}
          {chosen?.sku ? <p class="pm-buybox__sku">{text.sku}: <span {...NO_TRANSLATE}>{chosen.sku}</span></p> : null}
          <Slot k="low_stock_notice" showTo={showTo}><LowStockNotice locale={locale} labels={labels.social} liveUrl={liveUrl} productId={model.id} variantId={shownId} switchOn={switches.low_stock_notice !== false} /></Slot>
          <Slot k="dispatch_countdown" showTo={showTo}><Countdown kind="dispatch" locale={locale} labels={labels.countdown} liveUrl={liveUrl} productId={model.id} variantId={shownId} switchOn={switches.dispatch_countdown !== false} currency={model.currency} /></Slot>
        </div>

        <Slot k="delivery_promise" showTo={showTo}><DeliveryDate locale={locale} labels={labels.delivery} liveUrl={liveUrl} productId={model.id} variantId={shownId} countryCode={countryCode} switchOn={switches.delivery_promise !== false} /></Slot>

        {asRequest && requestLinks && (
          <div class="pm-buybox__actions pm-buybox__actions--request">
            <a class="pm-button pm-button--primary" href={requestLinks.quotation} data-quotation-request>{text.quoteCta}</a>
            <a class="pm-button pm-button--secondary" href={requestLinks.enquiry} data-enquiry-request>{text.enquiryCta}</a>
          </div>
        )}
        <div class="pm-buybox__actions" hidden={asRequest}>
          <div class="pm-qty" role="group" aria-label={text.quantity}>
            <button type="button" class="pm-qty__btn" aria-label={text.decrease} disabled={qty <= 1} onClick={() => setQty((q) => Math.max(1, q - 1))}>−</button>
            <input
              class="pm-qty__input"
              type="number"
              inputMode="numeric"
              min={MIN_QTY}
              max={MAX_QTY}
              value={qty}
              aria-label={text.quantity}
              onInput={(e) => {
                const n = Math.trunc(Number((e.currentTarget as HTMLInputElement).value));
                setQty(Number.isFinite(n) ? Math.min(MAX_QTY, Math.max(1, n)) : 1);
              }}
            />
            <button type="button" class="pm-qty__btn" aria-label={text.increase} disabled={qty >= MAX_QTY} onClick={() => setQty((q) => Math.min(MAX_QTY, q + 1))}>+</button>
          </div>
          <button type="button" class="pm-button pm-button--primary pm-buybox__direct" disabled={addDisabled} onClick={() => void add(true)}>{text.buyNow}</button>
          <button
            type="button"
            ref={addRef}
            class="pm-button pm-button--secondary pm-buybox__add"
            data-add-to-cart
            data-product-id={model.id}
            data-variant-id={chosen?.id ?? ''}
            disabled={addDisabled}
            aria-disabled={addDisabled ? 'true' : undefined}
            onClick={() => void add()}
          >
            {busy ? text.adding : text.addToCart}
          </button>
        </div>
        {!asRequest && shown?.price != null && totalLabel && (
          <p class="pm-ref-total" {...NO_TRANSLATE}>{fill(totalLabel, { qty, amount: formatMoney(shown.price * qty, model.currency, locale) })}</p>
        )}
        {facts && (
          <dl class="pm-pdp-facts">
            <div><dt>{text.shipsFrom}</dt><dd>{facts.shipsFrom}</dd></div>
            <div><dt>{text.soldBy}</dt><dd>{facts.soldBy}</dd></div>
            <div><dt>{text.gstInvoice}</dt><dd>{text.gstWithHsn}</dd></div>
            <div><dt>{text.payment}</dt><dd>{text.paymentValue}</dd></div>
          </dl>
        )}
        {panelNote && <p class="pm-buybox__note">{panelNote}</p>}
        <p class="pm-unavailable-note pm-error" data-unavailable-note data-product-id={model.id} hidden={!unavailable}>{text.unavailable}</p>
        <p class="pm-error" role="alert" hidden={!error}>{error}</p>

        <div class="pm-added" role="status" aria-live="polite">
          {added && (
            <section class="pm-added__box" aria-label={text.addedTitle}>
              <h2 class="pm-added__title">{text.addedTitle}</h2>
              <p>{fill(text.addedLine, { qty: added.qty, title: added.title })}</p>
              <p>{fill(text.subtotal, { amount: formatMoney(added.subtotal, added.currency, locale) })}</p>
              <Slot k="free_delivery_progress" showTo={showTo}><FreeDeliveryProgress locale={locale} labels={labels.journey} currency={added.currency} subtotal={added.subtotal} threshold={freeDeliveryThreshold} switchOn={switches.free_delivery_progress !== false} /></Slot>
              <p class="pm-added__links">
                <a class="pm-button pm-button--secondary" href={localizePath(locale, '/cart')}>{text.viewCart}</a>{' '}
                <a class="pm-button pm-button--primary" href={localizePath(locale, '/checkout')}>{text.checkout}</a>{' '}
                <button type="button" class="pm-link" onClick={() => setAdded(null)}>{text.dismiss}</button>
              </p>
            </section>
          )}
        </div>
      </aside>
      <StickyBuyBar
        locale={locale}
        labels={labels.journey}
        currency={model.currency}
        buyBoxId={BUY_BOX_ID}
        price={shown?.price ?? null}
        onAdd={() => void add()}
        disabled={unavailable || busy || soldOut}
        switchOn={switches.sticky_buy_bar !== false && !asRequest}
      />
    </div>
  );
}
