/**
 * Allowlist HTML sanitizer for admin-authored rich text (Req 21.3).
 * Pure and dependency-free so the build and the Storefront_Worker share it.
 * Keeps p, br, ul, ol, li, strong, b, em, i and a (http, https, mailto, tel
 * or relative links only). Every other element and attribute is removed, and
 * every link gets rel="nofollow noopener". Output is deterministic and
 * unchanged by a second pass.
 */

const ALLOWED = new Set(['p', 'br', 'ul', 'ol', 'li', 'strong', 'b', 'em', 'i', 'a']);
const VOID = new Set(['br']);
/** Elements whose content is dropped along with the tag. */
const DROP_CONTENT = new Set([
  'script', 'style', 'iframe', 'frame', 'frameset', 'object', 'embed', 'noscript',
  'template', 'textarea', 'select', 'svg', 'math', 'title', 'head', 'applet', 'noembed', 'xmp',
]);
const SAFE_SCHEMES = new Set(['http', 'https', 'mailto', 'tel']);

const NAMED: Record<string, string> = {
  amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: '\u00a0',
};

function decodeEntities(s: string): string {
  return s.replace(/&(?:#(\d{1,7})|#[xX]([0-9a-fA-F]{1,6})|([a-zA-Z]+));?/g, (m, dec, hex, name) => {
    if (name) return Object.hasOwn(NAMED, name.toLowerCase()) && (m.endsWith(';') || name === 'amp' || name === 'lt' || name === 'gt')
      ? NAMED[name.toLowerCase()]
      : m;
    const cp = dec ? parseInt(dec, 10) : parseInt(hex, 16);
    if (!Number.isFinite(cp) || cp === 0 || cp > 0x10ffff || (cp >= 0xd800 && cp <= 0xdfff)) return '\ufffd';
    return String.fromCodePoint(cp);
  });
}

function escapeText(s: string): string {
  return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function escapeAttr(s: string): string {
  return escapeText(s).replace(/"/g, '&quot;');
}

/** Returns the cleaned URL, or null if the scheme is unsafe. */
function safeHref(raw: string): string | null {
  // Browsers ignore tabs, newlines and control characters inside the scheme.
  // eslint-disable-next-line no-control-regex
  const probe = decodeEntities(raw).replace(/[\u0000-\u001f\u007f-\u009f]/g, '').replace(/\s/g, '');
  if (probe === '') return null;
  const scheme = /^([a-zA-Z][a-zA-Z0-9+.-]*):/.exec(probe);
  if (scheme) return SAFE_SCHEMES.has(scheme[1].toLowerCase()) ? probe : null;
  if (probe.startsWith('//') || probe.startsWith('\\')) return null;
  // A colon before any / ? # would make a scheme we failed to parse; refuse it.
  if (/^[^/?#]*:/.test(probe)) return null;
  return probe;
}

const TAG_RE = /^<(\/?)([a-zA-Z][a-zA-Z0-9]*)((?:"[^"]*"|'[^']*'|[^>"'])*)>/;
const ATTR_RE = /([^\s"'<>/=]+)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'=<>`]+)))?/g;

function readHref(attrs: string): string | null {
  ATTR_RE.lastIndex = 0;
  let m: RegExpExecArray | null;
  while ((m = ATTR_RE.exec(attrs)) !== null) {
    if (m[1].toLowerCase() === 'href') return m[2] ?? m[3] ?? m[4] ?? '';
  }
  return null;
}

type Token = { kind: 'text'; text: string } | { kind: 'tag'; close: boolean; name: string; attrs: string };

function tokenize(html: string): Token[] {
  const out: Token[] = [];
  let i = 0;
  let text = '';
  const flush = () => {
    if (text) out.push({ kind: 'text', text });
    text = '';
  };
  while (i < html.length) {
    const lt = html.indexOf('<', i);
    if (lt === -1) {
      text += html.slice(i);
      break;
    }
    text += html.slice(i, lt);
    const rest = html.slice(lt);
    if (rest.startsWith('<!--')) {
      const end = rest.indexOf('-->', 4);
      i = end === -1 ? html.length : lt + end + 3;
      continue;
    }
    if (rest.startsWith('<!') || rest.startsWith('<?')) {
      const end = rest.indexOf('>');
      i = end === -1 ? html.length : lt + end + 1;
      continue;
    }
    const m = TAG_RE.exec(rest);
    if (!m) {
      text += '<';
      i = lt + 1;
      continue;
    }
    flush();
    out.push({ kind: 'tag', close: m[1] === '/', name: m[2].toLowerCase(), attrs: m[3] });
    i = lt + m[0].length;
  }
  flush();
  return out;
}

export function sanitizeHtml(input: string | null | undefined): string {
  if (!input) return '';
  const tokens = tokenize(String(input));
  const stack: string[] = [];
  let out = '';
  let skip: string | null = null;

  for (const t of tokens) {
    if (skip) {
      if (t.kind === 'tag' && t.close && t.name === skip) skip = null;
      continue;
    }
    if (t.kind === 'text') {
      out += escapeText(decodeEntities(t.text));
      continue;
    }
    if (DROP_CONTENT.has(t.name)) {
      if (!t.close) skip = t.name;
      continue;
    }
    if (!ALLOWED.has(t.name)) continue;
    if (t.close) {
      if (VOID.has(t.name)) continue;
      const idx = stack.lastIndexOf(t.name);
      if (idx === -1) continue;
      while (stack.length > idx) out += `</${stack.pop()}>`;
      continue;
    }
    if (t.name === 'a') {
      const raw = readHref(t.attrs);
      const href = raw === null ? null : safeHref(raw);
      if (href === null) continue;
      out += `<a href="${escapeAttr(href)}" rel="nofollow noopener">`;
      stack.push('a');
      continue;
    }
    if (VOID.has(t.name)) {
      out += `<${t.name}>`;
      continue;
    }
    out += `<${t.name}>`;
    stack.push(t.name);
  }
  while (stack.length) out += `</${stack.pop()}>`;
  return out;
}

/** Visible text only, for reviews and Enquiry text. Render it escaped. */
export function toPlainText(input: string | null | undefined): string {
  if (!input) return '';
  let out = '';
  let skip: string | null = null;
  for (const t of tokenize(String(input))) {
    if (skip) {
      if (t.kind === 'tag' && t.close && t.name === skip) skip = null;
      continue;
    }
    if (t.kind === 'text') out += decodeEntities(t.text);
    else if (DROP_CONTENT.has(t.name)) {
      if (!t.close) skip = t.name;
    }
  }
  return out;
}
