/**
 * Business_Presets and the layout functions (Req 6.1, 6.6). The seven files in `presets/` hold each preset's Sections,
 * PDP_Blocks, PLP filters, badge priority and attribute definitions. The store's layout comes from the `storefront.layout.*`
 * Store_Settings; a store that applied a preset but saved no list of its own gets the preset's list. Pure.
 */
import { DEFAULT_SECTIONS, normalizeSections, type Section } from './home';
import { isBadgeKey } from './badges';

type Obj = Record<string, unknown>;
const isObj = (x: unknown): x is Obj => !!x && typeof x === 'object' && !Array.isArray(x);

export const PRESET_KEYS = ['fashion', 'electronics', 'grocery', 'home', 'beauty', 'b2b', 'jewellery'] as const;
export type PresetKey = (typeof PRESET_KEYS)[number];
export const isPresetKey = (x: unknown): x is PresetKey => typeof x === 'string' && (PRESET_KEYS as readonly string[]).includes(x);

export interface AttributeDefinition {
  key: string;
  type: 'text' | 'number' | 'date' | 'boolean';
  unit: string | null;
  /** The PDP_Block that shows the attribute, or `declarations` for the Mandatory_Declarations list. */
  block: string;
  /** A required Mandatory_Declaration: the Site_Build warns about a published product that lacks it (Req 16.5). */
  mandatory_declaration: boolean;
}

export interface Preset {
  key: PresetKey;
  name: { en: string; hi: string };
  sections: { id: string; type: string; settings: Obj }[];
  pdp_blocks: string[];
  plp_filters: string[];
  badges: string[];
  attributes: AttributeDefinition[];
}

const files = import.meta.glob<Preset>('../../presets/*.json', { eager: true, import: 'default' });
export const PRESETS: Record<PresetKey, Preset> = Object.fromEntries(
  Object.values(files).map((p) => [p.key, p]),
) as Record<PresetKey, Preset>;

export const presetByKey = (key: unknown): Preset | null => (isPresetKey(key) ? (PRESETS[key] ?? null) : null);

/** Product_Card badge order when the store has no preset and no list of its own. */
export const DEFAULT_BADGE_PRIORITY: readonly string[] = ['sale', 'new', 'best_seller', 'low_stock', 'free_delivery', 'made_in_india'];
/** Facet groups of the PLP filter form, in display order. */
export const FILTER_GROUPS = ['categories', 'collections', 'types', 'tags', 'options', 'price'] as const;
/** The PDP_Block that asks for a unit sale price (Req 10.5). */
export const UNIT_PRICE_BLOCK = 'unit_price';

export interface Layout {
  preset: PresetKey | null;
  sections: Section[];
  /** PDP_Block keys in display order; empty means the PDP shows its default blocks. */
  pdpBlocks: string[];
  /** Facet groups in display order; empty means every group shows. */
  plpFilters: string[];
  badgePriority: string[];
  /** The unit sale price is shown with the price (Req 10.5), for presets whose PDP_Blocks include it. */
  requireUnitPrice: boolean;
}

const keyList = (v: unknown): string[] | null =>
  Array.isArray(v) ? v.filter((k): k is string => typeof k === 'string' && k.length > 0) : null;

/** The store's layout from the public Store_Settings (`storefront.layout.*`), with the applied preset filling any empty list. */
export function resolveLayout(settings: Obj): Layout {
  const preset = presetByKey(settings['storefront.layout.preset']);
  const own = (k: string) => {
    const l = keyList(settings[`storefront.layout.${k}`]);
    return l && l.length > 0 ? l : null;
  };
  const rawSections = settings['storefront.layout.sections'];
  const hasSections = Array.isArray(rawSections) && rawSections.length > 0;
  const sections = hasSections ? normalizeSections(rawSections) : preset ? normalizeSections(preset.sections) : DEFAULT_SECTIONS;
  const pdpBlocks = own('pdp_blocks') ?? preset?.pdp_blocks ?? [];
  const plpFilters = own('plp_filters') ?? preset?.plp_filters ?? [];
  const badgePriority = (own('badges') ?? preset?.badges ?? [...DEFAULT_BADGE_PRIORITY]).filter(isBadgeKey);
  return {
    preset: preset?.key ?? null,
    sections,
    pdpBlocks,
    plpFilters,
    badgePriority,
    requireUnitPrice: pdpBlocks.includes(UNIT_PRICE_BLOCK),
  };
}

/** Facet groups to leave out of the filter form: those the store's filter list does not name. An empty list hides none. */
export function hiddenFilterGroups(plpFilters: readonly string[]): string[] {
  if (plpFilters.length === 0) return [];
  return FILTER_GROUPS.filter((g) => !plpFilters.includes(g));
}

/** Facet groups in the store's order, for the filter form. */
export function orderedFilterGroups(plpFilters: readonly string[]): string[] {
  if (plpFilters.length === 0) return [...FILTER_GROUPS];
  return plpFilters.filter((g) => (FILTER_GROUPS as readonly string[]).includes(g));
}

/** A PDP_Block shows when the store's list names it (or names none) and the product has data for it (Req 6.6). */
export const pdpBlockShows = (blocks: readonly string[], key: string, hasData: boolean): boolean =>
  hasData && (blocks.length === 0 || blocks.includes(key));

/** The attributes a PDP_Block needs, from the applied preset. */
export function blockAttributes(preset: Preset | null, block: string): AttributeDefinition[] {
  return preset ? preset.attributes.filter((a) => a.block === block) : [];
}

/** The required Mandatory_Declarations of a preset (Req 16.5). */
export function requiredDeclarations(preset: Preset | null): AttributeDefinition[] {
  return preset ? preset.attributes.filter((a) => a.mandatory_declaration) : [];
}

export interface ListDiff { added: string[]; removed: string[]; moved: string[] }

/** What changes between two ordered key lists. */
export function diffKeys(from: readonly string[], to: readonly string[]): ListDiff {
  const added = to.filter((k) => !from.includes(k));
  const removed = from.filter((k) => !to.includes(k));
  const keptFrom = from.filter((k) => to.includes(k));
  const keptTo = to.filter((k) => from.includes(k));
  return { added, removed, moved: keptTo.filter((k, i) => keptFrom[i] !== k) };
}

export interface PresetPreview {
  preset: PresetKey;
  sections: ListDiff;
  pdp_blocks: ListDiff;
  plp_filters: ListDiff;
  badges: ListDiff;
}

/** What applying `preset` would change in the current layout (the same result the Backend's preview function gives). */
export function previewPreset(current: Obj, preset: Preset): PresetPreview {
  const ids = (v: unknown) => (Array.isArray(v) ? v.filter(isObj).map((s) => String(s.id ?? s.type ?? '')).filter(Boolean) : []);
  return {
    preset: preset.key,
    sections: diffKeys(ids(current['storefront.layout.sections']), ids(preset.sections)),
    pdp_blocks: diffKeys(keyList(current['storefront.layout.pdp_blocks']) ?? [], preset.pdp_blocks),
    plp_filters: diffKeys(keyList(current['storefront.layout.plp_filters']) ?? [], preset.plp_filters),
    badges: diffKeys(keyList(current['storefront.layout.badges']) ?? [], preset.badges),
  };
}
