// Free_Delivery_Progress, Savings_Summary, Goes_Well_With, Bundle_Offer, Recently_Viewed, First_Order_Offer,
// Checkout_Progress and Sticky_Buy_Bar (Req 9.7, 11.10, 11.11, 11.13-11.15, 11.19, 11.20).
// Each renders only from its evidence and nothing otherwise. Products reach the Cart only through the add control
// of that product or offer (the `onAdd` callbacks); no component adds anything on its own.
import { useEffect, useRef, useState } from 'preact/hooks';
import {
  bundleTotals, checkoutStepStates, clearRecentlyViewed, firstOrderOfferDue, freeDeliveryProgress, pairedProducts, recentlyViewed,
  savingsTotal, stickyBarVisible, FIRST_ORDER_ID, PERCENT_MAX, type BundleEvidence, type JourneyProduct, type SavingsLine,
} from '../lib/basket-journey';
import { formatMoney, type FormatLocale } from '../lib/format';
import { showInterruptionOnce } from '../lib/honesty';
import { fill } from './delivery-labels';
import type { JourneyLabels } from './journey-labels';

interface Common { locale: FormatLocale; labels: JourneyLabels; currency?: string; switchOn?: boolean }

/** Free_Delivery_Progress: the amount still needed with a progress bar, or the free-delivery statement once reached. */
export function FreeDeliveryProgress({ locale, labels, currency = 'INR', subtotal, threshold, switchOn = true }: Common & { subtotal: unknown; threshold: unknown }) {
  const p = switchOn ? freeDeliveryProgress(subtotal, threshold) : null;
  if (!p) return null;
  const text = p.reached ? labels.freeReached : fill(labels.freeProgress, { amount: formatMoney(p.remaining, currency, locale) });
  return (
    <div class="pm-free-delivery">
      <p>{text}</p>
      <progress value={p.percent} max={PERCENT_MAX} aria-label={text} />
    </div>
  );
}

/** Savings_Summary: shown only while the total saving is above 0. */
export function SavingsSummary({ locale, labels, currency = 'INR', lines, promotionDiscount = 0, switchOn = true }: Common & { lines: readonly SavingsLine[]; promotionDiscount?: number }) {
  const total = switchOn ? savingsTotal(lines, promotionDiscount) : null;
  if (total === null) return null;
  return <p class="pm-savings">{fill(labels.savings, { amount: formatMoney(total, currency, locale) })}</p>;
}

/** Goes_Well_With: each paired product has its own add control. */
export function GoesWellWith({ locale, labels, currency = 'INR', self, paired, onAdd, switchOn = true }: Common & { self: string; paired: readonly JourneyProduct[]; onAdd: (id: string) => void }) {
  const items = switchOn ? pairedProducts(self, paired) : [];
  if (!items.length) return null;
  return (
    <section class="pm-goes-well" aria-label={labels.goesWellTitle}>
      <h2>{labels.goesWellTitle}</h2>
      <ul>
        {items.map((p) => (
          <li key={p.id}>
            {p.url ? <a href={p.url}>{p.title}</a> : <span>{p.title}</span>}{' '}
            <span>{formatMoney(p.price, currency, locale)}</span>{' '}
            <button type="button" class="pm-btn" data-add-product={p.id} onClick={() => onAdd(p.id)}>{labels.add}</button>
          </li>
        ))}
      </ul>
    </section>
  );
}

/** Bundle_Offer: the set's total and saving, added only by the offer's own control. */
export function BundleOffer({ locale, labels, currency = 'INR', bundle, onAdd, switchOn = true }: Common & { bundle: BundleEvidence | null; onAdd: (ids: string[]) => void }) {
  const totals = switchOn ? bundleTotals(bundle) : null;
  if (!bundle || !totals) return null;
  return (
    <section class="pm-bundle" aria-label={labels.bundleTitle}>
      <h2>{labels.bundleTitle}</h2>
      <ul>{bundle.products.map((p) => <li key={p.id}>{p.title}</li>)}</ul>
      <p>{fill(labels.bundleTotal, { price: formatMoney(totals.total, currency, locale) })}</p>
      <p>{fill(labels.bundleSave, { amount: formatMoney(totals.saving, currency, locale) })}</p>
      <button type="button" class="pm-btn" data-add-bundle={bundle.id} onClick={() => onAdd(bundle.products.map((p) => p.id))}>{labels.bundleAdd}</button>
    </section>
  );
}

/** Recently_Viewed: up to 10 products from the device, newest first, with a control that clears the list. */
export function RecentlyViewed({ labels, resolve, switchOn = true }: Pick<Common, 'labels' | 'switchOn'> & { resolve: (ids: string[]) => JourneyProduct[] }) {
  const [ids, setIds] = useState<string[]>([]);
  useEffect(() => setIds(recentlyViewed()), []);
  const items = switchOn ? resolve(ids) : [];
  if (!items.length) return null;
  return (
    <section class="pm-recent" aria-label={labels.recentTitle}>
      <h2>{labels.recentTitle}</h2>
      <ul>{items.map((p) => <li key={p.id}>{p.url ? <a href={p.url}>{p.title}</a> : p.title}</li>)}</ul>
      <button type="button" class="pm-btn" onClick={() => { clearRecentlyViewed(); setIds([]); }}>{labels.recentClear}</button>
    </section>
  );
}

/** First_Order_Offer: a banner for the configured Promotion, shown once per session and not for 30 days after a close. */
export function FirstOrderOffer({ labels, promotionText, switchOn = true }: Pick<Common, 'labels' | 'switchOn'> & { promotionText: string | null }) {
  const ref = useRef<HTMLDivElement>(null);
  const has = switchOn && !!promotionText;
  const [open, setOpen] = useState(false);
  useEffect(() => {
    if (has && firstOrderOfferDue(true) && showInterruptionOnce(FIRST_ORDER_ID, ref.current)) setOpen(true);
  }, [has]);
  if (!has) return null;
  return (
    <div class="pm-first-order" ref={ref} hidden={!open} role="region" aria-label={labels.firstOrderTitle}>
      <p>{promotionText}</p>
      <button type="button" class="pm-btn" data-pm-close onClick={() => setOpen(false)}>{labels.firstOrderClose}</button>
    </div>
  );
}

/** Checkout_Progress: the steps with the current and the completed ones, on every checkout step. */
export function CheckoutProgress({ labels, steps, stepNames, current }: Pick<Common, 'labels'> & { steps: readonly string[]; stepNames: Record<string, string>; current: string }) {
  return (
    <ol class="pm-checkout-progress" aria-label={labels.progressLabel}>
      {checkoutStepStates(steps, current).map(({ step, state }) => (
        <li key={step} data-state={state} aria-current={state === 'current' ? 'step' : undefined}>
          {stepNames[step] ?? step}
          {state !== 'upcoming' && <span class="pm-visually-hidden"> ({state === 'done' ? labels.stepDone : labels.stepCurrent})</span>}
        </li>
      ))}
    </ol>
  );
}

/** Sticky_Buy_Bar: below 768 px while the element `buyBoxId` is out of view. Its add control is the page's own add action. */
export function StickyBuyBar({ locale, labels, currency = 'INR', buyBoxId, price, onAdd, disabled = false, switchOn = true }: Common & { buyBoxId: string; price: number | null; onAdd: () => void; disabled?: boolean }) {
  const [inView, setInView] = useState(true);
  const [width, setWidth] = useState(() => (typeof window === 'undefined' ? Infinity : window.innerWidth));
  useEffect(() => {
    const el = document.getElementById(buyBoxId);
    const io = el && typeof IntersectionObserver !== 'undefined' ? new IntersectionObserver((e) => setInView(e[0]?.isIntersecting ?? true)) : null;
    if (el) io?.observe(el);
    const onResize = () => setWidth(window.innerWidth);
    window.addEventListener('resize', onResize);
    return () => {
      io?.disconnect();
      window.removeEventListener('resize', onResize);
    };
  }, [buyBoxId]);
  if (!switchOn || !stickyBarVisible(width, inView)) return null;
  return (
    <div class="pm-sticky-buy">
      {price !== null && <span class="pm-sticky-price">{formatMoney(price, currency, locale)}</span>}
      <button type="button" class="pm-btn" data-add-to-cart disabled={disabled} onClick={onAdd}>{labels.stickyAdd}</button>
    </div>
  );
}
