/**
 * The starter backend stores placehold.co URLs for every product. Plusmark's real photography lives in
 * Cloudinary under public ids owned by the reference storefront. This module swaps a placeholder for the
 * matching photo only where the mapping is genuinely the same product or range; anything unmatched keeps
 * no image so the card shows a calm branded blank instead of a fake picture.
 */
import type { HomeData } from './home-data';

type Product = HomeData['products'][number];

const CLOUD = 'https://res.cloudinary.com/drt0rpkn2/image/upload';
const FOLDER = 'plusmark/products';

const IMAGE_MAP: Record<string, string> = {
  'magnetic-whiteboard': 'metallic-premium-magnetic-board',
  'non-magnetic-whiteboard': 'metallic-premium-white-board',
  'cork-notice-board': 'cork-notice-board',
  'a4-clipboard': 'laminate-mdf-base-clipboard',
  'mobile-whiteboard-stand': 'telescopic-stand',
  'tripod-easel-stand': 'three-leg-stand',
};

const isPlaceholder = (url: unknown): boolean => typeof url !== 'string' || url === '' || url.includes('placehold.co');

export function realImageUrl(handle: string): string | null {
  const id = IMAGE_MAP[handle];
  return id ? `${CLOUD}/f_auto,q_auto,w_1000,c_fill,g_auto/${FOLDER}/${id}` : null;
}

/** One product with real media when available, otherwise no media (never the placeholder). */
export function withRealMedia(product: Product): Product {
  const handle = String(product.handle ?? '');
  const images = Array.isArray(product.images) ? product.images : [];
  const alreadyReal = images.some((image) => image && typeof image === 'object' && !isPlaceholder((image as Record<string, unknown>).url));
  if (alreadyReal) return product;
  const url = realImageUrl(handle);
  return {
    ...product,
    images: url ? [{ id: `plusmark-${handle}`, url, width: 1000, height: 1000 }] : [],
    thumbnail: url,
  };
}
