// Sale_Countdown and Dispatch_Countdown (Req 11.6-11.8, 2.4; design "Countdowns").
// Shows only while Live_Data supplies a genuine end. Time comes from the server clock of the latest response, never the
// device clock. It ticks only while visible, hides at zero and refetches, and never restarts. The live region changes
// once a minute; a static end time is always readable.
import { useEffect, useRef, useState } from 'preact/hooks';
import '../styles/delivery.css';
import {
  dispatchCountdownMs, formatClock, formatEndTime, minuteOf, saleCountdownMs,
} from '../lib/delivery';
import { formatDuration, formatMoney, type FormatLocale } from '../lib/format';
import { fill, type CountdownLabels } from './delivery-labels';
import { useLiveDelivery, usePrefersReducedMotion, useVisible } from './use-live-delivery';

export interface CountdownProps {
  kind: 'sale' | 'dispatch';
  locale: FormatLocale;
  labels: CountdownLabels;
  /** Live_Data request URL, or null to use only `initialBody`. */
  liveUrl?: string | null;
  productId: string;
  variantId: string;
  /** A Live_Data response to start from (fixtures and tests). */
  initialBody?: unknown;
  /** Component_Switch for this component. */
  switchOn?: boolean;
  currency?: string;
}

export default function Countdown({
  kind, locale, labels, liveUrl = null, productId, variantId, initialBody = null, switchOn = true, currency = 'INR',
}: CountdownProps) {
  const ref = useRef<HTMLDivElement>(null);
  const live = useLiveDelivery(switchOn ? liveUrl : null, productId, variantId, switchOn ? initialBody : null);
  const visible = useVisible(ref);
  const reduced = usePrefersReducedMotion();
  const [now, setNow] = useState<number | null>(null);
  const [ended, setEnded] = useState<{ price: number } | null>(null);
  const [announce, setAnnounce] = useState('');
  const shown = useRef(false);
  const firstMinute = useRef<number | null>(null);
  const clock = live.clock;
  const data = live.status === 'ready' ? live.data : null;

  // One tick a second, only while the countdown is on screen. The server clock gives the time.
  useEffect(() => {
    if (!clock || !visible) return;
    setNow(clock.now());
    const id = setInterval(() => setNow(clock.now()), 1000);
    return () => clearInterval(id);
  }, [clock, visible]);

  const remaining =
    now === null || !data
      ? null
      : kind === 'sale'
        ? saleCountdownMs(now, data.countdown)
        : data.dispatch
          ? dispatchCountdownMs(now, data.dispatch, data.sellable)
          : null;

  // The countdown reached zero: show nothing more, keep the later price for a sale, and ask Live_Data again.
  useEffect(() => {
    if (remaining !== null) {
      shown.current = true;
      return;
    }
    if (!shown.current || !data) return;
    shown.current = false;
    if (kind === 'sale' && data.countdown) setEnded({ price: data.countdown.laterPrice });
    live.refetch();
  }, [remaining === null]);

  // A fresh response replaces the "ended" note; a countdown never restarts, so an end in the past stays hidden.
  useEffect(() => setEnded(null), [live.data]);

  // The live region changes only when the minute changes, and not when the countdown first appears.
  const minute = remaining === null ? null : minuteOf(remaining);
  useEffect(() => {
    if (minute === null) {
      firstMinute.current = null;
      return setAnnounce('');
    }
    if (firstMinute.current === null) {
      firstMinute.current = minute;
      return;
    }
    setAnnounce(fill(kind === 'sale' ? labels.srSale : labels.srDispatch, { time: formatDuration(minute * 60000, locale) }));
  }, [minute]);

  const body = () => {
    if (remaining !== null && data) {
      const time = reduced ? formatDuration(remaining, locale) : formatClock(remaining, locale);
      if (kind === 'dispatch') {
        return (
          <p class="pm-countdown__line">
            {fill(labels.dispatchWithin, { time: formatDuration(remaining, locale) })}
          </p>
        );
      }
      const sale = data.countdown;
      return (
        <>
          <p class="pm-countdown__line" aria-hidden="true">
            {fill(labels.saleEndsIn, { time })}
            {sale && <span class="pm-countdown__then">{fill(labels.saleThen, { price: formatMoney(sale.laterPrice, currency, locale) })}</span>}
          </p>
          {sale && data.dispatch && (
            <p class="pm-countdown__static">{fill(labels.saleEndsAt, { time: formatEndTime(sale.endsAt, locale, data.dispatch.timezone) })}</p>
          )}
          {sale && !data.dispatch && <p class="pm-countdown__static">{fill(labels.saleEndsAt, { time: formatEndTime(sale.endsAt, locale, 'Asia/Kolkata') })}</p>}
        </>
      );
    }
    if (ended) {
      return <p class="pm-countdown__static">{fill(labels.saleEnded, { price: formatMoney(ended.price, currency, locale) })}</p>;
    }
    return null;
  };

  return (
    <div class="pm-countdown" data-kind={kind} data-active={remaining !== null ? 'true' : 'false'} ref={ref}>
      {switchOn && body()}
      <span class="pm-visually-hidden" role="status" aria-live="polite">{announce}</span>
    </div>
  );
}
