// Build-time listing data of a category or collection page (Req 8): the first 24 products in the store's order, the total and
// the facets, all derived from the build's catalog export. The island (scripts/plp.ts) asks `store_list_products` for the rest.
import { PAGE_SIZE } from './plp-state';
import type { CategoryRow } from './pdp';

type Obj = Record<string, unknown>;
const isObj = (x: unknown): x is Obj => !!x && typeof x === 'object' && !Array.isArray(x);
const str = (x: unknown): string => (typeof x === 'string' ? x : '');
const arr = (x: unknown): unknown[] => (Array.isArray(x) ? x : []);

/** The category and all categories below it. */
export function categoryIdsBelow(rows: readonly CategoryRow[], id: string): Set<string> {
  const out = new Set<string>([id]);
  for (let grew = true; grew;) {
    grew = false;
    for (const r of rows) if (r.parent && out.has(r.parent) && !out.has(r.id)) { out.add(r.id); grew = true; }
  }
  return out;
}

export function productsIn(catalog: readonly Obj[], match: { categoryIds?: Set<string>; collectionId?: string }): Obj[] {
  return catalog.filter((p) => {
    if (match.categoryIds) return arr(p.categories).some((c) => isObj(c) && match.categoryIds?.has(str(c.id)));
    if (match.collectionId) return isObj(p.collection) && p.collection.id === match.collectionId;
    return true;
  });
}

/** The listing of one page: the first page of products, the total and the facets of all matching products. */
export function listingOf(products: readonly Obj[]): { items: Obj[]; total: number; facets: Record<string, unknown> } {
  const counts = (pick: (p: Obj) => { id: string; label: string }[]) => {
    const m = new Map<string, { id: string; label: string; count: number }>();
    for (const p of products) for (const { id, label } of pick(p)) {
      if (!id || !label) continue;
      const cur = m.get(id) ?? { id, label, count: 0 };
      cur.count++;
      m.set(id, cur);
    }
    return [...m.values()].sort((a, b) => a.label.localeCompare(b.label));
  };
  const cats = counts((p) => arr(p.categories).filter(isObj).map((c) => ({ id: str(c.id), label: str(c.name) })));
  const cols = counts((p) => (isObj(p.collection) ? [{ id: str(p.collection.id), label: str(p.collection.title) }] : []));
  const types = counts((p) => (isObj(p.type) ? [{ id: str(p.type.id), label: str(p.type.value) }] : []));
  const tags = counts((p) => arr(p.tags).filter(isObj).map((t) => ({ id: str(t.id), label: str(t.value) })));
  const optionMap = new Map<string, Map<string, number>>();
  for (const p of products) {
    const seen = new Set<string>();
    for (const o of arr(p.options).filter(isObj)) {
      const name = str(o.title);
      const used = new Set(arr(p.variants).filter(isObj).flatMap((v) => arr(v.options).filter(isObj).filter((x) => x.option_id === o.id).map((x) => str(x.value))));
      for (const v of arr(o.values).filter(isObj).map((x) => str(x.value)).filter((v) => v && used.has(v))) {
        const key = `${name}\u0000${v}`;
        if (seen.has(key)) continue;
        seen.add(key);
        const m = optionMap.get(name) ?? new Map<string, number>();
        m.set(v, (m.get(v) ?? 0) + 1);
        optionMap.set(name, m);
      }
    }
  }
  const prices = products.flatMap((p) => arr(p.variants).filter(isObj).map((v) => (isObj(v.price) ? Number(v.price.calculated_amount) : NaN))).filter((n) => Number.isFinite(n));
  return {
    items: products.slice(0, PAGE_SIZE) as Obj[],
    total: products.length,
    facets: {
      categories: cats.map((c) => ({ id: c.id, name: c.label, count: c.count })),
      collections: cols.map((c) => ({ id: c.id, title: c.label, count: c.count })),
      types: types.map((c) => ({ id: c.id, value: c.label, count: c.count })),
      tags: tags.map((c) => ({ id: c.id, value: c.label, count: c.count })),
      options: [...optionMap.entries()].map(([name, vals]) => ({ name, values: [...vals.entries()].map(([value, count]) => ({ value, count })) })),
      price: { min: prices.length ? Math.min(...prices) : null, max: prices.length ? Math.max(...prices) : null },
    },
  };
}
