// Delivery_Promise on the PDP (Req 9.10, 11.9): the PIN code form, the stored code, and the Delivery_Estimate as a date range.
// Dates come from the serviceability rule's transit days, the store's working days, holidays and cutoff, and the server clock.
// Without Live_Data the range falls back to the rule's working days, never an invented date.
import { useEffect, useId, useState } from 'preact/hooks';
import '../styles/delivery.css';
import { deliveryEstimate, formatEstimate, parsePostalCheck, type PostalCheck } from '../lib/delivery';
import { formatNumber, type FormatLocale } from '../lib/format';
import { getItem, removeItem, setItem } from '../lib/storage';
import { validatePin } from '../lib/validate';
import { fill, type DeliveryLabels } from './delivery-labels';
import { useLiveDelivery } from './use-live-delivery';

/** Length of an Indian postal code; a form limit, not Backend evidence. */
const PIN_LENGTH = 6;

export interface DeliveryDateProps {
  locale: FormatLocale;
  labels: DeliveryLabels;
  liveUrl?: string | null;
  productId: string;
  variantId: string;
  initialBody?: unknown;
  /** Two-letter country code of the store's region. */
  countryCode?: string;
  /** Component_Switch for the Delivery_Promise. */
  switchOn?: boolean;
  /** Store_API origin and publishable key override (fixtures); the build's public settings are used otherwise. */
  apiUrl?: string;
  apiKey?: string;
}

type Phase = { name: 'idle' } | { name: 'checking' } | { name: 'error' } | { name: 'done'; pin: string; check: PostalCheck };

export default function DeliveryDate({
  locale, labels, liveUrl = null, productId, variantId, initialBody = null, countryCode = 'in', switchOn = true, apiUrl, apiKey,
}: DeliveryDateProps) {
  const live = useLiveDelivery(switchOn ? liveUrl : null, productId, variantId, switchOn ? initialBody : null);
  const [phase, setPhase] = useState<Phase>({ name: 'idle' });
  const [value, setValue] = useState('');
  const [invalid, setInvalid] = useState(false);
  const id = useId();

  const run = async (raw: string) => {
    const v = validatePin(raw);
    if (!v.ok) return setInvalid(true);
    setInvalid(false);
    setPhase({ name: 'checking' });
    try {
      const { createStoreApi } = await import('../lib/store-api');
      const api = createStoreApi(apiUrl ? { url: apiUrl, key: apiKey ?? 'sb_publishable_fixture' } : {});
      const check = parsePostalCheck(await api.call('store_check_postal_code', { p_country_code: countryCode, p_postal_code: v.value }));
      if (!check) return setPhase({ name: 'error' });
      setItem('sf.pin', v.value);
      setPhase({ name: 'done', pin: v.value, check });
    } catch {
      setPhase({ name: 'error' });
    }
  };

  // A stored code applies on later PDPs (Req 9.10).
  useEffect(() => {
    if (!switchOn) return;
    const stored = getItem('sf.pin');
    if (stored && validatePin(stored).ok) {
      setValue(stored);
      void run(stored);
    }
  }, [switchOn]);

  if (!switchOn) return <div class="pm-delivery" hidden />;

  const change = () => {
    removeItem('sf.pin');
    setPhase({ name: 'idle' });
  };

  const result = () => {
    if (phase.name !== 'done') return null;
    const { check } = phase;
    if (check.serviceable === false) return <p class="pm-delivery__error">{labels.notServiceable}</p>;
    if (check.serviceable === null || check.etaMin === null || check.etaMax === null) {
      return <p class="pm-delivery__note">{check.serviceable === null ? labels.unknownCountry : labels.noEstimate}</p>;
    }
    const data = live.status === 'ready' ? live.data : null;
    const est = data?.dispatch && live.clock ? deliveryEstimate(live.clock.now(), data.dispatch, check.etaMin, check.etaMax) : null;
    const line =
      est && data?.dispatch && live.clock
        ? fill(labels.between, { range: formatEstimate(est, locale, live.clock.now(), data.dispatch.timezone) })
        : check.etaMin === check.etaMax
          ? fill(labels.workingDaysOne, { days: formatNumber(check.etaMax, locale) })
          : fill(labels.workingDays, { min: formatNumber(check.etaMin, locale), max: formatNumber(check.etaMax, locale) });
    return (
      <>
        <p class="pm-delivery__date">{line}</p>
        <p class="pm-delivery__note">{check.cod ? labels.codYes : labels.codNo}</p>
      </>
    );
  };

  const inputId = `${id}-pin`;
  const hintId = `${id}-hint`;
  return (
    <div class="pm-delivery" data-state={phase.name}>
      {phase.name === 'done' ? (
        <p class="pm-delivery__head">
          <span class="pm-delivery__forpin">{fill(labels.forPin, { pin: phase.pin })}</span>
          <button type="button" class="pm-delivery__link" onClick={change}>{labels.change}</button>
        </p>
      ) : (
        <form
          class="pm-delivery__form"
          onSubmit={(e) => {
            e.preventDefault();
            void run(value);
          }}
        >
          <label class="pm-delivery__title" for={inputId}>{labels.pinLabel}</label>
          <div class="pm-delivery__row">
            <input
              id={inputId}
              class="pm-delivery__input"
              type="text"
              inputMode="numeric"
              autoComplete="postal-code"
              maxLength={PIN_LENGTH}
              value={value}
              aria-invalid={invalid}
              aria-describedby={hintId}
              onInput={(e) => setValue((e.currentTarget as HTMLInputElement).value)}
            />
            <button type="submit" class="pm-delivery__btn" disabled={phase.name === 'checking'}>
              {phase.name === 'checking' ? labels.checking : labels.check}
            </button>
          </div>
          <p id={hintId} class={invalid ? 'pm-delivery__error' : 'pm-delivery__hint'}>{invalid ? labels.pinInvalid : labels.pinHint}</p>
        </form>
      )}
      <div role="status" aria-live="polite">
        {phase.name === 'error' && <p class="pm-delivery__error">{labels.error}</p>}
        {result()}
      </div>
    </div>
  );
}
