// Live_Island client (design KD-3; Req 1.11, 1.12, 2.1, 2.2, 2.4, 2.7, 20.8).
// One Live_Data request per page: islands ask for the same URL and share one answer. The Worker is tried first; when it
// fails, the client calls `api.store_live_data` on Supabase. A signed-in Registered_Customer's prices come from
// `api.store_price_for_customer` (never from a shared cache). After 8 seconds, or once an answer is older than the
// Live_Data_Max_Age, the result is `stale` and islands keep their built values (Req 2.4). Islands keep the box of their
// built value, so nothing here changes layout (Req 2.2).

export const LIVE_TIMEOUT_MS = 8000;
export const DEFAULT_MAX_AGE_MS = 60_000;
export const LIVE_PATH = '/_live/v1/products';
const MAX_IDS = 60;

export interface LiveParams {
  ids: string[];
  region: string | null;
  channel: string | null;
  currency: string | null;
}

export interface LiveResult {
  /** ready: current evidence; stale: no usable answer in time, so built values stay. */
  status: 'ready' | 'stale';
  body: unknown;
  /** Where the answer came from. */
  source: 'worker' | 'supabase' | 'none';
  /** True when the signed-in prices of `store_price_for_customer` were applied. */
  customerPrices: boolean;
  fetchedAt: number;
  maxAgeMs: number;
}

export interface LiveClientDeps {
  fetch?: typeof fetch;
  /** The signed-in session's access token; null or undefined when nobody is signed in. */
  getAccessToken?: () => string | null | undefined;
  /** Calls a Store_API function (`api.<name>` on Supabase); defaults to the shared Store_API client. */
  call?: (fn: string, args: Record<string, unknown>) => Promise<unknown>;
  /** Monotonic milliseconds. */
  now?: () => number;
  timeoutMs?: number;
}

// --- Pure helpers ---------------------------------------------------------------------------------------------------

/** The page's single Live_Data URL: sorted, de-duplicated IDs, at most 60. */
export function buildLiveUrl(p: LiveParams, base = LIVE_PATH): string {
  const ids = [...new Set(p.ids.filter(Boolean))].sort().slice(0, MAX_IDS);
  const q = new URLSearchParams({ ids: ids.join(',') });
  if (p.region) q.set('region', p.region);
  if (p.channel) q.set('channel', p.channel);
  if (p.currency) q.set('currency', p.currency);
  return `${base}?${q.toString()}`;
}

export function parseLiveUrl(url: string): LiveParams {
  const q = new URL(url, 'https://x.invalid').searchParams;
  return {
    ids: (q.get('ids') ?? '').split(',').map((s) => s.trim()).filter(Boolean),
    region: q.get('region') || null,
    channel: q.get('channel') || null,
    currency: q.get('currency') || null,
  };
}

/** Reads `data-live-product` from every Live_Island on the page into one URL; null when the page has none. */
export function collectLiveUrl(root: ParentNode, region: string | null, channel: string | null = null, currency: string | null = null): string | null {
  const ids = [...root.querySelectorAll('[data-live-product]')].map((e) => e.getAttribute('data-live-product') ?? '');
  const clean = ids.filter(Boolean);
  return clean.length ? buildLiveUrl({ ids: clean, region, channel, currency }) : null;
}

type Obj = Record<string, unknown>;
const isObj = (x: unknown): x is Obj => !!x && typeof x === 'object' && !Array.isArray(x);

export function isLiveData(body: unknown): body is Obj & { products: unknown[] } {
  return isObj(body) && Array.isArray(body.products);
}

function findProduct(body: unknown, productId: string): Obj | null {
  if (!isLiveData(body)) return null;
  return (body.products.find((p) => isObj(p) && p.id === productId) as Obj | undefined) ?? null;
}

/** True when Live_Data says the product was unpublished or deleted after the build (Req 1.11). Absent means unknown. */
export function isProductUnavailable(body: unknown, productId: string): boolean {
  return findProduct(body, productId)?.available === false;
}

/** The current handle when it differs from `currentHandle`; null when unchanged or unknown. */
export function newHandleOf(body: unknown, productId: string, currentHandle: string): string | null {
  const p = findProduct(body, productId);
  if (!p || p.available === false || typeof p.handle !== 'string' || !p.handle) return null;
  return p.handle !== currentHandle ? p.handle : null;
}

/** Replaces the product handle in a product path (`/product/<handle>` or `/hi/product/<handle>`); keeps query and hash. */
export function replaceHandleInPath(path: string, oldHandle: string, newHandle: string): string | null {
  const m = /^([^?#]*)([?#].*)?$/.exec(path);
  const segs = (m?.[1] ?? path).split('/');
  const i = segs.lastIndexOf(encodeURIComponent(oldHandle));
  const at = i >= 0 ? i : segs.lastIndexOf(oldHandle);
  if (at < 1 || segs[at - 1] !== 'product') return null;
  segs[at] = encodeURIComponent(newHandle);
  return segs.join('/') + (m?.[2] ?? '');
}

/** Replaces the address-bar URL (no history entry) when Live_Data reports a new handle. Returns the new path or null. */
export function syncHandleUrl(
  body: unknown,
  productId: string,
  currentHandle: string,
  loc: Pick<Location, 'pathname' | 'search' | 'hash'> = location,
  hist: Pick<History, 'replaceState' | 'state'> = history,
): string | null {
  const next = newHandleOf(body, productId, currentHandle);
  if (!next) return null;
  const path = replaceHandleInPath(loc.pathname + loc.search + loc.hash, currentHandle, next);
  if (!path) return null;
  hist.replaceState(hist.state, '', path);
  return path;
}

/** Disables add-to-cart controls of an unavailable product and shows its note (Req 1.11). Returns the controls changed. */
export function applyAvailability(root: ParentNode, body: unknown): number {
  let n = 0;
  root.querySelectorAll('[data-add-to-cart][data-product-id]').forEach((el) => {
    const id = el.getAttribute('data-product-id') ?? '';
    if (!isProductUnavailable(body, id)) return;
    el.setAttribute('disabled', '');
    el.setAttribute('aria-disabled', 'true');
    n++;
  });
  root.querySelectorAll('[data-unavailable-note][data-product-id]').forEach((el) => {
    if (isProductUnavailable(body, el.getAttribute('data-product-id') ?? '')) el.removeAttribute('hidden');
  });
  return n;
}

/** Overlays `store_price_for_customer` rows onto Live_Data. A changed price ends the anonymous Prior_Price and countdown. */
export function applyCustomerPrices(body: unknown, prices: unknown): unknown {
  if (!isLiveData(body) || !isObj(prices) || !Array.isArray(prices.prices)) return body;
  const byVariant = new Map<string, Obj>();
  for (const r of prices.prices) if (isObj(r) && typeof r.variant_id === 'string') byVariant.set(r.variant_id, r);
  if (!byVariant.size) return body;
  const products = body.products.map((p) => {
    if (!isObj(p) || !Array.isArray(p.variants)) return p;
    const variants = p.variants.map((v) => {
      if (!isObj(v) || typeof v.id !== 'string') return v;
      const r = byVariant.get(v.id);
      if (!r || typeof r.calculated_amount !== 'number') return v;
      const prev = isObj(v.price) ? v.price : {};
      const changed = prev.amount !== r.calculated_amount;
      return {
        ...v,
        price: { ...prev, amount: r.calculated_amount, currency_code: r.currency_code ?? prev.currency_code, is_tax_inclusive: r.is_tax_inclusive ?? prev.is_tax_inclusive },
        prior_price: changed ? null : v.prior_price ?? null,
        countdown: changed ? null : v.countdown ?? null,
        customer_price: true,
      };
    });
    return { ...p, variants };
  });
  return { ...body, products };
}

function maxAgeMsOf(body: unknown): number {
  const s = isObj(body) ? body.max_age_seconds : undefined;
  return typeof s === 'number' && s > 0 ? s * 1000 : DEFAULT_MAX_AGE_MS;
}

// --- Client ---------------------------------------------------------------------------------------------------------

export interface LiveClient {
  /** The shared answer for a Live_Data URL: one request per page, reused while it is younger than the maximum age. */
  load(url: string): Promise<LiveResult>;
  /** True when the result is older than its Live_Data_Max_Age. */
  isExpired(r: LiveResult): boolean;
  /** Forgets answers, so the next `load` asks again. */
  reset(): void;
}

function withDeadline<T>(p: Promise<T>, ms: number): Promise<T> {
  return new Promise<T>((resolve, reject) => {
    const t = setTimeout(() => reject(new Error('timeout')), Math.max(0, ms));
    p.then((v) => { clearTimeout(t); resolve(v); }, (e) => { clearTimeout(t); reject(e); });
  });
}

export function createLiveClient(deps: LiveClientDeps = {}): LiveClient {
  const now = deps.now ?? (() => performance.now());
  const timeoutMs = deps.timeoutMs ?? LIVE_TIMEOUT_MS;
  const memo = new Map<string, { promise: Promise<LiveResult>; signedIn: boolean }>();

  const staleResult = (): LiveResult => ({ status: 'stale', body: null, source: 'none', customerPrices: false, fetchedAt: now(), maxAgeMs: DEFAULT_MAX_AGE_MS });

  async function defaultCall(fn: string, args: Record<string, unknown>): Promise<unknown> {
    const { createStoreApi } = await import('./store-api');
    return createStoreApi({ getAccessToken: deps.getAccessToken, fetch: deps.fetch, timeoutMs, retries: 0 }).call(fn, args);
  }
  const call = deps.call ?? defaultCall;

  async function fromWorker(url: string, deadline: number): Promise<unknown> {
    const doFetch = deps.fetch ?? globalThis.fetch;
    const ctl = new AbortController();
    const timer = setTimeout(() => ctl.abort(), Math.max(0, deadline - now()));
    try {
      // The Worker never caches an answer for a request with an Authorization header, so the anonymous request carries none.
      const res = await doFetch(url, { signal: ctl.signal, headers: { Accept: 'application/json' } });
      if (!res.ok) throw new Error(`live ${res.status}`);
      const body: unknown = await res.json();
      if (!isLiveData(body)) throw new Error('live shape');
      return body;
    } finally {
      clearTimeout(timer);
    }
  }

  async function fromSupabase(p: LiveParams): Promise<unknown> {
    const body = await call('store_live_data', {
      // PostgREST reads a text[] in a GET query as a Postgres array literal.
      p_product_ids: `{${p.ids.map((i) => `"${i.replace(/(["\\])/g, '\\$1')}"`).join(',')}}`,
      p_region_id: p.region ?? undefined,
      p_sales_channel_id: p.channel ?? undefined,
      p_currency_code: p.currency ?? undefined,
    });
    if (!isLiveData(body)) throw new Error('live shape');
    return body;
  }

  async function run(url: string, signedIn: boolean): Promise<LiveResult> {
    const params = parseLiveUrl(url);
    if (!params.ids.length) return staleResult();
    const deadline = now() + timeoutMs;
    let body: unknown;
    let source: 'worker' | 'supabase' = 'worker';
    try {
      body = await fromWorker(url, deadline);
    } catch {
      // Req 1.12: the Worker failed or is over its limit; read Live_Data from the Store_API directly, inside the 8 seconds.
      try {
        body = await withDeadline(fromSupabase(params), deadline - now());
        source = 'supabase';
      } catch {
        return staleResult();
      }
    }
    let customerPrices = false;
    if (signedIn) {
      const variantIds = ((body as { products: unknown[] }).products)
        .flatMap((p) => (isObj(p) && Array.isArray(p.variants) ? p.variants : []))
        .map((v) => (isObj(v) && typeof v.id === 'string' ? v.id : ''))
        .filter(Boolean)
        .slice(0, 100);
      if (variantIds.length) {
        try {
          const prices = await withDeadline(
            call('store_price_for_customer', {
              p_variant_ids: variantIds,
              p_region_id: params.region ?? undefined,
              p_currency_code: params.currency ?? undefined,
              p_sales_channel_id: params.channel ?? undefined,
            }),
            deadline - now(),
          );
          const next = applyCustomerPrices(body, prices);
          customerPrices = next !== body;
          body = next;
        } catch {
          // The Cart confirms the price (Req 2.4); the anonymous price stays.
        }
      }
    }
    return { status: 'ready', body, source, customerPrices, fetchedAt: now(), maxAgeMs: maxAgeMsOf(body) };
  }

  const isExpired = (r: LiveResult) => r.status !== 'ready' || now() - r.fetchedAt > r.maxAgeMs;

  return {
    isExpired,
    reset: () => memo.clear(),
    load(url) {
      const signedIn = !!deps.getAccessToken?.();
      const hit = memo.get(url);
      if (hit && hit.signedIn === signedIn) return hit.promise;
      const promise = run(url, signedIn).catch(staleResult);
      memo.set(url, { promise, signedIn });
      // A stale or expired answer must not be reused: forget it so the next call asks again.
      void promise.then((r) => {
        if (r.status !== 'ready') memo.delete(url);
        else setTimeout(() => memo.get(url)?.promise === promise && memo.delete(url), r.maxAgeMs);
      });
      return promise;
    },
  };
}

/** The page's shared client. Islands call `pageLiveClient().load(url)`; the sign-in code may set the token reader. */
let page: LiveClient | null = null;
let tokenReader: (() => string | null | undefined) | undefined;
export function setLiveAccessToken(read: (() => string | null | undefined) | undefined): void {
  tokenReader = read;
  page = null;
}
export function pageLiveClient(): LiveClient {
  return (page ??= createLiveClient({ getAccessToken: () => tokenReader?.() }));
}
