// Image markup: <picture> data with WebP and JPEG srcsets, sizes, dimensions and loading order (Req 3.4, 3.5, 3.6, 3.8).

export const IMAGE_WIDTHS = [160, 320, 480, 640, 800, 1024, 1280, 1600] as const;

/** `sizes` values per slot. */
export const IMAGE_SLOTS = {
  card: '(min-width: 1024px) 25vw, (min-width: 768px) 33vw, 50vw',
  hero: '100vw',
  gallery: '(min-width: 1024px) 50vw, 100vw',
  thumb: '80px',
  rail: '(min-width: 1024px) 20vw, 45vw',
} as const;
export type ImageSlot = keyof typeof IMAGE_SLOTS;

export interface ImageSource {
  /** Image ID and content hash, both part of the variant URL. */
  id: string;
  hash: string;
  /** Original size, giving the aspect ratio. */
  width: number;
  height: number;
  /** Widths of the variants the build produced; empty when none exist yet. */
  variants?: readonly number[];
  /** Original URL, used while the image has no variants. */
  originalUrl?: string;
  alt: string;
}

export interface PictureData {
  webpSrcset: string;
  jpegSrcset: string;
  /** 1× candidate for Save-Data, as `<url> <w>w`-free single URLs. */
  sdWebp: string;
  sdJpeg: string;
  src: string;
  sizes: string;
  width: number;
  height: number;
  alt: string;
  loading: 'lazy' | undefined;
  decoding: 'async' | undefined;
  fetchpriority: 'high' | undefined;
  /** False when the image has no variants and uses its original URL. */
  hasVariants: boolean;
}

export function variantUrl(mediaBase: string, id: string, hash: string, width: number, ext: 'webp' | 'jpg'): string {
  return `${mediaBase.replace(/\/+$/, '')}/${id}/${hash}/${width}.${ext}`;
}

/** Variant widths to list: those built, never more than the original's width unless it is the only one. */
function usableWidths(img: ImageSource): number[] {
  const all = [...new Set(img.variants ?? [])].filter((w) => w > 0).sort((a, b) => a - b);
  const within = all.filter((w) => w <= img.width);
  return within.length ? within : all.slice(0, 1);
}

/** Width of the 1× candidate: the smallest variant that covers the slot's CSS width at 1× density, else the largest. */
export function saveDataWidth(widths: readonly number[], cssWidth: number): number {
  return widths.find((w) => w >= cssWidth) ?? widths[widths.length - 1];
}

/** Approximate CSS width of a slot on a 360 px phone, used to pick the Save-Data candidate. */
const SD_CSS_WIDTH: Record<ImageSlot, number> = { card: 180, hero: 360, gallery: 360, thumb: 80, rail: 162 };

export function pictureData(
  img: ImageSource,
  opts: { mediaBase: string; slot: ImageSlot; priority?: boolean },
): PictureData {
  const widths = usableWidths(img);
  const hasVariants = widths.length > 0;
  const ratio = img.width > 0 && img.height > 0 ? img.height / img.width : 1;
  const list = (ext: 'webp' | 'jpg') =>
    widths.map((w) => `${variantUrl(opts.mediaBase, img.id, img.hash, w, ext)} ${w}w`).join(', ');
  const sd = hasVariants ? saveDataWidth(widths, SD_CSS_WIDTH[opts.slot]) : 0;
  const largest = widths[widths.length - 1];
  return {
    webpSrcset: list('webp'),
    jpegSrcset: list('jpg'),
    sdWebp: hasVariants ? variantUrl(opts.mediaBase, img.id, img.hash, sd, 'webp') : '',
    sdJpeg: hasVariants ? variantUrl(opts.mediaBase, img.id, img.hash, sd, 'jpg') : '',
    src: hasVariants ? variantUrl(opts.mediaBase, img.id, img.hash, largest, 'jpg') : (img.originalUrl ?? ''),
    sizes: IMAGE_SLOTS[opts.slot],
    width: img.width,
    height: Math.round(img.width * ratio) || img.height,
    alt: img.alt,
    loading: opts.priority ? undefined : 'lazy',
    decoding: opts.priority ? undefined : 'async',
    fetchpriority: opts.priority ? 'high' : undefined,
    hasVariants,
  };
}

/** Inline `<head>` script: with Save-Data, swap each lazy image's srcset for its `data-sd` 1× candidate before it loads. */
export const SAVE_DATA_SCRIPT = `(function(){var c=navigator.connection;if(!c||!c.saveData)return;function f(e){if(e.nodeType!==1)return;var l=e.matches&&e.matches('img[loading=lazy],picture source')?[e]:[];if(e.querySelectorAll)l=l.concat([].slice.call(e.querySelectorAll('img[loading=lazy],picture source')));l.forEach(function(n){var p=n.tagName==='SOURCE'?n.parentNode.querySelector('img'):n;if(!p||p.getAttribute('loading')!=='lazy')return;var d=n.getAttribute('data-sd');if(d){n.setAttribute('srcset',d);n.removeAttribute('sizes');if(n===p)n.removeAttribute('data-sd')}})}new MutationObserver(function(m){m.forEach(function(r){[].forEach.call(r.addedNodes,f)})}).observe(document,{childList:true,subtree:true})})();`;
