// Build-time read of the public Store_Settings that scripts/build-data wrote to src/data/settings.json.
// Without the file (a fresh checkout) the settings are empty and every legal page shows its "not published yet" text.
const generated = import.meta.glob<Record<string, unknown>>('../data/settings.json', { eager: true, import: 'default' });

export function loadSettings(): Record<string, unknown> {
  return Object.values(generated)[0] ?? {};
}
